function richLesson(title: string, introduction: string, outcomes: string[], concepts: Array<{ heading: string; body: string; code?: { language: string; caption: string; value: string; output?: string } }>, practice: string[], check: string[], resources: LearningResource[] = resourcesByDjangoLesson[title] ?? [djangoDocs, drfDocs]): Lesson {
  const id = `django-and-api-engineering-${slug(title)}`;
  const blocks: LessonBlock[] = [
    { type: "heading", id: "introduction", text: "Introduction" },
    { type: "paragraph", text: introduction },
    { type: "heading", id: "outcomes", text: "Learning outcomes" },
    { type: "list", items: outcomes },
  ];
  for (const concept of concepts) {
    blocks.push({ type: "heading", id: slug(concept.heading), text: concept.heading });
    blocks.push({ type: "paragraph", text: concept.body });
    if (concept.code) blocks.push({ type: "code", language: concept.code.language, caption: concept.code.caption, code: concept.code.value, output: concept.code.output });
  }
  blocks.push({ type: "heading", id: "assignment", text: "Assignment" });
  blocks.push({ type: "list", ordered: true, items: practice });
  blocks.push({ type: "resources", title: "Required and supporting reading", resources });
  blocks.push({ type: "heading", id: "knowledge-check", text: "Knowledge check" });
  blocks.push({ type: "list", items: check });

  return {
    id,
    title,
    activities: [
      { id: `${id}-concepts`, title: djangoActivityNames[title]?.[0] ?? `Understand ${title}`, estimatedMinutes: 50, content: { type: "reading", body: blocks.filter((block) => block.type === "paragraph").map((block) => block.text).join("\n\n") || introduction, blocks } },
      { id: `${id}-practice`, title: djangoActivityNames[title]?.[1] ?? `Practise ${title}`, estimatedMinutes: 55, content: { type: "practical", objective: `Apply ${title} to the evolving Steward API with observable behavior and evidence.`, scenario: "Continue the same Steward codebase. Preserve useful implementation, notes and decisions for later Builder modules.", instructions: practice, deliverables: ["Working Steward implementation or focused experiment", "Reproducible evidence note containing the command/request or setup, observed result, one failure path and one design decision"], completionCriteria: ["Another learner could reproduce the demonstrated behavior from the recorded setup and action.", "The implementation is connected to Steward rather than a disposable tutorial domain.", "At least one boundary/failure case is exercised and its observed result is recorded.", "The learner can explain what Django/DRF is doing rather than only copy framework syntax."] } },
      { id: `${id}-check`, title: djangoActivityNames[title]?.[2] ?? `Check ${title}`, estimatedMinutes: 10, content: { type: "reflection", prompt: check.join("\n\n") } },
    ],
  };
}

export const djangoAndApiRichLessons: Lesson[] = [
  richLesson("Django from Zero: A Running HTTP Endpoint", "Begin with a real HTTP process before learning framework abstractions. Use a scratch Python virtual environment, wire a route, and observe status codes. The earlier Web/API material already taught the HTTP exchange; this lesson explains Django's Python side.", ["Isolate a Python/Django installation and identify the active interpreter.","Build a complete URL/view endpoint without a database or DRF.","Verify successful HTTP and intentional failures with curl."], [{"heading":"Set up an identifiable interpreter and project","body":"In an empty directory create a venv, activate it, install a supported Django version, check the framework version, then create a Django project in place. The development server is only for local use. An installed package is not a running listener.","code":{"language":"bash","caption":"Disposable Django project from a clean directory","value":"mkdir tsa-django-intro && cd tsa-django-intro\npython3 -m venv .venv\nsource .venv/bin/activate\npython -m pip install 'Django>=5.2,<6'\npython -m django --version\ndjango-admin startproject config .\npython manage.py check"}},{"heading":"Route an actual request with no missing files","body":"Replace config/urls.py with the complete example. path maps a URL to a callable; JsonResponse serializes a Python dictionary. The view explicitly rejects POST rather than silently accepting every method.","code":{"language":"python","caption":"config/urls.py — first runnable Django endpoint","value":"from django.http import JsonResponse, HttpResponseNotAllowed\nfrom django.urls import path\n\ndef health(request):\n    if request.method != 'GET':\n        return HttpResponseNotAllowed(['GET'])\n    return JsonResponse({'service': 'steward', 'status': 'ok'})\n\nurlpatterns = [path('health/', health)]"}},{"heading":"Prove three HTTP outcomes and a transport failure","body":"Run python manage.py runserver 127.0.0.1:8000 in terminal A. In terminal B, curl -i http://127.0.0.1:8000/health/ should return 200 and JSON, curl -i http://127.0.0.1:8000/missing/ should return 404, and curl -i -X POST http://127.0.0.1:8000/health/ should return 405 with Allow: GET. Stop the server in terminal A and retry: connection refused is not an HTTP 500. Never expose this development listener to the public internet."},{"heading":"Trace and troubleshoot the actual boundaries","body":"The shell starts the management process; Django loads settings and middleware, opens a local socket, resolves config/urls.py and invokes the view. A missing Python package fails before serving HTTP; an occupied port prevents binding; a 404 indicates no matching URL; a 405 means the view was reached but method rejected. DRF, databases and serializers are not prerequisites for this example. The framework is an implementation of the same client/server exchange already taught."}], ["Execute project setup in a disposable directory and record interpreter, Django version and the check result.","Demonstrate HTTP 200, 404, 405 plus a post-shutdown connection error.","Draw shell → server → middleware → URL → view → response, identifying the status producer."], ["Why does python -m django --version not prove the server is listening?","Which layer distinguishes connection refusal from 404?"], [{"title":"Django official tutorial part 1","url":"https://docs.djangoproject.com/en/5.2/intro/tutorial01/","kind":"documentation","purpose":"Primary beginner setup and complete application dispatch."},{"title":"Django URL dispatcher","url":"https://docs.djangoproject.com/en/5.2/topics/http/urls/","kind":"documentation","purpose":"Route ordering, matching and view selection."}]),
  richLesson("Django Foundations", "Continue the disposable Django project from the previous 'Django from Zero' lesson. Instead of memorizing framework file names, we will put a working URL and view in an application, trace a request across the project boundary, and deliberately reproduce two errors. This chapter explains the mechanism using a small public catalogue; Steward is a later application exercise.", ["Distinguish a running Django project from a Django application package and explain what each generated file contributes.","Add a catalogue app and connect its URL configuration to the project without relying on a hidden starter repository.","Trace a request through the server, middleware, URL matching, view, and response.","Reproduce a successful HTTP response, a missing route, and a rejected method, and explain who produced each outcome."], [
  {
    "heading": "The project starts the site; an app owns a capability",
    "body": "The previous lesson generated config/settings.py, config/urls.py, config/asgi.py, config/wsgi.py and manage.py. That is a Django project: its configuration selects settings, middleware and URL dispatch for one site. An app is a Python package organizing a coherent capability, such as a catalogue or a checkout. A project can include several apps; an app can be reused in different projects. Neither word means a separate server or database. The runserver process is the HTTP listener, and the settings module tells Django which site to run."
  },
  {
    "heading": "Create an application inside your existing practice project",
    "body": "Use the same tsa-django-intro directory and activated virtual environment from the previous lesson. Do not start a second project. Running startapp creates catalogue/apps.py, views.py, models.py, tests.py and a migrations directory; it does not add your app to INSTALLED_APPS, define a URL or start a server. Run these commands in the operating-system terminal, not the Python shell. If you already created catalogue, inspect the files instead of running startapp twice.",
    "code": {
      "language": "bash",
      "caption": "Terminal — generate a catalogue application",
      "value": "cd tsa-django-intro\nsource .venv/bin/activate\npython manage.py startapp catalogue\npython manage.py check"
    }
  },
  {
    "heading": "Register the app; understand what that changes",
    "body": "Open config/settings.py. Find the existing INSTALLED_APPS list and add 'catalogue' as ONE new element, leaving all generated entries intact. Django uses installed app configurations for model discovery, migrations, template/static discovery and related framework facilities. INSTALLED_APPS is not a URL table: adding an app does not make /books/ available. The generated catalogue/apps.py declares application metadata; avoid doing network calls or business writes during startup. Keep SECRET_KEY in this local scratch setup private and never reuse its development settings in production.",
    "code": {
      "language": "python",
      "caption": "config/settings.py — add this item to the existing list, do not replace the list",
      "value": "# Add this *after* the generated INSTALLED_APPS list; keep all defaults.\nINSTALLED_APPS += ['catalogue']"
    }
  },
  {
    "heading": "Write one complete view and its URL pattern",
    "body": "A view is a Python callable that takes Django's HttpRequest and returns an HttpResponse. The example deliberately supports GET only. The response body is produced by JsonResponse, which serializes a Python dictionary into JSON and sets the content type. The 405 is produced by our explicit method check; Django does not automatically limit every plain function view to GET. Create the following file exactly in catalogue/views.py.",
    "code": {
      "language": "python",
      "caption": "catalogue/views.py — full view, without a database",
      "value": "from django.http import HttpResponseNotAllowed, JsonResponse\n\n\ndef books(request):\n    if request.method != 'GET':\n        return HttpResponseNotAllowed(['GET'])\n    return JsonResponse({'books': ['Beloved', 'Things Fall Apart']})"
    }
  },
  {
    "heading": "Give the app its routes, then include them in the project",
    "body": "Create catalogue/urls.py (startapp does not create it). The first path matches an empty suffix because config/urls.py will include these patterns under catalogue/. The project's include delegates URL resolution to the app; the request path /catalogue/books/ is matched in two stages. Keep the generated admin route if you want, but do not refer to nonexistent view functions. Notice that importing books must match the function you just created.",
    "code": {
      "language": "python",
      "caption": "catalogue/urls.py — create this file",
      "value": "from django.urls import path\nfrom .views import books\n\nurlpatterns = [path('books/', books, name='book-list')]"
    }
  },
  {
    "heading": "The project chooses where catalogue URLs begin",
    "body": "Replace config/urls.py in this disposable project with this complete configuration. A production project may need additional routes; this example intentionally shows only the generated admin route plus our catalogue prefix. Django tests path patterns in order and passes the unmatched suffix to an included URL configuration. /catalogue/books/ resolves, but /books/ does not.",
    "code": {
      "language": "python",
      "caption": "config/urls.py — project-level URL delegation",
      "value": "from django.contrib import admin\nfrom django.urls import include, path\n\nurlpatterns = [\n    path('admin/', admin.site.urls),\n    path('catalogue/', include('catalogue.urls')),\n]"
    }
  },
  {
    "heading": "Run two terminals and classify the results",
    "body": "Terminal A runs Django's development HTTP server. Terminal B makes HTTP requests. The successful response is 200 with application/json and a JSON array. /books/ returns 404 because it does not match the project prefix. POST /catalogue/books/ returns 405 and an Allow: GET header because the view rejects that method. Press Ctrl-C in Terminal A, then retry: a connection failure is not an HTTP response and should not be described as 500. If you see ModuleNotFoundError, verify the venv and the catalogue import. If you see an occupied port error, inspect what is already listening instead of randomly changing unrelated settings.",
    "code": {
      "language": "bash",
      "caption": "Terminal A, then Terminal B — actual HTTP checks",
      "value": "# Terminal A\npython manage.py runserver 127.0.0.1:8000\n\n# Terminal B (run these in a second terminal)\ncurl -i http://127.0.0.1:8000/catalogue/books/\ncurl -i http://127.0.0.1:8000/books/\ncurl -i -X POST http://127.0.0.1:8000/catalogue/books/"
    }
  },
  {
    "heading": "Follow the request through Django, not just through files",
    "body": "The client opens a connection to the runserver listener. Django constructs HttpRequest and runs configured middleware around dispatch. The project URL table sees catalogue/, include() delegates books/ to catalogue.urls, and Django calls books(request). JsonResponse produces the successful HTTP status, headers and body; the response returns outward through middleware and the server writes it to the client. The database is not involved because the view returns a fixed Python list. Middleware is an ordered wrapper and can stop a request before it reaches a view; merely registering an app does not make middleware run. Trace which layer handles a missing path versus an unsupported method."
  },
  {
    "heading": "Use Django's test client for repeatable checks",
    "body": "The test client invokes Django's request stack without opening a network listening port, so it complements but does not replace the curl experiment. From the project directory, run the one-line Python command below. It checks actual route mapping and responses; it does not test DNS, sockets or a reverse proxy. The request host testserver is accepted by Django's test client in a normal test context; if your custom ALLOWED_HOSTS differs, document and adjust the local-only configuration deliberately.",
    "code": {
      "language": "bash",
      "caption": "Terminal — automatic route and method check",
      "value": "python manage.py shell -c \"from django.test import Client; c=Client(); assert c.get('/catalogue/books/').status_code==200; assert c.get('/books/').status_code==404; assert c.post('/catalogue/books/').status_code==405; print('Django route tests passed')\""
    }
  }
], ["Show your directory tree including catalogue/urls.py. Identify which files were generated and which you created.","Execute the three curl requests, record response status/body, and explain which program or function produced each result.","Run the test-client assertion and deliberately change one route segment; explain the new 404 before restoring it.","Draw project settings → URL include → app URL → view → response, marking where middleware wraps the flow.","Only in the separate Steward practical, move this mechanism into the actual project and explain which boundaries remain domain-owned."], ["Why does adding 'catalogue' to INSTALLED_APPS not automatically create /catalogue/books/?","What is the difference between a project, an application, a view and the running HTTP server?","What would a failed TCP connection tell you that Django's test client cannot?","Why does POST yield 405 here rather than a Django-generated 404?"]),
  richLesson("Django REST Framework", "You already built a Django view that returns JSON. Django REST Framework (DRF) is not a new HTTP server: it adds API-oriented request parsing, response rendering, validation tools and explicit policy hooks around Django views. We will extend the same small catalogue project, prove what changed using real HTTP traffic, and then make an informed decision about using DRF in Steward.", ["Explain the difference between Django's HttpRequest/JsonResponse and DRF's Request/Response.","Install and route a DRF function view without assuming an existing registry model or ViewSet.","Distinguish the request Content-Type from the response Accept header using executable positive and negative tests.","Identify HTTP 400, 405, 406 and 415 at the appropriate parsing/validation/routing stages."], [
  {
    "heading": "Start from the plain Django example",
    "body": "Keep your working tsa-django-intro project, catalogue app and /catalogue/books/ endpoint. Django can already return JSON and read request bodies. DRF is optional; it adds a consistent set of API-focused tools, rather than magically making the application 'RESTful'. Use DRF when its serializers, API exceptions, authentication/permission policies, response renderers and common view conventions reduce real work. You should still be able to explain the underlying HTTP exchange."
  },
  {
    "heading": "Install DRF in the interpreter you are actually using",
    "body": "From the existing activated virtual environment, install the package and confirm that the Python interpreter imports it. Add 'rest_framework' to the existing INSTALLED_APPS list in config/settings.py, alongside catalogue. Keeping catalogue and every generated Django app is essential. The package install alone does not configure URLs or expose a new endpoint. If the import fails, check python -m pip versus the active python instead of reinstalling PostgreSQL or changing network settings.",
    "code": {
      "language": "bash",
      "caption": "Terminal — install and verify DRF",
      "value": "cd tsa-django-intro\nsource .venv/bin/activate\npython -m pip install djangorestframework\npython -c \"import rest_framework; print(rest_framework.VERSION)\"\npython manage.py check"
    }
  },
  {
    "heading": "Build a small JSON endpoint with explicit responsibilities",
    "body": "In catalogue/api_views.py create this complete view. @api_view wraps the function in DRF's APIView behavior. JSONParser interprets JSON when request.data is accessed; JSONRenderer turns Response's Python dictionary into JSON bytes. We configure one parser and renderer deliberately to make the media-type experiment unambiguous. This endpoint accepts POST only and checks a name field to keep the experiment focused. It does not save data or use a database, model, serializer or Steward service.",
    "code": {
      "language": "python",
      "caption": "catalogue/api_views.py — complete request/response example",
      "value": "from rest_framework.decorators import api_view, parser_classes, renderer_classes\nfrom rest_framework.exceptions import ValidationError\nfrom rest_framework.parsers import JSONParser\nfrom rest_framework.renderers import JSONRenderer\nfrom rest_framework.response import Response\n\n\n@api_view(['POST'])\n@parser_classes([JSONParser])\n@renderer_classes([JSONRenderer])\ndef greet(request):\n    name = request.data.get('name') if isinstance(request.data, dict) else None\n    if not isinstance(name, str) or not name.strip():\n        raise ValidationError({'name': 'Enter a non-empty string.'})\n    return Response({'greeting': f'Hello, {name.strip()}'})"
    }
  },
  {
    "heading": "Add the API URL without removing your Django URL",
    "body": "The catalogue app already has catalogue/urls.py from the earlier lesson. Replace that file with the two routes below. The project-level include stays at /catalogue/; therefore POST /catalogue/greet/ resolves to DRF while GET /catalogue/books/ still resolves to the plain Django view. This lets you compare them on the same development server.",
    "code": {
      "language": "python",
      "caption": "catalogue/urls.py — preserve the original plain Django endpoint",
      "value": "from django.urls import path\nfrom .api_views import greet\nfrom .views import books\n\nurlpatterns = [\n    path('books/', books, name='book-list'),\n    path('greet/', greet, name='greet'),\n]"
    }
  },
  {
    "heading": "Send a real JSON request and observe Response rendering",
    "body": "Run runserver in terminal A if it is not already running. Then use curl in terminal B. Request Content-Type: application/json describes the bytes you send; Accept: application/json says which response representation you can accept. The server should respond 200 and JSON containing 'Hello, Ada'. The view returns a DRF Response, not bytes; rendering occurs after the handler selects data. Compare with the earlier JsonResponse, which constructs an HttpResponse directly.",
    "code": {
      "language": "bash",
      "caption": "Terminal B — request and response media types",
      "value": "curl -i -X POST http://127.0.0.1:8000/catalogue/greet/ \\\n  -H 'Content-Type: application/json' \\\n  -H 'Accept: application/json' \\\n  -d '{\"name\":\"Ada\"}'"
    }
  },
  {
    "heading": "Change one condition at a time to see four different failures",
    "body": "Each command below changes a different part of the request. A blank name has valid JSON but fails our own serializer-like validation (400). GET reaches an existing DRF URL with an unsupported method (405). A text/plain body reaches the view, but JSONParser cannot parse that media type when request.data is accessed (415). A client accepting only text/plain cannot be served by our JSON-only renderer (406). These are *not* interchangeable errors: changing a role or reinstalling PostgreSQL cannot fix them. A malformed JSON body with Content-Type application/json would be another 400, this time from parsing rather than our field check.",
    "code": {
      "language": "bash",
      "caption": "Terminal B — reproduce 400, 405, 415 and 406",
      "value": "# 400: valid JSON but invalid field\ncurl -i -X POST http://127.0.0.1:8000/catalogue/greet/ -H 'Content-Type: application/json' -d '{\"name\":\"\"}'\n\n# 405: existing route, wrong method\ncurl -i http://127.0.0.1:8000/catalogue/greet/\n\n# 415: unsupported request body media type\ncurl -i -X POST http://127.0.0.1:8000/catalogue/greet/ -H 'Content-Type: text/plain' -d 'Ada'\n\n# 406: unacceptable response media type\ncurl -i -X POST http://127.0.0.1:8000/catalogue/greet/ -H 'Content-Type: application/json' -H 'Accept: text/plain' -d '{\"name\":\"Ada\"}'"
    }
  },
  {
    "heading": "Separate request parsing, validation and authorization",
    "body": "DRF Request wraps Django's HttpRequest and provides request.data plus request.query_params. The parser translates the incoming representation to Python primitives, then our function validates the value. A real serializer will perform more systematic field conversion and representation control; that deserves its own later lesson. Authentication identifies the caller, permission checks whether an operation is allowed, and throttling applies a rate policy. None of those is the same thing as parsing JSON. Our open local endpoint deliberately adds no access policy, so do not treat it as a production authentication example."
  },
  {
    "heading": "Learn the tools without hiding the control flow",
    "body": "A function-based @api_view is enough for this one request. APIView adds class-based methods and policy hooks; generic views and ViewSets become useful after we understand model querysets and serializer behavior. They can also hide default write methods, queryset scope and permissions if used prematurely. When evaluating an abstraction, explain what request it accepts, what SQL it may issue, what response it returns and what it rejects. Do not introduce a ViewSet here merely because one exists."
  }
], ["Keep the plain Django books endpoint working, then implement the new DRF greet endpoint without creating a new Django project.","Run one valid JSON request and all four failure requests, recording status, content type and response body.","Explain for each case whether URL dispatch, method dispatch, parsing, field validation or response negotiation caused the outcome.","Show how Content-Type and Accept serve opposite directions in the same HTTP exchange.","Only after passing these tests, use a separate Steward practical to apply DRF to a domain-backed endpoint."], ["Why is DRF's Response not the same class as Django's JsonResponse?","Why does text/plain sent to JSONParser produce 415 rather than 406?","Why does a nonempty string not imply that the caller is authorized to submit it?","What would you lose if you jumped straight into ModelViewSet before understanding routes and serializers?"]),
  richLesson("Projects, Applications and Boundaries", "Django's project is the configuration and process context, while an app is an importable unit of functionality. A well-named app does not automatically enforce good boundaries: responsibilities and dependencies determine whether changes remain understandable. Steward is a cohesive service registry whose teams, services, deployments and dependencies share domain rules; do not split them into isolated apps merely because they correspond to separate tables.", ["Distinguish the project configuration package from domain app packages.","Trace one request through URL/view/application/model without circular imports.","Compare app-per-table and cohesive-domain app layouts with explicit dependency direction."], [{"heading":"Start with the generated project rather than an architecture diagram","body":"Use the existing tsa-django-intro project and its catalogue app. config/settings.py configures the framework, config/urls.py includes application routes, and catalogue/views.py returns a fixed book list without a database. Later, the separate Steward registry app will add persistent models, serializers, permissions and application services; those files do not exist in this scratch exercise yet. The project can contain multiple apps, but Django does not impose a one-app-per-entity rule. The project can contain multiple apps, but Django does not impose a one-app-per-entity rule. Trace the actual catalogue request first: configuration includes catalogue.urls, which imports catalogue.views; the view returns JSON without a model. Then sketch the future registry variant as a design, not as runnable code. A domain model should not import HTTP Response or global request objects."},{"heading":"Compare two architectures against an actual change","body":"Design A has one team app, one service app, one environment app and one dependencies app, each importing the others' models. A request 'move a Service to retired' now traverses several packages and creates coupling/circular-import risks. Design B keeps registry concepts together and separates HTTP representation, domain command, and persistent mapping within that app. Neither structure is universally correct: choose B for Steward's initial narrow cohesive capability, and split only when ownership, independent change cadence or a stable integration contract justify a new boundary. Splitting modules is a response to independent reasons to change, not raw line count."},{"heading":"Make the HTTP → application → model direction visible","body":"The following is a sketch of the call graph, not runnable Python. It deliberately distinguishes the framework/router from an application command that owns the operation and from the database model that stores results. Authorization may need server-supplied user and owning Team facts; a serializer alone cannot substitute for policy. The application command should return a domain result/error instead of importing DRF Response.","code":{"language":"text","caption":"One cohesive app — request-to-data dependency direction","value":"config.urls → registry.urls → registry.views\nregistry.views → registry.serializers (parse representation)\nregistry.views → registry.services (request-independent operation)\nregistry.services → registry.models (persistent facts)\nregistry.services → registry.policy (ownership decision)\nregistry.models ✗ registry.views (forbidden dependency direction)"}},{"heading":"Test circular import and initialization assumptions","body":"Circular imports often occur when models.py imports services.py while services.py imports models.py at module load. Instead, keep domain policy functions independent where possible, import models at appropriate layering and use Django apps.get_model only for documented lifecycle/migration cases. Import errors can appear during Django app initialization before an HTTP server ever binds. Run python manage.py check and import the existing catalogue view, then test the previously built /catalogue/books/ request. The next lesson creates the Steward registry project; do not invent it here. Do not use a local import in every function as a permanent substitute for designing coherent dependencies."},{"heading":"Define an extraction criterion before growing the system","body":"Keep the first registry app together, but document extraction triggers: independent product ownership, distinct deployment/security boundary or repeated stable interface across consumers. Avoid creating a shared steward-common package for a single client; later systems education teaches service boundaries and governance. Preserve the current domain without constructing premature microservices inside a single Django process."}], ["Draw project and application responsibilities using the existing catalogue files, then sketch the future Steward registry layout as a proposed design rather than an existing implementation.","Trace the working GET /catalogue/books/ request and identify which responsibilities have not been implemented yet (authentication, authorization and persistence). Sketch how a future /services/ endpoint would add them.","Compare an app-per-table layout with a cohesive registry app and justify the dependency direction.","Run manage.py check and import catalogue.views; explain how a proposed registry.services to registry.models dependency would differ, without assuming those files already exist."], ["Why is a Django app not automatically a microservice?","Why should a model not import HTTP response classes?","When would a second app deserve its own boundary?"], [{"title":"Django — Applications","url":"https://docs.djangoproject.com/en/5.2/ref/applications/","kind":"reference","purpose":"App registry and startup behavior"},{"title":"Django — URL dispatcher","url":"https://docs.djangoproject.com/en/5.2/topics/http/urls/","kind":"reference","purpose":"Framework-level request routing"}]),
  richLesson("Define Your First Django Model", "Before mapping an entire service registry, define one ordinary Python model and connect each field to the table PostgreSQL taught you to reason about. Keep using the catalogue scratch project; no Steward schema and no Docker.", ["Explain the difference between a model class, an instance and a database row.","Identify Django's fields and implicit primary key.","Write one complete model in the existing Django app."], [
    { heading: "A model is a Python description of stored data", body: "PostgreSQL stores tables and rows; Django lets Python code describe the same structural ideas. A model class inherits django.db.models.Model, while each instance can represent a row. The class is not the table itself, and creating a Python instance does not write a row. A model needs a migration before its table exists." },
    { heading: "Write the Book model and read every field", body: "Replace the starter catalogue/models.py with this complete file. title is text with a maximum length of 120 and a uniqueness requirement. published_year is a nonnegative integer at the field-validation level. Django also gives the model a primary key named id by default (its exact database type follows the project configuration). __str__ affects human-readable display, not the database table name.", code: { language: "python", caption: "catalogue/models.py — first complete model", value: "from django.db import models\n\nclass Book(models.Model):\n    title = models.CharField(max_length=120, unique=True)\n    published_year = models.PositiveIntegerField()\n\n    def __str__(self):\n        return self.title" } },
    { heading: "What Python knows and what the database does not know yet", body: "This code is importable, and python manage.py check can catch many configuration errors, but it has not created catalogue_book. A Book(title='The River', published_year=2024) expression is just a Python object until save() persists it. Do not confuse defining fields, generating a migration, applying a migration and saving an instance." },
    { heading: "Compare it with the SQL you already learned", body: "The intended table conceptually has id, title and published_year columns, with a unique title. The actual SQL also depends on the database backend; do not blindly copy a guessed CREATE TABLE definition. In the next lesson you will inspect Django's real generated SQL before allowing it to modify the database." },
  ], ["Stay in tsa-django-intro and confirm that catalogue is listed in INSTALLED_APPS.","Replace catalogue/models.py with the source above and run python manage.py check.","Predict whether querying Book.objects.count() can work before migration; record the error or explanation.","Sketch the SQL columns and constraints this model describes without claiming the table exists yet."], ["What is the distinction between a Python model instance and a persisted row?","Does defining Book create a SQL table? What operation is still missing?","Why might full_clean and database constraints reject different invalid values?"], [{"title":"Django 5.2 — Models","url":"https://docs.djangoproject.com/en/5.2/topics/db/models/","kind":"documentation","purpose":"Field-to-table model, implicit primary key, model identity."},{"title":"Django 5.2 — Model instance validation","url":"https://docs.djangoproject.com/en/5.2/ref/models/instances/#validating-objects","kind":"reference","purpose":"full_clean versus save; database and Python validation are different."},{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"makemigrations, migrate, showmigrations and generated SQL."}]),

  richLesson("Turn a Model into a Database Table", "Now connect Django's model declaration to the actual database schema. Use one disposable catalogue database and distinguish the migration file from executing the migration.", ["Explain makemigrations versus migrate.","Inspect SQL and applied-migration state.","Create and query one row.","Demonstrate Python validation and a database UNIQUE rejection."], [
    { heading: "The change must reach the database", body: "Editing catalogue/models.py changes Python source, not the existing database. makemigrations compares model state with versioned migration state and writes a migration file; it does not create your table. sqlmigrate prints the SQL that a migration would execute; migrate applies pending migrations. showmigrations marks which migrations were applied. Django's scratch project uses its default local SQLite database unless you deliberately reconfigured it. This lab does not touch the previously created PostgreSQL library or Steward databases." },
    { heading: "Run the commands in order", body: "From the directory containing manage.py, run these commands in the established scratch project. After makemigrations, expect catalogue/migrations/0001_initial.py. sqlmigrate should show a CREATE TABLE for catalogue_book. Before migrate, showmigrations should report an unapplied [ ] migration; afterwards it should report [X]. Generated SQL varies by backend. Do not use --fake or manually create tables to make a broken run look successful.", code: { language: "bash", caption: "Terminal — create and inspect the first catalogue migration", value: "# In the same tsa-django-intro project; catalogue is in INSTALLED_APPS.\npython manage.py check\npython manage.py makemigrations catalogue\npython manage.py sqlmigrate catalogue 0001\npython manage.py showmigrations catalogue\npython manage.py migrate\npython manage.py showmigrations catalogue" } },
    { heading: "See what actually gets saved", body: "Create catalogue/books_lab.py with the entire program below. Run it once with python manage.py shell -c \"exec(open('catalogue/books_lab.py').read())\". The initial Book(...) merely constructs an instance; full_clean() performs Python-side validation; save() attempts persistence. .objects is Django's default manager. The printed count and titles show the stored row, and the two deliberate failures teach different layers.", code: { language: "python", caption: "catalogue/books_lab.py — persistence and two independent rejections", value: "from django.core.exceptions import ValidationError\nfrom django.db import IntegrityError\nfrom catalogue.models import Book\n\nbook = Book(title=\"The River\", published_year=2024)\nbook.full_clean()\nbook.save()\nprint(\"saved_books:\", Book.objects.count())\nprint(\"titles:\", list(Book.objects.values_list(\"title\", flat=True)))\n\ninvalid = Book(title=\"\", published_year=2024)\ntry:\n    invalid.full_clean()\nexcept ValidationError as exc:\n    assert \"title\" in exc.message_dict\n    print(\"BLANK_TITLE_REJECTED\")\nelse:\n    raise AssertionError(\"An empty title passed model validation\")\n\ntry:\n    Book.objects.create(title=\"The River\", published_year=2020)\nexcept IntegrityError:\n    print(\"DUPLICATE_TITLE_REJECTED\")\nelse:\n    raise AssertionError(\"The database accepted duplicate title\")", output: "saved_books: 1\ntitles: ['The River']\nBLANK_TITLE_REJECTED\nDUPLICATE_TITLE_REJECTED" } },
    { heading: "Do not confuse validation with a database constraint", body: "The blank-title case is rejected when full_clean() checks the model's field validation; ordinary model save() does not automatically call full_clean(). The duplicate-title insert reaches the database and fails with IntegrityError because unique=True created a uniqueness rule. A unique check in Python alone would not protect against concurrent inserts. Never rely on a prior check as your only database integrity mechanism." },
    { heading: "Recognize failed setup quickly", body: "A 'no such table: catalogue_book' or 'relation does not exist' error after the model import means the migration has not reached the database you are connected to. Confirm the current Django DATABASES setting, inspect showmigrations and sqlmigrate, then apply migrations to the intended disposable database. Do not drop an existing table as a first troubleshooting step." },
  ], ["Use makemigrations, sqlmigrate and showmigrations before executing migrate.","Run the authored books_lab.py only once on a clean scratch dataset and record its output.","Predict and explain the blank-title ValidationError and duplicate-title IntegrityError.","Describe why a database migration must be reviewed separately from code import and model validation."], ["Which command generates migration source and which command changes schema?","Why does sqlmigrate not create your table?","Why can a duplicate title still fail at the database after Python has already validated another object?","What should you inspect when a model imports but the table is missing?"], [{"title":"Django 5.2 — Models","url":"https://docs.djangoproject.com/en/5.2/topics/db/models/","kind":"documentation","purpose":"Field-to-table model, implicit primary key, model identity."},{"title":"Django 5.2 — Model instance validation","url":"https://docs.djangoproject.com/en/5.2/ref/models/instances/#validating-objects","kind":"reference","purpose":"full_clean versus save; database and Python validation are different."},{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"makemigrations, migrate, showmigrations and generated SQL."}]),

  richLesson("Create Relationships Between Django Models", "Before implementing Steward's multi-table domain, build one small relationship and enforce a rule across two foreign keys in the existing catalogue. Reuse the Book row created in the previous lesson.", ["Explain ForeignKey and one-to-many relationships.","Observe explicit on_delete choices.","Use a database UniqueConstraint on a pair.","Inspect a second migration before applying it."], [
    { heading: "Foreign keys reference rows; they do not embed objects", body: "A reading list can contain multiple books. We introduce ReadingList and ReadingListEntry as new tables; each entry references one list and one existing Book. ReadingListEntry explicitly represents a many-to-many membership and lets us enforce one copy of the same book per list. A ForeignKey stores a reference to an existing row, not a serialized copy of that Python object." },
    { heading: "Add the new models after Book", body: "Append the following exact classes to catalogue/models.py below the Book class, keeping the original import and Book definition. related_name='entries' lets you query entries from a ReadingList. Deleting a ReadingList through Django follows the CASCADE policy for its entries; deleting a referenced Book through Django hits PROTECT and fails. These are Django ORM deletion behaviors; do not mistake them for proof that direct SQL uses the same ON DELETE action.", code: { language: "python", caption: "catalogue/models.py — append two related models", value: "# Append the following classes BELOW Book in catalogue/models.py.\n# The earlier \"from django.db import models\" remains at the top of this file.\nclass ReadingList(models.Model):\n    name = models.CharField(max_length=120, unique=True)\n\nclass ReadingListEntry(models.Model):\n    reading_list = models.ForeignKey(\n        ReadingList, on_delete=models.CASCADE, related_name=\"entries\"\n    )\n    book = models.ForeignKey(Book, on_delete=models.PROTECT)\n\n    class Meta:\n        constraints = [\n            models.UniqueConstraint(\n                fields=[\"reading_list\", \"book\"], name=\"one_book_per_reading_list\"\n            )\n        ]" } },
    { heading: "Create the second migration", body: "These are NEW tables; no change to the existing populated Book table is required. Run makemigrations, inspect sqlmigrate catalogue 0002 for CREATE TABLE and references, then migrate. If Django suggests a different migration number, inspect current showmigrations rather than forcing the command. In this clean progression it should be 0002.", code: { language: "bash", caption: "Terminal — inspect and apply the relationship migration", value: "# After appending both classes to catalogue/models.py:\npython manage.py makemigrations catalogue\npython manage.py sqlmigrate catalogue 0002\npython manage.py migrate\npython manage.py showmigrations catalogue" } },
    { heading: "Demonstrate enforced behavior with real data", body: "Create catalogue/relations_lab.py and run python manage.py shell -c \"exec(open('catalogue/relations_lab.py').read())\". The first membership succeeds; a duplicate pair raises database IntegrityError; deleting the Book through Django is protected; deleting the ReadingList removes its entries while preserving Book. Each observation corresponds to one relationship or constraint declaration.", code: { language: "python", caption: "catalogue/relations_lab.py — uniqueness, PROTECT and CASCADE", value: "from django.db import IntegrityError\nfrom django.db.models.deletion import ProtectedError\nfrom catalogue.models import Book, ReadingList, ReadingListEntry\n\nbook = Book.objects.get(title=\"The River\")\nreading_list = ReadingList.objects.create(name=\"Weekend Reading\")\nReadingListEntry.objects.create(reading_list=reading_list, book=book)\nprint(\"list_items:\", reading_list.entries.count())\n\ntry:\n    ReadingListEntry.objects.create(reading_list=reading_list, book=book)\nexcept IntegrityError:\n    print(\"DUPLICATE_MEMBERSHIP_REJECTED\")\nelse:\n    raise AssertionError(\"A duplicate book/list pair was accepted\")\n\ntry:\n    book.delete()\nexcept ProtectedError:\n    print(\"BOOK_DELETE_PROTECTED\")\nelse:\n    raise AssertionError(\"A referenced book was deleted\")\n\nreading_list.delete()\nprint(\"entries_after_list_delete:\", ReadingListEntry.objects.count())\nprint(\"books_after_list_delete:\", Book.objects.count())", output: "list_items: 1\nDUPLICATE_MEMBERSHIP_REJECTED\nBOOK_DELETE_PROTECTED\nentries_after_list_delete: 0\nbooks_after_list_delete: 1" } },
    { heading: "Know where rules belong", body: "Django ForeignKey, unique constraints and field types translate to persistent database structure. More complicated operation rules—such as whether a service can transition into production—may need transactional domain code with database support. When the next lesson maps the real Steward SQL schema, keep those responsibilities distinct. The catalogue objects are teaching fixtures, not your service registry." },
    { heading: "If something fails, diagnose the layer", body: "A missing catalogue_readinglist table points to a migration that was not applied. An unexpected IntegrityError may reflect uniqueness or a missing referenced row; inspect its constraint and the actual saved records. A ProtectedError comes from the Django ORM's delete collector; reproduce the deletion through that path before claiming the database itself blocks equivalent direct SQL." },
  ], ["Append the two related model classes; generate and inspect the second migration.","Run the related-model example and capture all five observed lines.","Change the example to add a second distinct Book to the same list; predict whether it succeeds.","Explain the difference between many-to-many through an explicit model and a simple ManyToManyField.","Write down which safeguards must be verified separately for direct SQL and ORM deletion."], ["What does a ForeignKey store?","What happens if a ReadingList is deleted, versus a Book still referenced by an entry?","Which constraint prevents duplicate (reading_list, book) pairs?","Why is a successful Django PROTECT experiment not evidence about raw SQL ON DELETE semantics?"], [{"title":"Django 5.2 — Models","url":"https://docs.djangoproject.com/en/5.2/topics/db/models/","kind":"documentation","purpose":"Field-to-table model, implicit primary key, model identity."},{"title":"Django 5.2 — Model instance validation","url":"https://docs.djangoproject.com/en/5.2/ref/models/instances/#validating-objects","kind":"reference","purpose":"full_clean versus save; database and Python validation are different."},{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"makemigrations, migrate, showmigrations and generated SQL."}]),

  richLesson("Build and Execute Your First QuerySet", "Your catalogue models and migrations are working. Now learn how Django asks the database for rows. Start with a predictable four-book fixture before introducing optimization or a production service registry.", ["Tell apart a model class, a Manager, a QuerySet and an evaluated collection of rows.","Use filter, exclude and order_by to form a SQL question.","Measure zero queries during construction and one query when results are consumed.","Inspect the generated SQL without confusing a string representation with a safely executable query."], [
    { heading: "A model, a manager and a QuerySet have different jobs", body: "Book is a Python model class describing stored rows. Book.objects is its manager: it starts queries. Calling Book.objects.filter(...) returns a QuerySet, which represents a particular database question; it is not the table and it is not yet a list. Filter conditions specify which rows qualify, exclude removes matches, and order_by asks SQL to order returned rows. Each chaining step normally returns another QuerySet and does not update the database." },
    { heading: "Make the example data reproducible", body: "Reuse the tsa-django-intro catalogue from the previous lessons. You should already have Book, ReadingList and ReadingListEntry tables migrated, and the Book titled The River persisted. Save this fixture as catalogue/query_seed.py and run it using the next terminal command. get_or_create avoids inserting duplicates if you repeat the fixture. It creates four books, three reading lists, and three list entries; the expected counts assume the clean scratch dataset built in this course. If your dataset differs, inspect actual records before deleting anything.", code: { language: "python", caption: "catalogue/query_seed.py — four books and three reading lists", value: "# Save as catalogue/query_seed.py and run once, or rerun safely.\nfrom catalogue.models import Book, ReadingList, ReadingListEntry\n\nfor title, year in [\n    (\"The River\", 2024),\n    (\"River Guide\", 2021),\n    (\"Digital Habits\", 2022),\n    (\"Third Story\", 2018),\n]:\n    Book.objects.get_or_create(\n        title=title, defaults={\"published_year\": year}\n    )\n\nfor list_name, book_title in [\n    (\"Favorites\", \"Digital Habits\"),\n    (\"Weekend\", \"The River\"),\n    (\"Work\", \"River Guide\"),\n]:\n    reading_list, _ = ReadingList.objects.get_or_create(name=list_name)\n    book = Book.objects.get(title=book_title)\n    ReadingListEntry.objects.get_or_create(\n        reading_list=reading_list, book=book\n    )\n\nprint(\"books_ready:\", Book.objects.count())\nprint(\"lists_ready:\", ReadingList.objects.count())\nprint(\"entries_ready:\", ReadingListEntry.objects.count())", output: "books_ready: 4\nlists_ready: 3\nentries_ready: 3" } },
    { heading: "Run the fixture from the Django shell", body: "Django's shell initializes the settings and model registry before importing your models. Run this command from the directory containing manage.py. Do not type it inside the interactive Python prompt and do not connect it to the earlier manually seeded PostgreSQL database.", code: { language: "bash", caption: "Terminal — load the independent catalogue fixture", value: "# From tsa-django-intro, in the folder containing manage.py:\npython manage.py shell -c \"exec(open('catalogue/query_seed.py').read())\"" } },
    { heading: "Watch a QuerySet cross the Python-to-database boundary", body: "Save the following complete script. CaptureQueriesContext records real SQL statements issued on this Django database connection. Constructing the QuerySet produces no statements; converting its query to a string is an inspection aid, not an execution. Iterating through books runs one SELECT; repeating iteration on this already-evaluated QuerySet uses its result cache and runs zero. The output is stable because the fixture has known years and explicit title ordering.", code: { language: "python", caption: "catalogue/queryset_first.py — construction versus evaluation", value: "# Save as catalogue/queryset_first.py.\nfrom django.db import connection\nfrom django.test.utils import CaptureQueriesContext\nfrom catalogue.models import Book\n\nwith CaptureQueriesContext(connection) as constructing:\n    books = (\n        Book.objects.filter(published_year__gte=2021)\n        .exclude(title=\"Digital Habits\")\n        .order_by(\"title\")\n    )\n    statement = str(books.query)\n\nprint(\"construction_queries:\", len(constructing))\nprint(\"generated_sql_has_where:\", \"WHERE\" in statement)\n\nwith CaptureQueriesContext(connection) as executing:\n    titles = [book.title for book in books]\nprint(\"evaluation_queries:\", len(executing))\nprint(\"titles:\", titles)\n\nwith CaptureQueriesContext(connection) as reusing:\n    again = [book.title for book in books]\nprint(\"reuse_queries:\", len(reusing))\nassert titles == again == [\"River Guide\", \"The River\"]", output: "construction_queries: 0\ngenerated_sql_has_where: True\nevaluation_queries: 1\ntitles: ['River Guide', 'The River']\nreuse_queries: 0" } },
    { heading: "Run and explain the SQL trace", body: "Execute this command, then describe the path Book.objects → QuerySet → SQL SELECT → Book instances. The generated SQL has a WHERE clause derived from the filters, and ordering derives from order_by. Actual SQL syntax and quoting depend on the database engine; inspect the measured statements, not a guessed exact query string. The displayed qs.query is for diagnosis and should not be pasted into raw SQL or used to interpolate untrusted input.", code: { language: "bash", caption: "Terminal — measure actual QuerySet evaluation", value: "# From tsa-django-intro, in the folder containing manage.py:\npython manage.py shell -c \"exec(open('catalogue/queryset_first.py').read())\"" } },
    { heading: "Diagnose the first two failures", body: "If the import fails, verify that catalogue is registered in INSTALLED_APPS and models.py has the three models. If a missing-table error appears, confirm which database settings Django is using and inspect showmigrations catalogue; the Python model source alone does not create SQL tables. If titles do not match, query Book.objects.order_by('title').values_list('title',flat=True) in the shell and reconcile the fixture instead of silently modifying the expected output. A valid empty QuerySet is not an exception." },
  ], ["Run the source fixture and record its three counts.","Run queryset_first.py; explain why constructing a QuerySet is free of database round trips but iteration is not.","Replace published_year__gte=2021 with 2023, predict the new returned titles, then verify the one-query result.","Remove order_by('title') and explain why row order is no longer promised.","Identify the earlier PostgreSQL SELECT/WHERE/ORDER BY expressions corresponding to this ORM code."], ["What does Book.objects mean, and what does .filter() return?","Why is building a QuerySet different from retrieving a list of books?","Why is inspecting str(qs.query) not the same as running a SQL statement?","Which observable evidence distinguishes an empty result from a missing table?"], [{"title":"Django 5.2 — Making queries","url":"https://docs.djangoproject.com/en/5.2/topics/db/queries/","kind":"documentation","purpose":"QuerySet creation, lookups, evaluation, matching SQL behavior and per-QuerySet caches."},{"title":"Django 5.2 — QuerySet API reference","url":"https://docs.djangoproject.com/en/5.2/ref/models/querysets/","kind":"reference","purpose":"Evaluation triggers, get/first/count/exists, select_related and prefetch_related."},{"title":"Django 5.2 — Database access optimization","url":"https://docs.djangoproject.com/en/5.2/topics/db/optimization/","kind":"reference","purpose":"Profile query patterns and decide when to prefetch instead of guessing."}]),

  richLesson("Choose Django Query Methods and Reuse Results", "A working QuerySet does not mean every way of reading it costs the same. Learn the intent and failure behavior of get, first, exists and count, and see exactly when Django reuses cached rows versus sending new SQL.", ["Explain the different result contracts of get(), first(), exists() and count().","Distinguish cached iteration from two independently constructed queries.","Predict why indexing an unevaluated QuerySet can issue SQL each time.","Avoid measuring an already-evaluated QuerySet as if it were fresh."], [
    { heading: "Choose a method based on your question", body: "Use get() only when exactly one row is expected; it raises Book.DoesNotExist for none and Book.MultipleObjectsReturned for several. first() returns one row or None (use explicit order_by to define which), exists() answers yes/no, and count() asks the database to count rows. Evaluating an entire QuerySet with list() or len() may fetch full Book objects; avoid that if you only need a count. In contrast, if you will iterate the same rows anyway, an extra exists() or count() on an unevaluated QuerySet may add unnecessary work." },
    { heading: "A cache belongs to a QuerySet instance", body: "Django normally stores fetched results on the particular QuerySet that evaluated them. Reusing that same QuerySet for two full iterations usually produces one SELECT. Constructing two identical QuerySets is two separate objects and two SQL reads. Do not assume a matching SQL string or the same Python variable name makes two fresh QuerySets share a cache. An index on a still-unevaluated QuerySet can issue a separate LIMIT query each time." },
    { heading: "Run every method and its negative behavior", body: "Save this file in the same catalogue. Every query-count statement is wrapped around a fresh operation; the seeded four-book data makes the expected behavior deterministic. The two get() failures intentionally demonstrate different exceptions, not caught database outages. Two reads using the same QuerySet evaluate once; two independently constructed QuerySets evaluate twice. count() and list() asked separately also issue two statements.", code: { language: "python", caption: "catalogue/queryset_methods.py — query method and cache experiments", value: "# Save as catalogue/queryset_methods.py.\nfrom django.db import connection\nfrom django.test.utils import CaptureQueriesContext\nfrom catalogue.models import Book\n\nbooks = Book.objects.order_by(\"title\")\nwith CaptureQueriesContext(connection) as same:\n    first = [book.title for book in books]\n    second = [book.title for book in books]\nprint(\"same_queryset_queries:\", len(same))\nassert first == second\n\nwith CaptureQueriesContext(connection) as fresh:\n    _ = list(Book.objects.order_by(\"title\"))\n    _ = list(Book.objects.order_by(\"title\"))\nprint(\"fresh_querysets_queries:\", len(fresh))\n\nwith CaptureQueriesContext(connection) as count_only:\n    count = Book.objects.count()\nprint(\"count:\", count, \"queries:\", len(count_only))\n\nwith CaptureQueriesContext(connection) as existence:\n    found = Book.objects.filter(published_year__gte=2024).exists()\nprint(\"exists:\", found, \"queries:\", len(existence))\n\nwith CaptureQueriesContext(connection) as first_row:\n    earliest = Book.objects.order_by(\"published_year\", \"id\").first()\nprint(\"first:\", earliest.title, \"queries:\", len(first_row))\n\nwith CaptureQueriesContext(connection) as direct:\n    river = Book.objects.get(title=\"The River\")\nprint(\"get:\", river.title, \"queries:\", len(direct))\n\ntry:\n    Book.objects.get(title=\"No Such Book\")\nexcept Book.DoesNotExist:\n    print(\"GET_MISSING_REJECTED\")\nelse:\n    raise AssertionError(\"get() should fail when no row matches\")\n\ntry:\n    Book.objects.get(published_year__gte=2021)\nexcept Book.MultipleObjectsReturned:\n    print(\"GET_MULTIPLE_REJECTED\")\nelse:\n    raise AssertionError(\"get() should fail when several rows match\")\n\nindexed = Book.objects.order_by(\"title\")\nwith CaptureQueriesContext(connection) as indexing:\n    _ = indexed[0]\n    _ = indexed[0]\nprint(\"uncached_index_queries:\", len(indexing))\n\nwith CaptureQueriesContext(connection) as double_work:\n    _ = Book.objects.count()\n    _ = list(Book.objects.order_by(\"title\"))\nprint(\"count_then_list_queries:\", len(double_work))", output: "same_queryset_queries: 1\nfresh_querysets_queries: 2\ncount: 4 queries: 1\nexists: True queries: 1\nfirst: Third Story queries: 1\nget: The River queries: 1\nGET_MISSING_REJECTED\nGET_MULTIPLE_REJECTED\nuncached_index_queries: 2\ncount_then_list_queries: 2" } },
    { heading: "Run the query-method experiments", body: "Run the complete script once after the fixture. Inspect the printed counts and the reasoning, not just a pass/fail label. Notice that .get() returns a Book instance and may raise; .first() returns a Book instance or None; .exists() returns a Boolean; .count() returns a number. A QuerySet is not itself a single row.", code: { language: "bash", caption: "Terminal — measure method-specific SQL", value: "# From tsa-django-intro, in the folder containing manage.py:\npython manage.py shell -c \"exec(open('catalogue/queryset_methods.py').read())\"" } },
    { heading: "The subtle trap: reused results can hide new SQL", body: "If you create qs, call list(qs), and then measure list(qs), you may observe zero statements because the cache is already populated. That does not prove the original database read was free. Conversely qs.iterator() bypasses ordinary QuerySet result caching, which is useful in some streaming workloads but changes later reuse; do not optimize for streaming without considering memory, relationship loading and the complete task." },
    { heading: "Failure analysis and decision discipline", body: "A get() MultipleObjectsReturned is a broken uniqueness expectation or wrong filter, not an instruction to arbitrarily choose first(). A get() DoesNotExist is a useful distinction from a connection error. A surprisingly high count may result from repeating fresh queries or using exists() then evaluating the same unevaluated result set. Before changing code, state which return contract the caller needs and which SQL operations actually happened." },
  ], ["Reproduce each displayed count and both get() exception cases on the four-book fixture.","For an API that needs only a total number, choose count(), len(queryset) or list(queryset) and defend your choice.","For an API that must display all rows after checking whether any exist, compare exists()+list() with a single list() on a fresh QuerySet.","Change an indexed QuerySet to materialize it once before accessing [0] twice; predict the new query count and verify.","Write a short decision table: get, first, exists, count, list and their expected return shapes."], ["What exception does get() raise when two books match?","Why can count() be cheaper than len() on an unevaluated QuerySet?","Why does calling first() silently discard important information if the domain requires uniqueness?","If the second list(qs) issues no SQL, how do you prove the first one actually hit the database?"], [{"title":"Django 5.2 — Making queries","url":"https://docs.djangoproject.com/en/5.2/topics/db/queries/","kind":"documentation","purpose":"QuerySet creation, lookups, evaluation, matching SQL behavior and per-QuerySet caches."},{"title":"Django 5.2 — QuerySet API reference","url":"https://docs.djangoproject.com/en/5.2/ref/models/querysets/","kind":"reference","purpose":"Evaluation triggers, get/first/count/exists, select_related and prefetch_related."},{"title":"Django 5.2 — Database access optimization","url":"https://docs.djangoproject.com/en/5.2/topics/db/optimization/","kind":"reference","purpose":"Profile query patterns and decide when to prefetch instead of guessing."}]),

  richLesson("Load Related Django Rows Without Repeating Queries", "The first two QuerySet lessons explained when a SELECT executes. This one explains how relationship access can trigger further SELECT statements—sometimes one per row—and how to pick the correct loading strategy from relationship direction.", ["Recognize N+1 as one parent query plus repeated related-object queries.","Measure a reverse one-to-many access pattern and fix it using prefetch_related.","Measure a forward ForeignKey access pattern and fix it using select_related.","Verify that query-count improvements preserve returned records, and recognize the cost of loading too much."], [
    { heading: "Why one Python loop can produce many SQL queries", body: "A Book and a ReadingListEntry are connected through a foreign key. When a QuerySet loads three ReadingListEntry rows, it may not have fetched each related Book; reading entry.book.title can then cause another SELECT for each entry. That is 1+3=4 queries in this example. The problem is the number of round trips growing with result size, even when each individual SQL statement is fast. It is not an error Django raises automatically." },
    { heading: "Know the relationship direction before choosing a fix", body: "From ReadingListEntry to Book, book is a single-valued ForeignKey. select_related('book') requests a SQL join and can fetch both sides in one query. From ReadingList to its many entries, entries is a reverse one-to-many relation; prefetch_related('entries') executes a second query and assembles matching entries in Python. A join over many child rows can duplicate parent data, so Django does not support selecting arbitrary many-valued relationships through select_related." },
    { heading: "Reproduce N+1 and the two repairs", body: "Use the exact three reading lists and entries from query_seed.py. Save this complete program and run it. CaptureQueriesContext measures only what executes inside each scope; the first two cases compare 4 with 2 queries. The next two compare 4 with 1. It also asserts that the returned data is identical after the optimization; reducing query count by accidentally dropping rows would not be a valid improvement.", code: { language: "python", caption: "catalogue/queryset_relations.py — N+1 before and after", value: "# Save as catalogue/queryset_relations.py.\nfrom django.db import connection\nfrom django.test.utils import CaptureQueriesContext\nfrom catalogue.models import ReadingList, ReadingListEntry\n\ndef memberships(lists):\n    return [\n        (reading_list.name,\n         sorted(entry.book_id for entry in reading_list.entries.all()))\n        for reading_list in lists\n    ]\n\nwith CaptureQueriesContext(connection) as plain_queries:\n    plain = memberships(ReadingList.objects.order_by(\"name\"))\nprint(\"reverse_plain_queries:\", len(plain_queries))\n\nwith CaptureQueriesContext(connection) as prefetch_queries:\n    prefetched = memberships(\n        ReadingList.objects.order_by(\"name\").prefetch_related(\"entries\")\n    )\nprint(\"reverse_prefetch_queries:\", len(prefetch_queries))\nprint(\"reverse_results_match:\", plain == prefetched)\n\nwith CaptureQueriesContext(connection) as repeated_queries:\n    plain_titles = [\n        entry.book.title\n        for entry in ReadingListEntry.objects.order_by(\"id\")\n    ]\nprint(\"forward_plain_queries:\", len(repeated_queries))\n\nwith CaptureQueriesContext(connection) as joined_queries:\n    joined_titles = [\n        entry.book.title\n        for entry in ReadingListEntry.objects.order_by(\"id\")\n        .select_related(\"book\")\n    ]\nprint(\"forward_join_queries:\", len(joined_queries))\nprint(\"forward_results_match:\", plain_titles == joined_titles)\n\nassert len(plain_queries) == 4\nassert len(prefetch_queries) == 2\nassert len(repeated_queries) == 4\nassert len(joined_queries) == 1\nassert plain == prefetched and plain_titles == joined_titles", output: "reverse_plain_queries: 4\nreverse_prefetch_queries: 2\nreverse_results_match: True\nforward_plain_queries: 4\nforward_join_queries: 1\nforward_results_match: True" } },
    { heading: "Run the experiment and see the effect", body: "Run this command after the fixture, and explain each number by identifying the main SQL SELECT plus the extra SELECTs on related objects. In production the exact cost depends on cardinality, filters, query planner, network latency and data volume: 2 queries are not universally better than 1 if prefetching loads an enormous collection nobody uses.", code: { language: "bash", caption: "Terminal — compare normal and eager relationship loading", value: "# From tsa-django-intro, in the folder containing manage.py:\npython manage.py shell -c \"exec(open('catalogue/queryset_relations.py').read())\"" } },
    { heading: "Why not prefetch everything?", body: "Each extra relationship loaded has a memory, data transfer and sometimes SQL cost. prefetch_related creates separate lookups and typically caches their related results; filters applied to the related manager after prefetch can produce a new query instead of using that cache. select_related can produce wide SQL joins. Profile the endpoint's actual access pattern and verify both result correctness and database workload before changing it." },
    { heading: "Practical diagnosis", body: "If you observe 1 instead of 4 for the unoptimized case, check whether related objects were already loaded or cached before the measurement. If the results do not match, inspect ordering and the exact queryset/relationship being loaded. If a queryset fails because entries is not a valid relation, inspect ReadingListEntry.reading_list.related_name and migrations. Never claim query-count measurements are response-time improvements without separate duration and workload evidence." },
  ], ["Run the exact reverse and forward relationship examples and record the four query counts with the reason for each.","Add a fourth reading list with one entry using the same models; predict and verify how the unoptimized and prefetched query counts change.","Change select_related('book') to select_related('reading_list') while still accessing entry.book.title; explain why N+1 persists.","Explain when a second query from prefetch_related is a deliberate performance improvement.","Only then apply the same measurement approach to Steward: service.owning_team for forward ForeignKey, and service.environments for a reverse collection if that actual related_name exists."], ["Which relationship direction supports select_related and why?","Why can 1+N queries be inefficient even if each SELECT runs quickly?","How do you know an optimization did not accidentally change which records were returned?","Why must your evidence distinguish query count from total API latency?"], [{"title":"Django 5.2 — Making queries","url":"https://docs.djangoproject.com/en/5.2/topics/db/queries/","kind":"documentation","purpose":"QuerySet creation, lookups, evaluation, matching SQL behavior and per-QuerySet caches."},{"title":"Django 5.2 — QuerySet API reference","url":"https://docs.djangoproject.com/en/5.2/ref/models/querysets/","kind":"reference","purpose":"Evaluation triggers, get/first/count/exists, select_related and prefetch_related."},{"title":"Django 5.2 — Database access optimization","url":"https://docs.djangoproject.com/en/5.2/topics/db/optimization/","kind":"reference","purpose":"Profile query patterns and decide when to prefetch instead of guessing."}]),

  richLesson("Steward SQL to Django ORM: One Canonical Domain", "PostgreSQL already taught Team, Service and Environment with explicit fields. Mapping those facts into Django must not silently change the canonical owning_team field into another name or mistake lifecycle production for a deployed Environment record. Build the Django model in a NEW, empty database; the previous SQL lab already has unmanaged tables, and Django does not own their migration history.", ["Map one Service identity and Team ownership to a Django ForeignKey.","Keep lifecycle development/uat/production/retired separate from Environment kind production.","Migrate in a fresh Django-managed lab rather than collision with the existing raw SQL fixture."], [{"heading":"Create a separate Django project and give it its own database","body":"Do not run Django migrations against the earlier manually seeded tsa_steward_lab. Start a *different* project directory from tsa-django-intro and a fresh virtual environment; reuse the concepts, not its catalogue files. Create the registry app yourself. These are terminal commands for a new scratch directory. Afterwards, provision or request an authorized EMPTY tsa_steward_django_lab PostgreSQL database and configure the project's DATABASES setting from environment variables. Do not hardcode a password or use a production role. makemigrations creates versioned operations, sqlmigrate shows SQL, and migrate applies it while tracking django_migrations. The former SQL fixture's rows are not automatically imported.","code":{"language":"bash","caption":"Terminal — start a separate Steward Django application","value":"mkdir tsa-steward-django-app && cd tsa-steward-django-app\npython3 -m venv .venv\nsource .venv/bin/activate\npython -m pip install 'Django>=5.2,<6' 'psycopg[binary]' djangorestframework\ndjango-admin startproject config .\npython manage.py startapp registry\npython manage.py check"}},{"heading":"Model durable facts with identical meanings","body":"In registry/models.py, define Team, Service, and Environment below. owning_team is the ForeignKey attribute; owning_team_id is the underlying database field. Service lifecycle is development/uat/production/retired and Environment kind is development/staging/production. The original SQL fixture also declared other constraints; this model is a readable initial bridge, not a claim that every earlier rule has already been migrated. Slug is a later explicit migration, not present in this initial SQL fixture.","code":{"language":"python","caption":"registry/models.py — canonical Steward ORM foundation","value":"from django.db import models\n\nclass Team(models.Model):\n    name = models.TextField(unique=True)\n    class Meta:\n        db_table = 'team'\n\nclass Service(models.Model):\n    class Lifecycle(models.TextChoices):\n        DEVELOPMENT = 'development', 'Development'\n        UAT = 'uat', 'UAT'\n        PRODUCTION = 'production', 'Production'\n        RETIRED = 'retired', 'Retired'\n    name = models.TextField(unique=True)\n    owning_team = models.ForeignKey(Team, on_delete=models.PROTECT)\n    endpoint = models.URLField()\n    lifecycle = models.CharField(max_length=12, choices=Lifecycle.choices, default=Lifecycle.DEVELOPMENT)\n    criticality = models.CharField(max_length=12, default='medium')\n    active = models.BooleanField(default=True)\n    retired_at = models.DateTimeField(null=True, blank=True)\n    class Meta:\n        db_table = 'service'\n\nclass Environment(models.Model):\n    class Kind(models.TextChoices):\n        DEVELOPMENT = 'development', 'Development'\n        UAT = 'uat', 'UAT'\n        STAGING = 'staging', 'Staging'\n        PRODUCTION = 'production', 'Production'\n    service = models.ForeignKey(Service, on_delete=models.PROTECT)\n    name = models.TextField()\n    kind = models.CharField(max_length=12, choices=Kind.choices)\n    class Meta:\n        db_table = 'environment'\n        constraints = [models.UniqueConstraint(fields=['service', 'name'], name='uq_env_service_name')]"}},{"heading":"Migrate the NEW database and prove a record","body":"In the new Steward project's virtual environment, install Django, psycopg and djangorestframework. Run python manage.py makemigrations registry, python manage.py sqlmigrate registry 0001, python manage.py migrate and python manage.py check. In python manage.py shell create a Team named Payments, a Service with that owning_team and lifecycle production, and a related Environment kind production. Query Service.objects.select_related('owning_team').values('name','owning_team__name','lifecycle'). Under Steward's application rule, promoting a Service to production must require a production Environment; the initial Django model alone does not enforce this cross-table condition. Its executable transactional protection is taught later. Those two fields answer different questions: lifecycle is the Service's stage; Environment.kind identifies a recorded deployment. A missing production Environment is a business-rule violation, even if the database accepts the individual rows."},{"heading":"Do not fake migration history as a shortcut","body":"The manually created PostgreSQL tables did not originate from these Django migrations. Using fake-initial over a schema with divergent fields, defaults, constraints or names can hide differences. If mapping a legacy database is truly required, inspectdb, managed=False, schema migration ownership and change planning become a separate project. This lesson teaches a clean educational bridge, not an unsafe production import."}], ["Set up a separate tsa_steward_django_lab with an authorized nonproduction role and verify the target before migration.","Write the models and check the generated migration operations against the canonical Team/Service/Environment facts.","Apply the migration to the empty lab; create one Service and one production Environment from Django shell.","Explain why the old owning_team and production-lifecycle snippets conflict with the SQL fixture."], ["Why does a new ORM project need migration ownership?","What column does owning_team create automatically?","Why is Service lifecycle production not proof that a production Environment exists?"], [{"title":"Django model relationships","url":"https://docs.djangoproject.com/en/5.2/topics/db/models/","kind":"documentation","purpose":"Model fields, ForeignKey and relationships."},{"title":"Django schema migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"Versioned schema changes and migration ownership."},{"title":"Django PostgreSQL notes","url":"https://docs.djangoproject.com/en/5.2/ref/databases/","kind":"documentation","purpose":"PostgreSQL connection and backend setup."}]),
  richLesson("Models and Domain Data", "Django models map Python objects to relational persistence, but database-shaped code should still reflect domain meaning. Fields, constraints, relationships and lifecycle values are part of Steward's behavior contract.", ["Model Steward concepts with appropriate fields and relationships.", "Distinguish database constraints from application validation.", "Use enums/choices deliberately."], [
    { heading: "Model the language of the domain", body: "A model class expresses domain facts using names with stable meaning. In the migrated registry from the previous lesson, Team represents ownership, Service represents the service record and Environment represents one deployment. The Python class name is not a guarantee about the SQL table name: inspect the Meta.db_table mapping and the migration. Save this complete read-only example as registry/inspect_models.py in the Django-managed Steward project, then run the command shown in the code caption. Import from registry.models in the top-level Django shell, never from .models without a package context. The _meta.fields inspection shows stored forward fields, including Django's default id and ForeignKeys, but does not by itself prove an entire database schema is up-to-date.", code: { language: "python", caption: "registry/inspect_models.py — inspect the migrated domain model", value: "# Run with: python manage.py shell -c \"exec(open('registry/inspect_models.py').read())\"\nfrom registry.models import Team, Service, Environment\n\nfor model in (Team, Service, Environment):\n    print(model.__name__, [field.name for field in model._meta.fields])\nprint(\"lifecycle_example:\", Service.Lifecycle.UAT)\nprint(\"deployment_kind_example:\", Environment.Kind.PRODUCTION)", output: "Team ['id', 'name']\nService ['id', 'name', 'owning_team', 'endpoint', 'lifecycle', 'criticality', 'active', 'retired_at']\nEnvironment ['id', 'service', 'name', 'kind']\nlifecycle_example: uat\ndeployment_kind_example: production" } },
    { heading: "Model classes map to relational structure", body: "A Django model class describes persistent fields and relationships at the Python layer. Instances represent rows conceptually; ForeignKey represents a relational reference rather than an embedded Python object. This layer should map the PostgreSQL facts you already designed rather than silently invent a different data model." },
    { heading: "Migrations version schema changes", body: "Changing a model class does not directly rewrite the database. makemigrations derives a versioned migration from model-state changes; migrate applies pending migration operations. Always inspect generated migrations because the framework cannot know your production data, locking tolerance or compatibility requirements." },
    { heading: "Apply the QuerySet skills to a real domain", body: "You already created and measured QuerySets in the independent catalogue. Apply those mechanics to the migrated Steward registry now. This is not a second introduction to Django query evaluation. In python manage.py shell inside tsa_steward_django_lab, import from registry.models—an unqualified from .models import would fail in the top-level interactive shell. get_or_create creates or retrieves a named Team and UAT Service; the name is unique so repeating this exercise should not create duplicate rows. This example deliberately uses UAT rather than creating a production Service without a production Environment, which would violate the cross-table readiness contract. The select_related query follows the owning_team ForeignKey; the one evaluated list contains one known row. A wrong lifecycle is rejected by full_clean() at the Python model-validation boundary; calling save() without full_clean() does not automatically enforce choices in the database.", code: { language: "python", caption: "registry/models_lab.py — safe UAT record and related query", value: "# Run within the Django-managed Steward registry project, not the catalogue.\nfrom django.core.exceptions import ValidationError\nfrom registry.models import Team, Service\n\nteam, _ = Team.objects.get_or_create(name=\"Django Workshop\")\nservice, _ = Service.objects.get_or_create(\n    name=\"Workshop Reports API\",\n    defaults={\n        \"owning_team\": team,\n        \"endpoint\": \"https://workshop.example.invalid/api\",\n        \"lifecycle\": Service.Lifecycle.UAT,\n    },\n)\nassert service.owning_team_id == team.pk\n\nquery = Service.objects.filter(pk=service.pk).select_related(\"owning_team\")\nprint(\"query_has_join:\", \"JOIN\" in str(query.query))\nrows = list(query)\nprint(\"returned_rows:\", len(rows))\nfor row in rows:\n    print(row.name, row.owning_team.name, row.lifecycle)\n\ninvalid = Service(\n    name=\"Invalid Example\", owning_team=team,\n    endpoint=\"https://workshop.example.invalid/invalid\",\n    lifecycle=\"launched\",\n)\ntry:\n    invalid.full_clean()\nexcept ValidationError as error:\n    assert \"lifecycle\" in error.message_dict\n    print(\"INVALID_LIFECYCLE_REJECTED\")\nelse:\n    raise AssertionError(\"An undefined lifecycle passed validation\")", output: "query_has_join: True\nreturned_rows: 1\nWorkshop Reports API Django Workshop uat\nINVALID_LIFECYCLE_REJECTED" } },
    { heading: "Persistence is not all validation", body: "A unique slug belongs naturally in the database. A rule such as 'retired services cannot accept new dependencies' may require application/domain logic because it spans state and operation semantics." },
    { heading: "Field classes map Python values to database representation", body: "CharField, BooleanField, DateTimeField, ForeignKey and other fields define conversion, validation metadata and schema intent. null controls database NULL for most fields; blank is primarily a validation/form concern. They are not interchangeable. Defaults may be values or callables and should represent legitimate domain defaults." },
    { heading: "Relationships have direction and deletion semantics", body: "ForeignKey models many-to-one and requires an on_delete policy such as PROTECT/RESTRICT/CASCADE/SET_NULL. OneToOneField models a unique single-valued relation. ManyToManyField uses an intermediary relation and is appropriate only when the relationship itself does not need richer domain fields—or an explicit through model can represent those fields." },
    { heading: "Meta carries model-level database intent", body: "Model Meta can declare constraints, indexes and default ordering. Prefer UniqueConstraint/CheckConstraint for durable invariants rather than relying only on serializer validation. Remember that default ordering affects every unqualified QuerySet and can add hidden sort cost." },
  ], ["Implement Team, Service and Environment models.", "Add at least one database-enforced constraint.", "Represent lifecycle/criticality deliberately.", "Document one rule that should not live only as a database field constraint."], ["What kinds of invariants belong in the database?", "Why are choices useful but insufficient for all domain rules?", "How can model names improve architectural clarity?"]),

  richLesson("ORM Query Behavior and Performance", "The ORM is a query-building interface over the relational model you already learned. Productive Django engineering means using that interface without losing sight of SQL execution, round trips or relationship cardinality.", ["Inspect generated SQL and QuerySet evaluation.", "Choose select_related versus prefetch_related from relationship shape.", "Detect and remove N+1 query patterns.", "Choose ORM versus parameterized SQL deliberately."], [
    { heading: "QuerySets are lazy descriptions", body: "Chaining filter(), exclude(), order_by() and relationship-loading methods normally builds a query description. Iteration, serialization and other evaluation operations cause database work. Inspect qs.query and query logs while learning so convenience stays connected to PostgreSQL behavior." },
    { heading: "N+1 is a round-trip pattern", body: "If one query loads 100 services and later access to service.owning_team causes another query for every service, the endpoint performs roughly 101 queries. Tiny development datasets can hide this. Measure query count instead of assuming the ORM optimized it." },
    { heading: "Load relationships intentionally", body: "`select_related` uses SQL joins for single-valued relationships such as ForeignKey/OneToOne. `prefetch_related` uses additional bounded queries and assembles multi-valued relationships in Python. Choose from cardinality and access pattern, then verify the generated behavior.", code: { language: "python", caption: "Bound query growth for service ownership", value: "qs = Service.objects.filter(lifecycle=Service.Lifecycle.PRODUCTION).select_related('owning_team')\nfor service in qs:\n    print(service.name, service.owning_team.name)" } },
    { heading: "ORM versus SQL is a design choice", body: "Routine model operations are usually clearer in the ORM. Complex reporting, PostgreSQL-specific capabilities or carefully tuned access paths may be clearer in parameterized SQL. Do not switch to raw SQL merely because ORM syntax is unfamiliar, and never interpolate untrusted values into SQL strings." },
    { heading: "Evaluation and QuerySet caching are related but not identical", body: "Iteration, list(), len(), bool(), slicing in some forms and serialization can evaluate a QuerySet. Once a QuerySet has fetched its result set, normal reuse of that same QuerySet can use its result cache; creating another equivalent QuerySet is still another query. Methods such as iterator() deliberately change caching behavior. Measure rather than assuming a Python variable means one database call." },
    { heading: "get, first, exists and count express different database questions", body: "get() expects exactly one row and raises model-specific DoesNotExist/MultipleObjectsReturned when that contract fails. first() asks for at most one ordered result. exists() asks whether any matching row exists without materializing the full result set. count() delegates a count query rather than loading every object merely to count in Python." },
    { heading: "Transactions remain PostgreSQL transactions", body: "django.db.transaction.atomic() defines an application-visible transaction boundary; nested atomic blocks can use savepoints. Do not hold transactions open across slow network work. Database constraints/isolation still determine correctness—the ORM does not create a separate transactional universe." },
  ], ["Implement a service query with a relationship.", "Inspect its generated SQL and record when evaluation occurs.", "Create an N+1 case intentionally and capture query count.", "Fix it using select_related or prefetch_related and compare counts.", "Implement one non-trivial query in both ORM and parameterized SQL and justify which representation you would keep."], ["What does QuerySet laziness mean operationally?", "Why is N+1 a scaling pattern rather than merely one slow query?", "When should select_related be preferred to prefetch_related?", "When can raw SQL be clearer than ORM code?"]),

  richLesson("Add a Field Without Losing Existing Django Rows", "Your first migration created empty tables. Real applications already contain rows. Learn an additive, backwards-compatible change on the existing Book model before you attempt uniqueness or a large data backfill.", ["Distinguish the current model file, generated migration, migration history and actual database state.","Add a nullable field to populated Book rows with an inspected SQL migration.","Prove old rows and primary keys survive, and distinguish a source change from an applied schema change."], [
    { heading: "Know what already exists", body: "Your earlier catalogue contains Books and related ReadingListEntry records. The database has applied migrations 0001 (Book) and 0002 (the reading lists). This lesson adds 0003. Start by running showmigrations catalogue and checking your Django DATABASES target; use only the disposable tsa-django-intro database, not the manually seeded PostgreSQL library or the Steward registry. A Python class is not the database. makemigrations writes a migration file, sqlmigrate shows proposed SQL and migrate changes the database; django_migrations records what ran." },
    { heading: "Add one optional field, not a whole new application", body: "In catalogue/models.py, replace only the existing Book definition with the following complete version; keep ReadingList and ReadingListEntry below it, as before. edition_note is nullable so existing books can legitimately have SQL NULL; blank=True also allows optional form validation. No value or default is invented for existing rows. The existing title uniqueness and published_year behavior stay unchanged.", code: { language: "python", caption: "catalogue/models.py — Book with an optional field", value: "from django.db import models\n\nclass Book(models.Model):\n    title = models.CharField(max_length=120, unique=True)\n    published_year = models.PositiveIntegerField()\n    edition_note = models.TextField(null=True, blank=True)\n\n    def __str__(self):\n        return self.title" } },
    { heading: "Generate, inspect and apply migration 0003", body: "Run the commands in order from the directory containing manage.py. makemigrations creates a catalogue 0003 AddField migration; inspect that generated Python file, then sqlmigrate 0003 before running migrate. showmigrations changes from [ ] to [X]. In the real SQL you should find an added edition_note column. Do not run migrate before reviewing the target database, especially if a classroom dataset is not disposable. Django may name the generated file differently, but its 0003 prefix and AddField operation are the stable contract.", code: { language: "bash", caption: "Terminal — inspect and apply an additive migration", value: "# From tsa-django-intro, in the directory containing manage.py:\npython manage.py check\npython manage.py makemigrations catalogue --noinput\npython manage.py sqlmigrate catalogue 0003\npython manage.py showmigrations catalogue\npython manage.py migrate catalogue --noinput\npython manage.py showmigrations catalogue" } },
    { heading: "Check existing data, not just the success message", body: "Save the program as catalogue/optional_migration_check.py and run it with python manage.py shell -c \"exec(open('catalogue/optional_migration_check.py').read())\". It checks that at least four existing rows are present, each initially has a NULL edition_note, and the same primary keys remain after updating only one note. This is a real persisted read-after-write, not a simulated model list.", code: { language: "python", caption: "catalogue/optional_migration_check.py — verify rows survive", value: "from catalogue.models import Book\n\nbefore = list(Book.objects.order_by(\"pk\").values_list(\"pk\", flat=True))\nassert len(before) >= 4\nassert Book.objects.filter(edition_note__isnull=True).count() == len(before)\nprint(\"old_rows_retained:\", len(before))\n\nriver = Book.objects.get(title=\"The River\")\nriver.edition_note = \"Checked in the migration lab\"\nriver.save(update_fields=[\"edition_note\"])\nassert Book.objects.get(pk=river.pk).edition_note == \"Checked in the migration lab\"\nassert list(Book.objects.order_by(\"pk\").values_list(\"pk\", flat=True)) == before\nprint(\"optional_field_updated: True\")\nprint(\"ids_unchanged: True\")", output: "old_rows_retained: 4\noptional_field_updated: True\nids_unchanged: True" } },
    { heading: "Diagnose a missing column and compatibility", body: "If you edit models.py but forget migrate, a query selecting edition_note will fail with a missing-column error. Check the database target and showmigrations rather than dropping tables. A nullable new field is generally easier for old application code to tolerate than removing or renaming a field; however this lab does not prove safe rolling deployment or zero downtime on a busy server. SQL changes may still take locks, depending on the database and operation." },
  ], ["Confirm the catalogue database and applied 0001/0002 migration history.","Add the optional field; run makemigrations, sqlmigrate and showmigrations before migrate.","Execute optional_migration_check.py; explain why existing IDs do not change.","Deliberately query the new field in a disposable environment before applying 0003, capture the missing-column error, then repair it by applying the intended migration.","Explain why setting a default value on every existing row would be a separate data-policy decision."], ["Why doesn't editing models.py add a PostgreSQL/SQLite column?","Which command generates source, which previews SQL and which applies the change?","Why is nullable an appropriate first state for a newly added optional field?","What database evidence must remain the same across this migration?"], [{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"Migration graph, state, historical models and RunPython."},{"title":"Django 5.2 — Writing migrations","url":"https://docs.djangoproject.com/en/5.2/howto/writing-migrations/","kind":"documentation","purpose":"Unique fields, staged data migration and non-atomic large-table alternatives."},{"title":"Django 5.2 — Migration operations","url":"https://docs.djangoproject.com/en/5.2/ref/migration-operations/","kind":"reference","purpose":"AddField, AlterField and RunPython state vs database semantics."}]),

  richLesson("Backfill a Unique Field Without Losing Data", "A unique required value needs more care than an optional note. Work through a deliberate collision and recovery in the same Book catalogue, with actual migration files and database evidence before transferring the method to Steward.", ["Apply schema expansion, historical-model data backfill and final constraint enforcement in separate migrations.","Explain why a slug generated from a title is not guaranteed unique.","Observe a migration failure that rolls back its writes, repair only the intentional collision and resume.","Prove row IDs, foreign-key relationships and final UNIQUE/NOT NULL constraints remain correct."], [
    { heading: "Why a single migration is dangerous", body: "A slug is a short URL-friendly string such as river-guide. Both 'River Guide' and 'river-guide' map to the same slug, even though their original titles are different and unique. Adding a required, unique slug in one migration over existing rows forces a default/collision policy that the framework cannot guess. We will use 0004 (nullable column), 0005 (data backfill), and 0006 (unique, non-null constraint). These are historical migration numbers for the clean catalogue progression; if your app has extra migrations, inspect its graph and adjust the dependencies rather than copying numbers blindly." },
    { heading: "Expand: make space for old rows", body: "Replace just the Book class in catalogue/models.py with this intermediate definition, keeping the related models. The new shelf_code allows NULL and is not unique yet. Run makemigrations catalogue to generate 0004, inspect its AddField, then apply only 0004. Never add a fake default to hide missing data. At this stage the old Book rows still work, but application writes must be coordinated: if live code writes shelf_code while a backfill is running, the migration needs an explicit conflict policy.", code: { language: "python", caption: "catalogue/models.py — nullable shelf_code stage", value: "from django.db import models\n\nclass Book(models.Model):\n    title = models.CharField(max_length=120, unique=True)\n    published_year = models.PositiveIntegerField()\n    edition_note = models.TextField(null=True, blank=True)\n    shelf_code = models.SlugField(max_length=160, null=True, blank=True)\n\n    def __str__(self):\n        return self.title" } },
    { heading: "Run 0004 and create the data-migration skeleton", body: "The code below creates 0004 from the intermediate model, previews its SQL, and applies the column change. The final command generates an empty 0005 whose dependency should point to 0004. Open the generated 0005_backfill_shelf_code.py file and replace its contents with the complete RunPython migration in the next section; do not leave it as an empty no-op migration.", code: { language: "bash", caption: "Terminal — expand and create the empty backfill migration", value: "# After changing only Book to add nullable shelf_code:\npython manage.py makemigrations catalogue --noinput\npython manage.py sqlmigrate catalogue 0004\npython manage.py migrate catalogue --noinput\n# Create the next file from Django so its dependency is correct:\npython manage.py makemigrations --empty catalogue --name backfill_shelf_code\n# Replace the contents of generated 0005_backfill_shelf_code.py\n# with the complete migration below, then inspect it before running migrate." } },
    { heading: "Seed a collision and preserve an independent snapshot", body: "Save catalogue/migration_baseline.py with the following program and run it through manage.py shell. Your earlier fixture contains River Guide; this adds a distinct title, river-guide, which slugify will map to the same code. The program saves every Book ID and every reading-list membership pair outside the database, so a later successful command cannot conceal lost relations. The counts may exceed the original three links if you completed earlier transfer exercises.", code: { language: "python", caption: "catalogue/migration_baseline.py — create deliberate collision and capture IDs", value: "import json\nfrom pathlib import Path\nfrom catalogue.models import Book, ReadingListEntry\n\nBook.objects.get_or_create(\n    title=\"river-guide\", defaults={\"published_year\": 2017}\n)\nbaseline = {\n    \"book_ids\": list(Book.objects.order_by(\"pk\").values_list(\"pk\", flat=True)),\n    \"entry_links\": [\n        list(pair)\n        for pair in ReadingListEntry.objects.order_by(\"pk\").values_list(\n            \"reading_list_id\", \"book_id\"\n        )\n    ],\n}\nPath(\"catalogue/migration_baseline.json\").write_text(\n    json.dumps(baseline), encoding=\"utf-8\"\n)\nprint(\"before_books:\", len(baseline[\"book_ids\"]))\nprint(\"before_links:\", len(baseline[\"entry_links\"]))\nprint(\"same_slug:\", \"river-guide\")" } },
    { heading: "Backfill through historical models, never the latest model import", body: "Place this exact file at catalogue/migrations/0005_backfill_shelf_code.py. Migration-time apps.get_model returns the frozen historical Book state. Importing catalogue.models.Book directly here would couple old migrations to future source changes. schema_editor.connection.alias keeps the operation on the database being migrated. An unexpected preexisting value, an empty slug or a duplicate causes ValueError. No reverse_code is supplied because automatically deleting slugs on downgrade would discard data; an irreversible data step requires a deliberate recovery plan.", code: { language: "python", caption: "catalogue/migrations/0005_backfill_shelf_code.py — historical backfill", value: "from django.db import migrations\nfrom django.utils.text import slugify\n\ndef fill_shelf_codes(apps, schema_editor):\n    Book = apps.get_model(\"catalogue\", \"Book\")\n    alias = schema_editor.connection.alias\n    seen = set()\n    for book in Book.objects.using(alias).order_by(\"pk\").iterator():\n        if book.shelf_code is not None:\n            raise ValueError(\"unexpected preexisting shelf code\")\n        code = slugify(book.title)\n        if not code or len(code) > 160 or code in seen:\n            raise ValueError(\"empty or duplicate shelf code: \" + repr(code))\n        seen.add(code)\n        book.shelf_code = code\n        book.save(update_fields=[\"shelf_code\"], using=alias)\n\nclass Migration(migrations.Migration):\n    dependencies = [(\"catalogue\", \"0004_book_shelf_code\")]\n    operations = [migrations.RunPython(fill_shelf_codes)]" } },
    { heading: "Observe the failed migration and its rollback", body: "Run python manage.py migrate catalogue --noinput with the collision still present. Expect a nonzero exit and a ValueError for river-guide. On PostgreSQL and the default SQLite setup, the migration is atomic: the previously updated slugs from this same migration are rolled back. Verify that all shelf_code values remain NULL and showmigrations lists 0005 as [ ], rather than assuming that a stack trace is proof of safe rollback. Do not bypass this by --fake. The program below changes only the intentionally conflicting training title while keeping its primary key.", code: { language: "python", caption: "catalogue/repair_shelf_collision.py — preserve the row and change its title", value: "from catalogue.models import Book\n\ncandidate = Book.objects.get(title=\"river-guide\")\ncandidate.title = \"River Guide Revised\"\ncandidate.full_clean()\ncandidate.save(update_fields=[\"title\"])\nprint(\"collision_repaired:\", candidate.pk)\nprint(\"code_still_empty:\", candidate.shelf_code is None)" } },
    { heading: "Retry the backfill after resolving the collision", body: "Run the repair program with python manage.py shell -c \"exec(open('catalogue/repair_shelf_collision.py').read())\", then run python manage.py migrate catalogue --noinput again. The 0005 migration now assigns distinct slugs. Check showmigrations for [X] 0005 and inspect values. Production workflows require an explicit policy for slug collisions; renaming this fictional book is only a safe exercise decision, not a universal production fix." },
    { heading: "Contract: require each code and make it unique", body: "Only after validating that no shelf_code is NULL and no duplicates remain, change Book to this final definition (keep the other two related models). Create catalogue/migrations/0006_require_unique_shelf_code.py exactly as printed next; the migration dependency is 0005. The explicit AlterField avoids Django's one-off-default prompt for changing nullable to nonnullable. Review sqlmigrate before applying. This is a small local example, not a promise that a large UNIQUE index can be built without locks.", code: { language: "python", caption: "catalogue/models.py — final required unique shelf_code", value: "from django.db import models\n\nclass Book(models.Model):\n    title = models.CharField(max_length=120, unique=True)\n    published_year = models.PositiveIntegerField()\n    edition_note = models.TextField(null=True, blank=True)\n    shelf_code = models.SlugField(max_length=160, unique=True)\n\n    def __str__(self):\n        return self.title" } },
    { heading: "The final schema migration is a real file", body: "Save this complete migration in catalogue/migrations/0006_require_unique_shelf_code.py. It changes the database rule to UNIQUE and NOT NULL after rows are backfilled. Attempting it earlier with NULLs or duplicates must be treated as a failure, not solved by fake migration history.", code: { language: "python", caption: "catalogue/migrations/0006_require_unique_shelf_code.py — enforce constraints", value: "from django.db import migrations, models\n\nclass Migration(migrations.Migration):\n    dependencies = [(\"catalogue\", \"0005_backfill_shelf_code\")]\n    operations = [\n        migrations.AlterField(\n            model_name=\"book\",\n            name=\"shelf_code\",\n            field=models.SlugField(max_length=160, unique=True),\n        ),\n    ]" } },
    { heading: "Inspect, apply and check model-state consistency", body: "Run these terminal commands from the Django project. The final makemigrations --check --dry-run is important: it verifies that current models.py agrees with the generated migration graph. If it proposes a surprise migration, inspect the field definitions and dependencies rather than committing drift.", code: { language: "bash", caption: "Terminal — apply the final constraint migration", value: "# After repairing the deliberate collision and successfully applying 0005:\n# Replace the Book class with the final version, retaining the other models.\n# Create 0006_require_unique_shelf_code.py exactly as shown below.\npython manage.py sqlmigrate catalogue 0006\npython manage.py migrate catalogue --noinput\npython manage.py showmigrations catalogue\npython manage.py makemigrations catalogue --check --dry-run" } },
    { heading: "Prove the original rows, relationships and constraints survived", body: "Save and run the verification script. It compares primary keys and membership pairs with the independent snapshot, checks every slug is present and distinct, then attempts two actual invalid writes. The database must reject a duplicate and a NULL code with IntegrityError. A successful HTTP response or just seeing [X] in showmigrations would not prove those invariants.", code: { language: "python", caption: "catalogue/verify_shelf_migration.py — positive and negative database evidence", value: "import json\nfrom pathlib import Path\nfrom django.db import IntegrityError\nfrom catalogue.models import Book, ReadingListEntry\n\nbefore = json.loads(\n    Path(\"catalogue/migration_baseline.json\").read_text(encoding=\"utf-8\")\n)\nafter_ids = list(Book.objects.order_by(\"pk\").values_list(\"pk\", flat=True))\nafter_links = [\n    list(pair)\n    for pair in ReadingListEntry.objects.order_by(\"pk\").values_list(\n        \"reading_list_id\", \"book_id\"\n    )\n]\nassert after_ids == before[\"book_ids\"]\nassert after_links == before[\"entry_links\"]\nprint(\"ids_and_links_preserved: True\")\n\ncodes = list(Book.objects.order_by(\"pk\").values_list(\"shelf_code\", flat=True))\nassert all(codes) and len(codes) == len(set(codes))\nprint(\"unique_shelf_codes:\", len(codes))\n\nduplicate = Book.objects.get(title=\"River Guide\")\ntry:\n    Book.objects.create(\n        title=\"Another River Book\", published_year=2025,\n        shelf_code=duplicate.shelf_code,\n    )\nexcept IntegrityError:\n    print(\"DUPLICATE_CODE_REJECTED\")\nelse:\n    raise AssertionError(\"The database accepted a duplicate shelf code\")\n\ntry:\n    Book.objects.create(\n        title=\"Missing Code Book\", published_year=2025, shelf_code=None,\n    )\nexcept IntegrityError:\n    print(\"NULL_CODE_REJECTED\")\nelse:\n    raise AssertionError(\"The database accepted a missing shelf code\")", output: "ids_and_links_preserved: True\nunique_shelf_codes: 5\nDUPLICATE_CODE_REJECTED\nNULL_CODE_REJECTED" } },
    { heading: "Rollback is not the same as undoing a failed step", body: "The failed 0005 operation rolled back automatically because it never completed. After it succeeds, RunPython without reverse_code is intentionally irreversible. You cannot assume python manage.py migrate catalogue 0004 restores the old application/database contract; doing so attempts to reverse a migration that has no safe reverse. Design restore/roll-forward decisions, data retention and old/new application compatibility before a real release. Large backfills may need non-atomic, separately batched jobs; an in-migration loop over millions of rows is not a production migration plan." },
  ], ["Complete migrations 0004/0005/0006 one stage at a time, with file/SQL/ledger evidence.","Prove 0005 fails with the deliberate duplicate slug, leaves no partial backfilled rows, and remains unapplied.","Repair only the fictional collision without deleting the row; rerun and validate all generated codes.","Run the final verification of stable IDs/links, nonnull unique slugs and two real database refusals.","Explain why a migration with RunPython.noop as a reverse could falsely imply data was undone.","Choose a safe deployment policy for new rows inserted between expand and backfill, and identify what requires a maintenance window or batching."], ["Why can two unique titles generate the same slug?","How do apps.get_model and a schema_editor alias differ from importing the live model?","Why is a failed atomic migration different from reversing a successful irreversible one?","Why should the schema be made strict only after inspecting populated rows?","When should a migration be split across deployment windows rather than run as one command?"], [{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"Migration graph, state, historical models and RunPython."},{"title":"Django 5.2 — Writing migrations","url":"https://docs.djangoproject.com/en/5.2/howto/writing-migrations/","kind":"documentation","purpose":"Unique fields, staged data migration and non-atomic large-table alternatives."},{"title":"Django 5.2 — Migration operations","url":"https://docs.djangoproject.com/en/5.2/ref/migration-operations/","kind":"reference","purpose":"AddField, AlterField and RunPython state vs database semantics."}]),

  richLesson("Schema Evolution with Django Migrations", "The Book exercise showed every step on a populated dataset. Now apply the same mechanism to a real multi-table domain and explain the additional decisions before shipping. Steward is the applied case here—not a prerequisite for understanding migrations.", ["Map the Book expand/backfill/contract sequence to a populated Service table.","Inspect complete Service migration files and predict their schema and data effects.","Demonstrate a repeatable slug collision without creating an invalid production Service.","Distinguish successful classroom execution from production deployment/rollback guarantees."], [
    { heading: "Four different states must agree", body: "Current registry/models.py is what application code expects. The migration graph describes versioned operations and dependencies. django_migrations records applied files. The database catalog and Service rows are the actual installed state. A green makemigrations or Python import cannot prove all four agree. This applied lab uses the isolated tsa_steward_django_lab with the canonical Team, Service and Environment models; do not point the commands at the manually created tsa_steward_lab SQL fixture or a live bank database." },
    { heading: "Record identity and ownership before touching the schema", body: "Before changing the model, save the script as registry/migration_identity_snapshot.py and run it from the initialized Django shell. It records the original Service primary-key-to-owner mapping and Environment primary-key-to-Service mapping in a local JSON evidence file. Later verification compares these mappings even if new training Services were added. A row count alone cannot prove the same rows survived.", code: { language: "python", caption: "registry/migration_identity_snapshot.py — preserve original IDs and foreign keys", value: "import json\nfrom pathlib import Path\nfrom registry.models import Service, Environment\n\nbaseline = {\n    \"service_owners\": [\n        list(pair) for pair in\n        Service.objects.order_by(\"pk\").values_list(\"pk\", \"owning_team_id\")\n    ],\n    \"environment_services\": [\n        list(pair) for pair in\n        Environment.objects.order_by(\"pk\").values_list(\"pk\", \"service_id\")\n    ],\n}\nPath(\"registry/migration_identity_baseline.json\").write_text(\n    json.dumps(baseline), encoding=\"utf-8\"\n)\nprint(\"original_services:\", len(baseline[\"service_owners\"]))\nprint(\"original_environments:\", len(baseline[\"environment_services\"]))" } },
    { heading: "Expand the Service model without breaking existing Services", body: "Add slug=models.SlugField(max_length=160, null=True, blank=True) immediately below Service.name in registry/models.py, keeping all other fields, constraints and relationships intact. Do not create a new model or change lifecycle/ownership. Save this complete initial migration as registry/migrations/0002_service_slug_nullable.py. Inspect sqlmigrate registry 0002 before applying migrate registry 0002. Confirm all prior Service IDs and owning_team_id values remain unchanged.", code: { language: "python", caption: "registry/migrations/0002_service_slug_nullable.py — expand", value: "from django.db import migrations, models\n\nclass Migration(migrations.Migration):\n    dependencies = [(\"registry\", \"0001_initial\")]\n    operations = [\n        migrations.AddField(\n            model_name=\"service\",\n            name=\"slug\",\n            field=models.SlugField(max_length=160, null=True, blank=True),\n        ),\n    ]" } },
    { heading: "Make a reproducible conflict without violating production readiness", body: "In the same Django-managed registry, save registry/create_slug_collision.py and run it using the initialized manage.py shell. It creates or reuses two UAT Services whose names differ but whose slugs collide. Never create a production-stage Service without a production Environment merely to test migrations. The executable source can safely run again without duplicating the fixture. Observe that the newly added slug column is still NULL for old records.", code: { language: "python", caption: "registry/create_slug_collision.py — two UAT Services with matching slug", value: "from registry.models import Team, Service\n\nteam, _ = Team.objects.get_or_create(name=\"Django Workshop\")\nService.objects.get_or_create(\n    name=\"Workshop Reports API\",\n    defaults={\n        \"owning_team\": team,\n        \"endpoint\": \"https://workshop.example.invalid/api\",\n        \"lifecycle\": Service.Lifecycle.UAT,\n    },\n)\nconflict, _ = Service.objects.get_or_create(\n    name=\"workshop-reports-api\",\n    defaults={\n        \"owning_team\": team,\n        \"endpoint\": \"https://workshop.example.invalid/another\",\n        \"lifecycle\": Service.Lifecycle.UAT,\n    },\n)\nprint(\"collision_service_pk:\", conflict.pk)\nprint(\"all_slugs_still_empty:\", not Service.objects.exclude(slug__isnull=True).exists())" } },
    { heading: "Backfill against the historical schema", body: "Save registry/migrations/0003_backfill_service_slugs.py exactly as printed. This migration uses apps.get_model for the historic Service class, filters against the actual database alias, checks duplicate generated slugs and saves through the same connection. It does not access Service.Lifecycle or instance methods, which historical models may not carry. It intentionally defines no reverse_code because deleting or resetting public identifiers is not a safe general downgrade.", code: { language: "python", caption: "registry/migrations/0003_backfill_service_slugs.py — detect and backfill", value: "from django.db import migrations\nfrom django.utils.text import slugify\n\ndef fill_service_slugs(apps, schema_editor):\n    Service = apps.get_model(\"registry\", \"Service\")\n    alias = schema_editor.connection.alias\n    seen = set()\n    for service in Service.objects.using(alias).order_by(\"pk\").iterator():\n        if service.slug is not None:\n            raise ValueError(\"unexpected existing Service slug\")\n        candidate = slugify(service.name)\n        if not candidate or len(candidate) > 160 or candidate in seen:\n            raise ValueError(\"empty or duplicate Service slug: \" + repr(candidate))\n        seen.add(candidate)\n        service.slug = candidate\n        service.save(update_fields=[\"slug\"], using=alias)\n\nclass Migration(migrations.Migration):\n    dependencies = [(\"registry\", \"0002_service_slug_nullable\")]\n    operations = [migrations.RunPython(fill_service_slugs)]" } },
    { heading: "Watch the actual collision failure and resolve it safely", body: "Run migrate registry with the conflict still present and capture the error. Show that 0003 remains unapplied and no slug values were partially persisted. Resolve only the fictional lower-case Service name using this complete script; keep its ID and owning Team. Then retry migrate registry --noinput and check all slugs are filled. Real conflicts require decisions about stable URLs, aliases and external references, not arbitrary production renames.", code: { language: "python", caption: "registry/repair_slug_collision.py — keep the Service identity", value: "from registry.models import Service\n\nconflict = Service.objects.get(name=\"workshop-reports-api\")\nconflict.name = \"Workshop Reports API Secondary\"\nconflict.full_clean()\nconflict.save(update_fields=[\"name\"])\nprint(\"service_collision_repaired:\", conflict.pk)" } },
    { heading: "Enforce the new contract only after inspection", body: "Change the model line to slug=models.SlugField(max_length=160, unique=True), then save this full migration file as registry/migrations/0004_require_unique_service_slug.py. Only after the historical backfill is applied and verified should you run sqlmigrate and migrate 0004. The final model and historical migration state must match under makemigrations --check --dry-run.", code: { language: "python", caption: "registry/migrations/0004_require_unique_service_slug.py — enforce", value: "from django.db import migrations, models\n\nclass Migration(migrations.Migration):\n    dependencies = [(\"registry\", \"0003_backfill_service_slugs\")]\n    operations = [\n        migrations.AlterField(\n            model_name=\"service\",\n            name=\"slug\",\n            field=models.SlugField(max_length=160, unique=True),\n        ),\n    ]" } },
    { heading: "Run the project-specific migration sequence", body: "These commands are a guide for the already-owned isolated Django lab, not instructions to connect to production. Create each numbered migration file only when the preceding stage is complete. The first migrate registry after adding 0003 must fail due to the deliberate collision; the next succeeds after the repair. Read the relevant file and run showmigrations at each stage.", code: { language: "bash", caption: "Terminal — staged Steward migration review", value: "# In the separate Django-managed PostgreSQL training database only.\n# Confirm its database name in Django settings and with SELECT current_database().\n# Add the nullable slug field to the existing Service class (keep other fields).\n# Create the three source-published migration files one stage at a time:\npython manage.py showmigrations registry\npython manage.py sqlmigrate registry 0002\npython manage.py migrate registry 0002 --noinput\n# Seed the collision, then create 0003_backfill_service_slugs.py.\npython manage.py migrate registry --noinput  # Expected to FAIL at 0003.\n# Fix the conflicting training Service name (see the repair example).\npython manage.py migrate registry --noinput  # 0003 succeeds.\n# Make slug required and unique in models.py; create 0004.\npython manage.py sqlmigrate registry 0004\npython manage.py migrate registry --noinput\npython manage.py makemigrations registry --check --dry-run" } },
    { heading: "Confirm rows and owners, then challenge the constraint", body: "Once the final migration is applied, run the verification program. It checks generated slugs and owning Team, then deliberately tries a new Service with a duplicate slug. The database, not a Python-only if statement, must reject it. Additionally compare all original Service IDs and ownership mappings captured before applying 0002; a renamed fictional Service must retain its original PK. The final successful query is not a substitute for a separate deployment safety review.", code: { language: "python", caption: "registry/verify_service_slugs.py — applied-domain check", value: "import json\nfrom pathlib import Path\nfrom django.db import IntegrityError\nfrom registry.models import Service, Team, Environment\n\nbaseline = json.loads(\n    Path(\"registry/migration_identity_baseline.json\").read_text(encoding=\"utf-8\")\n)\ncurrent_owners = dict(Service.objects.values_list(\"pk\", \"owning_team_id\"))\ncurrent_environments = dict(Environment.objects.values_list(\"pk\", \"service_id\"))\nassert all(\n    current_owners.get(pk) == owner\n    for pk, owner in baseline[\"service_owners\"]\n)\nassert all(\n    current_environments.get(pk) == service_id\n    for pk, service_id in baseline[\"environment_services\"]\n)\nprint(\"original_ids_and_owners_preserved: True\")\n\nservices = list(Service.objects.order_by(\"pk\"))\ncodes = [service.slug for service in services]\nassert all(codes) and len(codes) == len(set(codes))\nassert Service.objects.get(name=\"Workshop Reports API\").slug == \"workshop-reports-api\"\nassert Service.objects.get(name=\"Workshop Reports API Secondary\").slug == \"workshop-reports-api-secondary\"\nprint(\"service_slugs_valid:\", len(codes))\nprint(\"owner_still_present:\", Service.objects.get(\n    name=\"Workshop Reports API\"\n).owning_team.name == \"Django Workshop\")\n\nteam = Team.objects.get(name=\"Django Workshop\")\ntry:\n    Service.objects.create(\n        name=\"Another Report\", owning_team=team,\n        endpoint=\"https://workshop.example.invalid/more\",\n        lifecycle=Service.Lifecycle.UAT,\n        slug=\"workshop-reports-api\",\n    )\nexcept IntegrityError:\n    print(\"DUPLICATE_SERVICE_SLUG_REJECTED\")\nelse:\n    raise AssertionError(\"Service slug uniqueness was not enforced\")" } },
    { heading: "Choose deployment stages and rollback behavior deliberately", body: "In a busy PostgreSQL service, a one-shot in-migration backfill can hold a long transaction and locks. Concurrent writers can insert missing slugs between expansion and backfill; coordinate a write strategy or use a separate resumable, batched backfill when appropriate. PostgreSQL concurrent index creation requires non-atomic migration handling; do not introduce it as a generic command here without considering the database/version and service availability. A successful local migration is not proof of zero downtime or reversibility. Preserve a documented compatibility window before relying on the new field in every request; once external clients use slugs, changing or deleting them has an API contract cost." },
  ], ["Apply the fully authored 0002→0003→0004 migration files to the dedicated migrated Steward database only.","Show the actual ValueError on slug collision, the unapplied migration status, and the absence of partial writes.","Repair the one training Service name without changing its PK, confirm owner IDs survive, and apply the final unique/not-null contract.","Record generated SQL, migration statuses, before/after Service counts and a real database constraint rejection.","Explain at least two differences between the disposable Book example and a staffed, live service deployment."], ["Why is a migration file that imports the current Service class fragile?","What does the database know about a Service lifecycle or Team ownership when enforcing a slug UNIQUE constraint?","What kind of writer can defeat a one-time backfill when records are being created concurrently?","What makes rollback unsafe after public identifiers have been consumed by clients?"], [{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"Migration graph, state, historical models and RunPython."},{"title":"Django 5.2 — Writing migrations","url":"https://docs.djangoproject.com/en/5.2/howto/writing-migrations/","kind":"documentation","purpose":"Unique fields, staged data migration and non-atomic large-table alternatives."},{"title":"Django 5.2 — Migration operations","url":"https://docs.djangoproject.com/en/5.2/ref/migration-operations/","kind":"reference","purpose":"AddField, AlterField and RunPython state vs database semantics."}]),


  richLesson("Serializers and Representation", "A serializer is a boundary between external representations and trusted Python values. It should not be introduced only as a ModelSerializer tied to an existing application model. First prove field parsing, validation, read-only output and partial updates using an ordinary book dictionary; then apply that understanding to the Steward ORM models in the practical.", ["Distinguish JSON parsing, serializer validation, domain authorization and model/database persistence.","Define a plain Serializer, inspect initial_data, errors, validated_data and output .data.","Explain exactly how field validation, cross-field validation and read-only fields behave.","Demonstrate a partial update without assuming missing fields become NULL or that validation automatically saves records."], [
  {
    "heading": "Follow the data from HTTP bytes to a Python value",
    "body": "A client sends bytes with a media type, such as JSON. DRF's JSONParser turns those bytes into Python objects, usually dictionaries and lists. That is *not* proof the objects meet your API contract: a string, negative year or missing field can still be valid JSON. Serializer fields convert data into typed Python values, apply declared constraints and collect errors. Only after is_valid() succeeds can application code decide whether the caller is authorized and whether a database operation is allowed. Rendering happens in the opposite direction: the serializer's .data contains representable primitives, which a renderer turns into response bytes."
  },
  {
    "heading": "Begin with Serializer, not a hidden database model",
    "body": "Create catalogue/serializers.py in the same practice project where DRF is installed. This serializer does not import models and therefore can be understood without having created a database table. title must be nonblank; published_year is a valid integer in our deliberately constrained teaching range; format is either print or digital; a digital book requires a download_url. The book_id belongs to the server, so read_only=True includes it in output but never accepts it as a writable input. The chosen year range and digital-book policy are example requirements, not universal library facts.",
    "code": {
      "language": "python",
      "caption": "catalogue/serializers.py — complete plain serializer",
      "value": "from rest_framework import serializers\n\n\nclass BookSerializer(serializers.Serializer):\n    book_id = serializers.IntegerField(read_only=True)\n    title = serializers.CharField(allow_blank=False, max_length=120)\n    published_year = serializers.IntegerField(min_value=1450, max_value=2100)\n    format = serializers.ChoiceField(choices=['print', 'digital'])\n    download_url = serializers.URLField(required=False, allow_blank=True)\n\n    def validate_title(self, value):\n        if not value.strip():\n            raise serializers.ValidationError('Use a non-whitespace title.')\n        return value.strip()\n\n    def validate(self, attrs):\n        if attrs.get('format') == 'digital' and not attrs.get('download_url'):\n            raise serializers.ValidationError({'download_url': 'Required for a digital book.'})\n        return attrs"
    }
  },
  {
    "heading": "Observe validation as a separate step",
    "body": "Create serializer_lab.py at the root of tsa-django-intro. The script supplies external input, including book_id=999, which is deliberately read-only. Before is_valid(), initial_data contains what the caller sent. After validation, validated_data contains accepted writable values and omits book_id. The code does not call save(): this bare Serializer has no create/update implementation and has not inserted anything. Demonstrating validation before persistence prevents the false assumption that a Python serializer itself is a database.",
    "code": {
      "language": "python",
      "caption": "serializer_lab.py — run with python manage.py shell < serializer_lab.py",
      "value": "from catalogue.serializers import BookSerializer\n\npayload = {'book_id': 999, 'title': '  Beloved  ', 'published_year': 1987, 'format': 'print'}\nserializer = BookSerializer(data=payload)\nassert serializer.initial_data['book_id'] == 999\nassert serializer.is_valid(), serializer.errors\nassert serializer.validated_data['title'] == 'Beloved'\nassert 'book_id' not in serializer.validated_data\nprint('Accepted:', dict(serializer.validated_data))\n\noutgoing = BookSerializer(instance={\n    'book_id': 7, 'title': 'Beloved', 'published_year': 1987, 'format': 'print'\n})\nassert outgoing.data['book_id'] == 7\nprint('Rendered output data:', dict(outgoing.data))"
    }
  },
  {
    "heading": "Prove a field error and a cross-field error",
    "body": "A malformed publication year is rejected at the field boundary, before the object-level rule. A valid year with digital format and no download URL passes individual field parsing but fails validate(attrs), because the two fields together violate the example contract. Run the negative cases against the exact same serializer, then name which validation stage caused each result. Errors are structured data, not arbitrary print strings the API should reinterpret.",
    "code": {
      "language": "python",
      "caption": "serializer_negatives.py — expected independent failures",
      "value": "from catalogue.serializers import BookSerializer\n\nbad_year = BookSerializer(data={'title': 'Beloved', 'published_year': 'not-a-year', 'format': 'print'})\nassert not bad_year.is_valid()\nassert 'published_year' in bad_year.errors\n\nno_url = BookSerializer(data={'title': 'Digital Handbook', 'published_year': 2021, 'format': 'digital'})\nassert not no_url.is_valid()\nassert 'download_url' in no_url.errors\nprint('Rejected bad year and missing digital URL')"
    }
  },
  {
    "heading": "Understand partial=True without silently resetting fields",
    "body": "For an API PATCH, the client can send only the fields being changed. partial=True makes required-field checks tolerant of omitted input fields; it does not automatically change an existing instance or set omitted fields to NULL. The example below validates a title-only patch against an existing dictionary. The accepted data contains only title. We deliberately do NOT call save() because this serializer has no update() method. A production update must combine validated changes with the existing record and re-evaluate any domain invariants affected by the result, including cross-field rules where appropriate.",
    "code": {
      "language": "python",
      "caption": "serializer_patch.py — a partial payload, not an automatic database write",
      "value": "from catalogue.serializers import BookSerializer\n\nexisting = {'book_id': 7, 'title': 'Beloved', 'published_year': 1987, 'format': 'print'}\npatch = BookSerializer(instance=existing, data={'title': '  Beloved (new edition) '}, partial=True)\nassert patch.is_valid(), patch.errors\nassert dict(patch.validated_data) == {'title': 'Beloved (new edition)'}\nassert existing['published_year'] == 1987\nprint('Accepted PATCH fields:', dict(patch.validated_data))"
    }
  },
  {
    "heading": "Run the three scripts and inspect what did not happen",
    "body": "In the project root run python manage.py shell < serializer_lab.py, then repeat for serializer_negatives.py and serializer_patch.py. The three scripts operate only on Python dictionaries. They create no table and issue no SQL; this is intentional isolation of the representation boundary. If the import fails, confirm that catalogue/serializers.py exists and that the correct virtual environment is active. If an assertion fails, look at serializer.errors, not the PostgreSQL server log. Once this behavior is understood, compare a ModelSerializer: it generates fields from a Django model and usually supplies default create/update mapping, but it does not replace domain authorization or every database constraint.",
    "code": {
      "language": "bash",
      "caption": "Terminal — three independent serializer experiments",
      "value": "python manage.py shell < serializer_lab.py\npython manage.py shell < serializer_negatives.py\npython manage.py shell < serializer_patch.py"
    }
  },
  {
    "heading": "Apply the same rules to a Steward ModelSerializer",
    "body": "Only after you have successfully run the independent book serializer examples, return to the separate Django-managed Steward registry. ModelSerializer can derive fields and default persistence methods from an existing Django model, but it does not replace authorization, domain rules or database constraints. The identifier and Team owner below are server-controlled read-only fields; never let an untrusted client assign ownership merely because the model has a ForeignKey.",
    "code": {
      "language": "python",
      "caption":"Service serializer",
      "value": "from rest_framework import serializers\nfrom .models import Service\n\nclass ServiceSerializer(serializers.ModelSerializer):\n    class Meta:\n        model = Service\n        fields = ['id', 'name', 'endpoint', 'lifecycle', 'criticality', 'owning_team']\n        read_only_fields = ['id', 'owning_team']"
    }
  },
  {
    "heading": "Decide what belongs in a serializer",
    "body": "Basic input shape, type conversion, external field names, read-only fields and cross-field representation rules are strong serializer responsibilities. An operation such as authorizing a librarian to edit a restricted record or deciding whether a Service may become production-ready is a reusable application/domain decision and may also require a database transaction. Do not hide it in validate_title simply because that hook is available. Field validation is not authorization; server-generated IDs remain server-owned even when the client tries to send them."
  }
], ["Create catalogue/serializers.py and the three standalone scripts exactly as shown; execute them using the same virtual environment.","Write down initial_data, validated_data, output .data and errors for the observed cases, indicating which can be trusted at each stage.","Explain why the incoming book_id is ignored for writes yet included in read output.","Prove that a title-only partial input does not erase published_year, and describe what a real update() method would still need to do.","Before using ModelSerializer in Steward, list two authorization/domain requirements that serializer field parsing cannot guarantee."], ["What is the difference between JSONParser and BookSerializer.is_valid()?","What distinguishes field validation from validate(attrs), and when does it run?","Why does is_valid() not imply that a database row has been created?","What does partial=True allow, and what does it *not* do?"]),
  richLesson("Views, ViewSets and Routing", "DRF offers several ways to connect an HTTP method to Python code. The right choice is the smallest abstraction that makes routing, validation, persistence and permissions understandable. Use the plain serializer you just tested and a deliberately read-only in-memory catalogue to compare a function view, an APIView and a router-backed ViewSet before moving to database-driven ModelViewSet in Steward.", ["Explain which work belongs in a view and which belongs in a serializer or application service.","Build one APIView with explicitly routed GET and POST and no hidden database assumptions.","Build a ViewSet with list/retrieve actions and inspect exactly which URLs a router generates.","Distinguish routing/HTTP dispatch from authorization and persistence; know when ModelViewSet would be unsafe without scoping."], [
  {
    "heading": "Start with the view you already know",
    "body": "The earlier DRF @api_view(['POST']) example is a function-based view: it names accepted methods directly, inspects request.data and returns a Response. A view coordinates one HTTP operation, it does not create its own database. APIView groups methods in a class and runs DRF parsing, authentication, permissions and rendering around them. Generic views add standard queryset/serializer behavior. ViewSets group related actions, and routers generate URL patterns. These are *alternatives for dispatch*, not increasingly advanced concepts that every project must use."
  },
  {
    "heading": "Use APIView when the request flow should be explicit",
    "body": "Create catalogue/book_api.py. The GET method returns two fixed records with IDs, and the POST method uses the BookSerializer taught in the previous lesson. Input validation happens before returning a 201 response; our demonstration assigns a fixed teaching ID but intentionally does not save data. A later GET will still show the original two books. Explain why a 201 representation does not prove persistence: a real create endpoint must perform an authorized durable write before promising success. This is an isolated mechanics lab, not a recommended production create implementation.",
    "code": {
      "language": "python",
      "caption": "catalogue/book_api.py — explicit class-based dispatch",
      "value": "from rest_framework.response import Response\nfrom rest_framework.status import HTTP_201_CREATED\nfrom rest_framework.views import APIView\nfrom .serializers import BookSerializer\n\nBOOKS = [\n    {'book_id': 1, 'title': 'Beloved', 'published_year': 1987, 'format': 'print'},\n    {'book_id': 2, 'title': 'Things Fall Apart', 'published_year': 1958, 'format': 'print'},\n]\n\n\nclass BookAPIView(APIView):\n    def get(self, request):\n        return Response(BookSerializer(BOOKS, many=True).data)\n\n    def post(self, request):\n        serializer = BookSerializer(data=request.data)\n        serializer.is_valid(raise_exception=True)\n        response_record = {'book_id': 99, **serializer.validated_data}\n        return Response(BookSerializer(response_record).data, status=HTTP_201_CREATED)"
    }
  },
  {
    "heading": "Bind an APIView to one explicit URL",
    "body": "A class itself is not a URL. Django URL dispatch requires a callable; APIView.as_view() builds it. Add the following import and path to the *existing* catalogue/urls.py rather than replacing the previously working books/ and greet/ routes. The class maps GET and POST to separate methods; a PUT without a handler receives 405. If you see 404, debug the URL first rather than the serializer.",
    "code": {
      "language": "python",
      "caption": "catalogue/urls.py — add these lines, keep existing urlpatterns",
      "value": "from .book_api import BookAPIView\n\n# Append to your existing urlpatterns list:\nurlpatterns += [path('books-demo/', BookAPIView.as_view(), name='books-demo')]"
    }
  },
  {
    "heading": "Check method dispatch, validation and the non-persistent contract",
    "body": "Run the existing Django development server, then send the following requests. GET returns two book objects. Valid POST returns 201 with teaching ID 99; invalid POST with no title returns 400. GET after POST still returns two objects because BOOKS is a constant in Python, not a table. A real API that claims record creation must persist and then retrieve the new record; this lesson deliberately refuses to confuse an HTTP demonstration with a working database-backed service.",
    "code": {
      "language": "bash",
      "caption": "Terminal B — prove GET, 201, 400 and unchanged GET",
      "value": "curl -i http://127.0.0.1:8000/catalogue/books-demo/\ncurl -i -X POST http://127.0.0.1:8000/catalogue/books-demo/ -H 'Content-Type: application/json' -d '{\"title\":\"Home\",\"published_year\":2012,\"format\":\"print\"}'\ncurl -i -X POST http://127.0.0.1:8000/catalogue/books-demo/ -H 'Content-Type: application/json' -d '{\"published_year\":2012,\"format\":\"print\"}'\ncurl -i http://127.0.0.1:8000/catalogue/books-demo/"
    }
  },
  {
    "heading": "What problem does a ViewSet solve?",
    "body": "If one resource has list and detail operations, repeatedly hand-writing routes becomes tedious. DRF's ViewSet names actions such as list(request) and retrieve(request, pk); a router translates collection and detail HTTP URLs into those methods. Create the following read-only demonstration ViewSet. It uses the same two fixed rows and returns 404 when an ID does not exist. This lab avoids ModelViewSet because it would silently introduce model and database writes we have not supplied.",
    "code": {
      "language": "python",
      "caption": "catalogue/viewset_demo.py — named actions over a fixed catalogue",
      "value": "from rest_framework.exceptions import NotFound\nfrom rest_framework.response import Response\nfrom rest_framework.viewsets import ViewSet\nfrom .book_api import BOOKS\nfrom .serializers import BookSerializer\n\n\nclass BookViewSet(ViewSet):\n    def list(self, request):\n        return Response(BookSerializer(BOOKS, many=True).data)\n\n    def retrieve(self, request, pk=None):\n        match = next((book for book in BOOKS if str(book['book_id']) == str(pk)), None)\n        if match is None:\n            raise NotFound('Book does not exist.')\n        return Response(BookSerializer(match).data)"
    }
  },
  {
    "heading": "Register a router and inspect the actual URL table",
    "body": "Use SimpleRouter for this lab. In catalogue/urls.py append the two imports and the new URL patterns; this preserves all earlier routes and makes the generated paths /catalogue/router-books/ and /catalogue/router-books/2/. We use a distinct prefix to avoid conflicting with the plain Django /catalogue/books/ endpoint. The router basename is important when no queryset/model is declared, because the router cannot infer a model name.",
    "code": {
      "language": "python",
      "caption": "catalogue/urls.py — append a ViewSet through SimpleRouter",
      "value": "from rest_framework.routers import SimpleRouter\nfrom .viewset_demo import BookViewSet\n\nrouter = SimpleRouter()\nrouter.register('router-books', BookViewSet, basename='router-book')\nurlpatterns += router.urls"
    }
  },
  {
    "heading": "Prove the router is mapping list and retrieve actions",
    "body": "The router-generated collection URL calls list; the detail URL passes pk and calls retrieve. A non-existent ID should return 404 through NotFound; POST to the read-only collection should return 405 because no create action was defined. The router did not decide any business permission or persist a book. These request checks make action mapping visible without adding ORM complexity.",
    "code": {
      "language": "bash",
      "caption": "Terminal B — list, retrieve, missing resource and unsupported write",
      "value": "curl -i http://127.0.0.1:8000/catalogue/router-books/\ncurl -i http://127.0.0.1:8000/catalogue/router-books/2/\ncurl -i http://127.0.0.1:8000/catalogue/router-books/999/\ncurl -i -X POST http://127.0.0.1:8000/catalogue/router-books/"
    }
  },
  {
    "heading": "Choose abstractions for responsibilities, not prestige",
    "body": "A ModelViewSet offers list/create/retrieve/update/partial_update/destroy when backed by a model, serializer and queryset. That is useful for a genuine CRUD resource but dangerous if a broad queryset exposes another tenant's records or if default update/delete actions violate application invariants. Pick @api_view when there is one transparent operation; APIView when distinct methods need explicit orchestration; a generic view for straightforward model-backed CRUD; and ViewSet/router when many related actions justify generated routes. In Steward's actual application practical, enforce ownership/authorization and durable writes in the correct layers before enabling broad actions. Never adopt an abstraction simply to remove a few lines of code."
  }
], ["Build the APIView and router-backed ViewSet as complete separate mechanisms over the same two book records.","Record the GET, valid POST, rejected POST, router detail, missing detail and unsupported write HTTP statuses.","Explain why the POST in this scratch lab is not a valid persisted create operation; show which part of a real API would have to change.","Compare manually registered APIView routes with router-generated ViewSet routes; identify which code controls methods and which controls paths.","In the Steward practical, justify the chosen abstraction by actual operation contracts, queryset scoping, permissions and transaction boundaries."], ["What does APIView.as_view() do that an uninstantiated class cannot?","How do a ViewSet's list and retrieve methods become URLs?","Why could ModelViewSet be unsafe with Service.objects.all() and no permission policy?","How would you distinguish a routing 404 from NotFound raised after a matching route?"]),
  richLesson("Persist a Book Through a Real DRF API", "You now know Django models, migrations, QuerySets, serializers and HTTP dispatch independently. Connect them in one genuine persisted request flow before taking on Steward's production and access-control rules.", ["Build a database-backed list/create/detail/patch API without hidden project setup.","Explain the difference between is_valid(), serializer.save() and persisted database state.","Prove a new request sees a saved row and a PATCH preserves omitted fields.","Verify invalid input, duplicate code, missing resource and unsupported-method failures with unchanged data."], [
    { heading: "Why another lesson after APIView?", body: "The previous APIView returned 201 and a made-up book ID but did not call save(). That intentionally taught HTTP dispatch in isolation. You now have a real Book table from the earlier migrations and understand serializer validation, so it is time to join the layers. A real create operation must validate the input, persist a row, and return an accurate status and representation. This lesson uses a disposable catalogue only; authorization and multi-table production invariants will be added in the Steward practical." },
    { heading: "Start from the actual Book schema", body: "Use the same tsa-django-intro project after the completed schema migration lessons. Its Book model has id, title, published_year, optional edition_note and a required unique shelf_code. Confirm python manage.py showmigrations catalogue shows migrations 0001 through 0006 applied. If you skipped the migration exercises, do not blindly add these files and expect POST to work: complete those prerequisites or inspect the actual Book model and adapt deliberately." },
    { heading: "A ModelSerializer maps an existing model into input and output fields", body: "Create catalogue/stored_serializers.py with the complete code below. ModelSerializer derives field conversions and default create/update operations from Book. Its is_valid() checks required input and some uniqueness constraints; a successful validation is still not a database write. The server assigns id; the client cannot force a row's primary key simply by including an id in JSON. The database UNIQUE constraint remains authoritative if concurrent requests race.", code: {language: "python", caption: "catalogue/stored_serializers.py — model-backed input and representation", value: "from rest_framework import serializers\nfrom .models import Book\n\nclass StoredBookSerializer(serializers.ModelSerializer):\n    class Meta:\n        model = Book\n        fields = [\"id\", \"title\", \"published_year\", \"edition_note\", \"shelf_code\"]\n        read_only_fields = [\"id\"]" } },
    { heading: "Call save() only after successful validation", body: "Create catalogue/stored_api.py. The collection GET reads real rows and returns a serialized list. POST parses request.data, calls is_valid(raise_exception=True), then serializer.save(), which uses ModelSerializer's default create() to insert one Book. Only afterwards does the handler return 201 and the new representation. The detail GET fetches the row by a real integer primary key; missing IDs produce 404. PATCH passes the current instance and partial=True so default update() changes only submitted fields. These are four explicit operations, without an unexplained ModelViewSet or hidden database work.", code: {language: "python", caption: "catalogue/stored_api.py — real GET, POST and PATCH operations", value: "from django.shortcuts import get_object_or_404\nfrom rest_framework import status\nfrom rest_framework.response import Response\nfrom rest_framework.views import APIView\n\nfrom .models import Book\nfrom .stored_serializers import StoredBookSerializer\n\nclass StoredBooks(APIView):\n    def get(self, request):\n        rows = Book.objects.order_by(\"pk\")\n        return Response(StoredBookSerializer(rows, many=True).data)\n\n    def post(self, request):\n        serializer = StoredBookSerializer(data=request.data)\n        serializer.is_valid(raise_exception=True)\n        book = serializer.save()\n        return Response(\n            StoredBookSerializer(book).data,\n            status=status.HTTP_201_CREATED,\n        )\n\nclass StoredBookDetail(APIView):\n    def get(self, request, book_id):\n        book = get_object_or_404(Book, pk=book_id)\n        return Response(StoredBookSerializer(book).data)\n\n    def patch(self, request, book_id):\n        book = get_object_or_404(Book, pk=book_id)\n        serializer = StoredBookSerializer(\n            book, data=request.data, partial=True\n        )\n        serializer.is_valid(raise_exception=True)\n        updated = serializer.save()\n        return Response(StoredBookSerializer(updated).data)" } },
    { heading: "Register both routes without deleting earlier endpoints", body: "Append these imports and paths to the existing catalogue/urls.py file, keeping previous books/, greet/, books-demo/ and router-books/ routes intact. The project-level config/urls.py already delegates the catalogue prefix. The URL pattern chooses a function to handle requests; it does not itself validate or save a book. The detail URL uses a named book_id integer, which is passed to StoredBookDetail.", code: {language: "python", caption: "catalogue/urls.py — append real stored-book routes", value: "from .stored_api import StoredBooks, StoredBookDetail\n\n# Append to the existing catalogue/urls.py urlpatterns:\nurlpatterns += [\n    path(\"stored-books/\", StoredBooks.as_view(), name=\"stored-book-list\"),\n    path(\"stored-books/<int:book_id>/\", StoredBookDetail.as_view(),\n         name=\"stored-book-detail\"),\n]" } },
    { heading: "Prove a row survives a second request and a partial update", body: "Save the full script below as catalogue/stored_request_lab.py and run it once against your disposable training database. It uses Django's test Client, which dispatches real framework requests without needing an external HTTP server. It records the initial row count, POSTs a valid unique Book, and verifies the new ID exists in the database. A *new* Client then retrieves the row. PATCH changes only edition_note while title, year and shelf_code remain intact. Do not invent a second database or assume a 201 alone proves anything.", code: {language: "python", caption: "catalogue/stored_request_lab.py — persistent HTTP flow with failures", value: "import json\nfrom django.test import Client\nfrom catalogue.models import Book\n\nc = Client()\nbefore = Book.objects.count()\npayload = {\n    \"title\": \"Stored API Test Book\",\n    \"published_year\": 2020,\n    \"shelf_code\": \"stored-api-test-book\",\n}\ncreated = c.post(\n    \"/catalogue/stored-books/\",\n    data=json.dumps(payload),\n    content_type=\"application/json\",\n)\nassert created.status_code == 201, created.content\nbook_id = created.json()[\"id\"]\nassert Book.objects.filter(pk=book_id).count() == 1\nprint(\"CREATE_201_SAVED\")\n\nfresh = Client().get(f\"/catalogue/stored-books/{book_id}/\")\nassert fresh.status_code == 200\nassert fresh.json()[\"shelf_code\"] == \"stored-api-test-book\"\nassert any(\n    item[\"id\"] == book_id\n    for item in Client().get(\"/catalogue/stored-books/\").json()\n)\nprint(\"FRESH_REQUEST_READ_200\")\n\nchanged = c.patch(\n    f\"/catalogue/stored-books/{book_id}/\",\n    data=json.dumps({\"edition_note\": \"Checked through PATCH\"}),\n    content_type=\"application/json\",\n)\nassert changed.status_code == 200, changed.content\nstored = Book.objects.get(pk=book_id)\nassert stored.edition_note == \"Checked through PATCH\"\nassert stored.title == payload[\"title\"]\nassert stored.published_year == payload[\"published_year\"]\nassert stored.shelf_code == payload[\"shelf_code\"]\nprint(\"PATCH_CHANGED_ONLY_NOTE\")\n\ninvalid = c.post(\n    \"/catalogue/stored-books/\",\n    data=json.dumps({\"published_year\": 2022,\n                     \"shelf_code\": \"no-title-book\"}),\n    content_type=\"application/json\",\n)\nassert invalid.status_code == 400 and \"title\" in invalid.json()\nprint(\"MISSING_TITLE_400\")\n\nduplicate = c.post(\n    \"/catalogue/stored-books/\",\n    data=json.dumps({\"title\": \"Another Stored Book\",\n                     \"published_year\": 2022,\n                     \"shelf_code\": \"stored-api-test-book\"}),\n    content_type=\"application/json\",\n)\nassert duplicate.status_code == 400\nassert \"shelf_code\" in duplicate.json()\nassert Book.objects.count() == before + 1\nprint(\"DUPLICATE_SLUG_400_NO_WRITE\")\n\nassert c.get(\"/catalogue/stored-books/999999/\").status_code == 404\nassert c.post(f\"/catalogue/stored-books/{book_id}/\").status_code == 405\nprint(\"MISSING_404_AND_UNSUPPORTED_405\")\nprint(\"STORED_BOOK_API_OK\")", output: "CREATE_201_SAVED\nFRESH_REQUEST_READ_200\nPATCH_CHANGED_ONLY_NOTE\nMISSING_TITLE_400\nDUPLICATE_SLUG_400_NO_WRITE\nMISSING_404_AND_UNSUPPORTED_405\nSTORED_BOOK_API_OK" } },
    { heading: "Inspect the errors and prove they made no rows", body: "An omitted title returns 400 because ModelSerializer rejects required input. A different book with an already-used shelf_code also returns 400 through the serializer's uniqueness validation; the database still enforces that constraint even if two requests both pass a race-prone precheck. The script asserts no additional row exists after these rejected POSTs. A nonexistent detail ID returns 404 from get_object_or_404; POST to the detail route returns 405 because no post() method exists. HTTP status and unchanged database state are separate assertions." },
    { heading: "Run from a terminal and verify persistence after a new Python process starts", body: "Use these terminal commands from the directory containing manage.py. The last command opens a new Django shell after the test script has exited and reads edition_note from the database. This is stronger evidence than inspecting the Python variable created during POST. The script uses a fixed unique title and code for reproducibility: run it once on a clean lab; a second full run should reject the duplicate rather than create a second copy.", code: {language: "bash", caption: "Terminal — test and independently reopen the persisted row", value: "# From the same tsa-django-intro directory containing manage.py:\npython manage.py check\npython manage.py shell -c \"exec(open('catalogue/stored_request_lab.py').read())\"\n# After the first shell process exits, verify persistence in another:\npython manage.py shell -c \"from catalogue.models import Book; print(Book.objects.get(shelf_code='stored-api-test-book').edition_note)\"", output: "Checked through PATCH" } },
    { heading: "Boundary: persistence is not authorization or business correctness", body: "This catalogue deliberately uses DRF's default permissions for a disposable local exercise. It is not safe as a multi-tenant production API: there are no ownership checks, authenticated principals, rate limits or explicit domain commands. A ModelSerializer.save() may write an individually valid row while violating a cross-table invariant that only application services and controlled database paths protect. Steward's production readiness and authorization are taught next, and you must not lift this open catalogue API unchanged into Steward." },
    { heading: "Diagnose real mistakes", body: "If POST returns 404, inspect the project-level include and catalogue/urls.py routes before changing serializers. If POST returns 400, inspect response.json() to see the field errors. If a missing-table or missing-column exception appears, check the active DATABASES setting and showmigrations catalogue; source models do not automatically update the database. If response is 201 but a new request cannot find the row, inspect where and whether save() actually executed, and whether the two requests pointed at the same database. Never make a test pass by deleting unrelated learning data." },
  ], ["Create the complete ModelSerializer, APIView and route files in the existing catalogue project after the Book slug migration.","Run the published stored_request_lab.py from a new Django shell; capture every status and the database row count before/after negative requests.","Close that shell, start another and retrieve the stored title and edition note by shelf_code to prove persistence across interpreter sessions.","Change only the year through PATCH, explain how default update differs from create, and prove title and shelf_code remain unchanged.","Remove serializer.save() temporarily in a disposable copy, predict why a 201-shaped response cannot establish persistence and restore the correct implementation.","Explain which authorization and multi-table domain rules must be added before adapting this code to the Steward Service API."], ["What changed when you called serializer.save() after is_valid()?","Why do we check the saved database row separately from a POST status?","What does partial=True preserve in the existing Book, and what does it not guarantee about unrelated domain rules?","Why is a duplicate slug 400 in this example while a concurrent race still needs a database UNIQUE constraint?","What would be unsafe about exposing this open catalogue handler in a production multi-tenant registry?"], [{"title":"DRF — Serializers and ModelSerializer","url":"https://www.django-rest-framework.org/api-guide/serializers/","kind":"documentation","purpose":"Differences between is_valid, save, ModelSerializer default create/update and partial fields."},{"title":"DRF — APIView","url":"https://www.django-rest-framework.org/api-guide/views/","kind":"documentation","purpose":"Method dispatch, parsing, exceptions and response rendering."},{"title":"Django 5.2 — Test client","url":"https://docs.djangoproject.com/en/5.2/topics/testing/tools/","kind":"documentation","purpose":"In-process HTTP requests and captured status/JSON outcomes."}]),

  richLesson("Production Readiness Commands and Atomic Updates", "The PostgreSQL lesson proved that a production-stage Service with no production Environment violates the Steward product rule even when its foreign keys are valid. Now place that rule in one reusable Django application command—not in an incidental view, serializer or a database constraint that cannot see related rows. Two operations must preserve it: promoting a Service and removing its last production deployment. This lesson requires PostgreSQL and the canonical Django models built earlier.", ["Implement a real two-table readiness invariant in a Django application command.","Explain why a row lock and atomic transaction coordinate cooperating mutation paths.","Run and inspect the failed promotion, successful promotion and blocked last-deployment deletion.","Identify the security boundary that must authenticate and authorize the caller before these commands execute."], [{"heading":"The contract is about two tables and two operations","body":"A Service lifecycle change from UAT to production must not commit if no related production Environment exists. Deleting the last production Environment is prohibited while the Service remains in the production lifecycle. These rules are independent of whether a client used a ViewSet, a management command or a background worker; a reusable application/domain operation is a better home than copying checks across HTTP handlers. We deliberately model a business exception separately from JSON error mapping."},{"heading":"Write actual transaction-safe application operations","body":"Save the following as registry/services.py after creating the canonical Django-managed model. transaction.atomic opens the transaction; select_for_update locks the Service row in PostgreSQL until the transaction ends, coordinating the two operations when both paths honor the same rule. The existence query checks the recorded Environment.kind, not lifecycle labels alone. A failed check raises ReadinessConflict before committing a changed Service. These functions presume the caller already verified authenticated Team authority; they are not a complete security implementation.","code":{"language":"python","caption":"registry/services.py — protect production transitions and last-deployment deletion","value":"from django.db import transaction\nfrom .models import Service, Environment\n\nclass ReadinessConflict(Exception):\n    pass\n\ndef promote_to_production(service_id):\n    with transaction.atomic():\n        service = Service.objects.select_for_update().get(pk=service_id)\n        deployed = Environment.objects.filter(\n            service_id=service_id,\n            kind=Environment.Kind.PRODUCTION,\n        ).exists()\n        if not deployed:\n            raise ReadinessConflict(\"production environment required\")\n        service.lifecycle = Service.Lifecycle.PRODUCTION\n        service.save(update_fields=[\"lifecycle\"])\n        return service\n\ndef remove_environment(environment_id):\n    with transaction.atomic():\n        environment = Environment.objects.get(pk=environment_id)\n        service = Service.objects.select_for_update().get(pk=environment.service_id)\n        last_production = (\n            service.lifecycle == Service.Lifecycle.PRODUCTION\n            and environment.kind == Environment.Kind.PRODUCTION\n            and not Environment.objects.filter(\n                service_id=service.id, kind=Environment.Kind.PRODUCTION,\n            ).exclude(pk=environment.id).exists()\n        )\n        if last_production:\n            raise ReadinessConflict(\"cannot remove final production environment\")\n        environment.delete()"}},{"heading":"Execute the three outcomes against a fresh Service","body":"Create a new Team and a Service initially in lifecycle UAT with a UAT Environment only. Calling promote_to_production should raise ReadinessConflict and leave lifecycle UAT. Now create a production Environment. Promote again and read back the saved lifecycle from the database: it must equal production. Finally call remove_environment with that only production Environment ID; the function must raise and the deployment row must still exist. The SQL queries and request tests after each attempt are the evidence; copying the function without running it is not completion."},{"heading":"A transaction alone does not authorize a change","body":"An attacker with a valid JWT from another Team might call a promotion route if the view does not check Service ownership. These functions are not access-control substitutes: the API boundary must establish the authenticated subject, load trusted Membership, evaluate action/Team authority and then invoke the command. DRF list endpoints need scoped querysets; object-permission hooks do not automatically filter list rows. Negative tests must prove both a 403-style denial and the absence of database changes."},{"heading":"What the row lock does and does not prove","body":"The Service row lock serializes cooperating promotion/deletion operations when each locks that same row. It does not stop a separate uncontrolled SQL client from deleting an Environment without using these functions. Direct admin writes, model.save calls, cascade paths and data repair scripts are still possible bypasses unless the system restricts write access or enforces rules more centrally. Isolation level, deadlock/lock ordering and whole-transaction retries still matter under concurrency. An ordinary Django unit test cannot claim race freedom without an actual multi-session integration test."},{"heading":"Design a DRF error adapter without leaking internals","body":"Catch the explicit ReadinessConflict at the API boundary and produce a stable domain error, e.g. HTTP 409 and code production_environment_required, rather than exposing raw SQL. A missing Service can map to 404 and unauthenticated/forbidden requests to the chosen 401/403 contract. Do not catch every Exception and turn programming bugs into 400. Decide whether the endpoint accepts an already-created Environment or supports an atomic command creating both; whichever contract you choose must make partial state impossible."}], ["Save and run the exact registry/services.py example inside the disposable Django PostgreSQL lab.","Capture rejected promotion, valid promotion and blocked last-production-deployment deletion with database before/after assertions.","Describe how the Service row lock coordinates the two commands and name an uncontrolled path that bypasses it.","Write a DRF error mapping for ReadinessConflict, missing Service and forbidden user without swallowing unknown exceptions.","Plan a multi-session race test between authorized transition and deployment deletion; do not claim it has run until actually executed."], ["Why does Environment.service_id FK not enforce this requirement?","What state remains after ReadinessConflict?","Why must both promotion and deletion lock the same Service row?","Why is a correct domain command insufficient without Team authorization?"], [{"title":"Django — Database Transactions","url":"https://docs.djangoproject.com/en/5.2/topics/db/transactions/","kind":"documentation","purpose":"Atomic boundaries and transaction behavior."},{"title":"Django — select_for_update","url":"https://docs.djangoproject.com/en/5.2/ref/models/querysets/#select-for-update","kind":"documentation","purpose":"PostgreSQL row-lock behavior and testing caveats."},{"title":"DRF — Permissions","url":"https://www.django-rest-framework.org/api-guide/permissions/","kind":"documentation","purpose":"Object permissions, list filtering and create-action limitations."}]),

  richLesson("Validation and Business Rules", "Validation means establishing that a proposed representation and state transition satisfy declared rules before persistent mutation. DRF serializer validation checks representation and field-level policy. The Steward production-readiness invariant is different: it depends on existing Service and Environment rows and belongs in an authorized transaction-backed application command. A green serializer does not make the command safe.", ["Separate type/field validation, cross-field validation and state-dependent business invariants.","Demonstrate DRF ValidationError for invalid fields and pairwise conflicts.","Explain why validation can race with another database writer.","Place readiness and ownership checks in the correct trusted layers."], [{"heading":"Three boundaries, three reasons to reject","body":"A JSON parser may reject malformed JSON before a serializer runs. A serializer can reject a missing name, an invalid URL or a client-provided lifecycle not in allowed choices. A state-dependent command can reject a production transition when no production Environment exists. A database constraint may reject duplicate names even if two requests passed serializer uniqueness checks before either committed. The same failed request can legitimately be caught at more than one layer; do not assume that repeating an integrity rule only in Python makes it safe under concurrency."},{"heading":"Build a serializer with explicit input checks","body":"The following example is a complete DRF Serializer independent of the database. It enforces nonempty name, a properly typed requested lifecycle and a restricted criticality. It also enforces a cross-field example policy: a retired Service cannot request a change to critical priority. Run the three examples with the real DRF framework and print the errors; do not infer success from simply reading class attributes.","code":{"language":"python","caption":"DRF validation — executable field and cross-field rejection","value":"from rest_framework import serializers\n\nclass ServiceInput(serializers.Serializer):\n    name = serializers.CharField(allow_blank=False, max_length=120)\n    lifecycle = serializers.ChoiceField(choices=[\"development\",\"uat\",\"production\",\"retired\"])\n    criticality = serializers.ChoiceField(choices=[\"low\",\"medium\",\"high\",\"critical\"])\n\n    def validate(self, attrs):\n        if attrs[\"lifecycle\"] == \"retired\" and attrs[\"criticality\"] == \"critical\":\n            raise serializers.ValidationError({\"criticality\": \"retired Service cannot be marked critical in this example policy\"})\n        return attrs\n\nvalid = ServiceInput(data={\"name\":\"Payments API\",\"lifecycle\":\"uat\",\"criticality\":\"high\"})\nassert valid.is_valid(), valid.errors\ninvalid = ServiceInput(data={\"name\":\"\",\"lifecycle\":\"production\",\"criticality\":\"high\"})\nassert not invalid.is_valid() and \"name\" in invalid.errors\nconflict = ServiceInput(data={\"name\":\"Legacy API\",\"lifecycle\":\"retired\",\"criticality\":\"critical\"})\nassert not conflict.is_valid() and \"criticality\" in conflict.errors\nprint(\"DRF validation: valid, field failure, cross-field failure\")"}},{"heading":"Validation must not trust client-supplied ownership","body":"A client can send owning_team=42 in JSON, but the accepted Team must come from authenticated, authorized membership or a server-approved administrative command. In an actual ModelSerializer, mark owning_team read-only or enforce assignment through the view/application command. An attacker must not be able to change Service ownership by altering only a request body. A serializer with correct field types is not authorization."},{"heading":"Production readiness needs current database state","body":"A Service marked lifecycle=production must have a production Environment. The new registry/services.py lesson locks the Service row and checks the related Environment before changing lifecycle. This cannot be proved by the serializer above because the example contains no database and no Service record. Write two separate tests: invalid input rejected before application operation, and correct-shaped input rejected when related deployment state fails the business invariant. A successful HTTP status alone does not demonstrate the invariant remains protected under concurrent deletion."},{"heading":"Prove the negative condition beyond the response","body":"For a denied cross-Team attempt and a production transition without deployment, inspect the database before and after: Service owner, lifecycle, environment count and related audit record must remain unchanged. A user can see a 403/409 while a broken implementation has already mutated the row—so test both response and side effect. Classify a unique-name conflict as 409 only if the API contract defines that outcome, rather than leaking raw SQL text."}], ["Run the published DRF Serializer exercise and capture all three outcomes.","Write a separate database-backed test for a production promotion without a production Environment using registry/services.py.","Write an object-authorization negative test that proves a forged owning_team input cannot move Service ownership.","Explain one race between serializer validation and database uniqueness enforcement."], ["Why cannot a pure serializer prove production readiness?","What distinguishes field choice errors from forbidden cross-Team writes?","Why should database state be rechecked after a denied operation?"], [{"title":"DRF — Serializers and Validation","url":"https://www.django-rest-framework.org/api-guide/serializers/","kind":"documentation","purpose":"Field, object and non-model validation."},{"title":"Django — Database transactions","url":"https://docs.djangoproject.com/en/5.2/topics/db/transactions/","kind":"documentation","purpose":"State-dependent changes and atomic boundaries."}]),
  richLesson("See How DRF Turns Exceptions into HTTP Responses", "An API failure is more than a status code. When code inside a DRF view raises a recognized exception, DRF chooses a response status, payload and headers. You will observe that mechanism in the existing Book catalogue before translating Steward domain exceptions.", ["Explain which raised exceptions DRF handles and when it returns a response.","Install a project-wide handler without deleting unrelated configuration.","Prove 400, 404, 405, 406 and 415 with actual HTTP requests and unchanged database state.","Distinguish a handled API error from an unexpected HTTP 500."], [
    { heading: "What is actually handling the failure?", body: "There are four distinct layers: HTTP bytes must be parsed, fields are validated, the view runs its application operation, and DRF may convert a raised exception into an HTTP response. DRF recognizes APIException, Django Http404 and Django PermissionDenied. A view can instead return a Response(status=400) directly; the exception handler does NOT run for that explicit Response. Do not confuse these cases, and do not return HTTP 200 merely because an exception was caught." },
    { heading: "Create a custom handler that keeps HTTP semantics", body: "Save catalogue/error_handlers.py with the complete code. It delegates to DRF's built-in exception_handler first, which preserves HTTP status and relevant headers such as Allow and WWW-Authenticate where applicable. It then wraps the returned details in a predictable error object. The code does not turn unknown exceptions into 400; returning None tells DRF to let Django produce HTTP 500. This is a teaching contract for the catalogue, not a universal standard.", code: { language: "python", caption: "catalogue/error_handlers.py — preserve DRF status and headers", value: "from rest_framework.views import exception_handler\n\ndef catalogue_exception_handler(exc, context):\n    # DRF handles APIException, Http404 and Django PermissionDenied.\n    response = exception_handler(exc, context)\n    if response is None:\n        return None  # Unexpected failures remain HTTP 500, not 400.\n\n    codes = {\n        400: \"invalid_input\",\n        404: \"not_found\",\n        405: \"method_not_allowed\",\n        406: \"not_acceptable\",\n        415: \"unsupported_media_type\",\n    }\n    details = response.data\n    response.data = {\n        \"error\": {\n            \"code\": codes.get(response.status_code, \"request_failed\"),\n            \"details\": details,\n        }\n    }\n    return response" } },
    { heading: "Give the endpoint known ways to fail", body: "Save the complete error_views.py. A valid POST returns a success payload without writing a Book. Blank title and invalid copies are rejected by serializer.is_valid(raise_exception=True). ErrorLookup uses get_object_or_404 inside APIView so DRF can turn a missing row into 404. Wrong method, unsupported input media type and unacceptable output media type are handled by APIView/DRF itself. No authentication code is introduced yet; this catalogue remains a local learning experiment.", code: { language: "python", caption: "catalogue/error_views.py — real parsing, validation and lookup", value: "from django.shortcuts import get_object_or_404\nfrom rest_framework import serializers\nfrom rest_framework.response import Response\nfrom rest_framework.views import APIView\nfrom .models import Book\n\nclass IntakeInput(serializers.Serializer):\n    title = serializers.CharField(allow_blank=False, max_length=120)\n    copies = serializers.IntegerField(min_value=1)\n\nclass ErrorIntake(APIView):\n    def post(self, request):\n        incoming = IntakeInput(data=request.data)\n        incoming.is_valid(raise_exception=True)\n        return Response({\"accepted\": True, \"title\": incoming.validated_data[\"title\"]})\n\nclass ErrorLookup(APIView):\n    def get(self, request, book_id):\n        book = get_object_or_404(Book, pk=book_id)\n        return Response({\"id\": book.pk, \"title\": book.title})" } },
    { heading: "Wire the route and handler in the already working app", body: "Append the URL fragment to catalogue/urls.py; keep the old Book routes. Then append the REST_FRAMEWORK setting to config/settings.py, preserving other settings. If your project already defines REST_FRAMEWORK, update only EXCEPTION_HANDLER instead of creating a second separate dictionary. The handler is loaded by Python import path after Django setup, not by a magic global variable.", code: { language: "python", caption: "catalogue/urls.py — append error demo routes", value: "# Append to catalogue/urls.py; keep all earlier urlpatterns.\nfrom .error_views import ErrorIntake, ErrorLookup\nurlpatterns += [\n    path(\"error-intake/\", ErrorIntake.as_view(), name=\"error-intake\"),\n    path(\"error-books/<int:book_id>/\", ErrorLookup.as_view(), name=\"error-book\"),\n]" } },
    { heading: "Configure DRF without erasing earlier settings", body: "The example is an append-only project setting that retains any already-defined REST_FRAMEWORK keys. Confirm the import path matches error_handlers.py, then run python manage.py check. This changes only the scratch catalogue configuration, not the application deployed elsewhere.", code: { language: "python", caption: "config/settings.py — use the catalogue exception handler", value: "# Append to config/settings.py; retain unrelated project settings.\n# Keep the earlier REST_FRAMEWORK keys if you added any.\nREST_FRAMEWORK = {\n    **globals().get(\"REST_FRAMEWORK\", {}),\n    \"EXCEPTION_HANDLER\": \"catalogue.error_handlers.catalogue_exception_handler\",\n}" } },
    { heading: "Investigate a genuine unexpected failure without publishing a broken route", body: "Create catalogue/error_test_urls.py exactly as shown. It is a separate URLConf used only by the final test, NOT appended to the public catalogue URL patterns. The client temporarily selects it with override_settings, disables DEBUG, and sets raise_request_exception=False so a deliberate RuntimeError becomes a real 500 response. The internal exception text must not appear in the response. Django's default 500 may be HTML rather than our JSON envelope: a DRF exception handler does not handle every server error.", code: { language: "python", caption: "catalogue/error_test_urls.py — isolated unexpected-500 test only", value: "# This is a separate test-only URLConf; DO NOT append it to catalogue/urls.py.\nfrom django.urls import path\nfrom rest_framework.views import APIView\n\nclass DeliberatelyBroken(APIView):\n    def get(self, request):\n        raise RuntimeError(\"PRIVATE_DIAGNOSTIC_EXAMPLE\")\n\nurlpatterns = [path(\"crash/\", DeliberatelyBroken.as_view())]" } },
    { heading: "Run a real positive and negative HTTP contract", body: "Save catalogue/error_contract_lab.py and execute it through python manage.py shell -c \"exec(open('catalogue/error_contract_lab.py').read())\". Requests go through Django's in-process HTTP test client: valid 200, serializer and parse 400, missing 404, wrong method 405, unacceptable 406 and unsupported input 415. It checks the structured public code for each and verifies that the Book count was unchanged. This is more evidence than a Python dictionary pretending to be an HTTP response.", code: { language: "python", caption: "catalogue/error_contract_lab.py — verify actual statuses and no writes", value: "# Save as catalogue/error_contract_lab.py.\n# Run: python manage.py shell -c \"exec(open('catalogue/error_contract_lab.py').read())\"\nimport json\nfrom django.test import Client, override_settings\nfrom catalogue.models import Book\n\nclient = Client()\nbefore = Book.objects.count()\n\nok = client.post(\n    \"/catalogue/error-intake/\",\n    data=json.dumps({\"title\": \"A Book\", \"copies\": 2}),\n    content_type=\"application/json\",\n)\nassert ok.status_code == 200 and ok.json()[\"accepted\"] is True\n\ninvalid = client.post(\n    \"/catalogue/error-intake/\",\n    data=json.dumps({\"title\": \"\", \"copies\": 0}),\n    content_type=\"application/json\",\n)\nassert invalid.status_code == 400\nassert invalid.json()[\"error\"][\"code\"] == \"invalid_input\"\nassert \"title\" in invalid.json()[\"error\"][\"details\"]\n\nmalformed = client.post(\n    \"/catalogue/error-intake/\",\n    data='{\"title\": ',\n    content_type=\"application/json\",\n)\nassert malformed.status_code == 400\nassert malformed.json()[\"error\"][\"code\"] == \"invalid_input\"\n\nmissing = client.get(\"/catalogue/error-books/999999999/\")\nassert missing.status_code == 404\nassert missing.json()[\"error\"][\"code\"] == \"not_found\"\n\nwrong_method = client.get(\"/catalogue/error-intake/\")\nassert wrong_method.status_code == 405\nassert wrong_method.json()[\"error\"][\"code\"] == \"method_not_allowed\"\nassert \"Allow\" in wrong_method.headers\n\nunsupported_input = client.post(\n    \"/catalogue/error-intake/\", data=\"plain text\",\n    content_type=\"text/plain\",\n)\nassert unsupported_input.status_code == 415\nassert unsupported_input.json()[\"error\"][\"code\"] == \"unsupported_media_type\"\n\nunacceptable = client.post(\n    \"/catalogue/error-intake/\",\n    data=json.dumps({\"title\": \"A Book\", \"copies\": 2}),\n    content_type=\"application/json\", HTTP_ACCEPT=\"application/xml\",\n)\nassert unacceptable.status_code == 406\nassert unacceptable.json()[\"error\"][\"code\"] == \"not_acceptable\"\nassert Book.objects.count() == before\nprint(\"DRF_HANDLED_ERRORS_OK 200 400 404 405 406 415 no writes\")\n\n# Separate test-only URLConf: unexpected exceptions must NOT be converted\n# into client errors or disclose their internal string when DEBUG=False.\nwith override_settings(\n    ROOT_URLCONF=\"catalogue.error_test_urls\", DEBUG=False\n):\n    internal = Client(raise_request_exception=False).get(\"/crash/\")\nassert internal.status_code == 500\nassert b\"PRIVATE_DIAGNOSTIC_EXAMPLE\" not in internal.content\nassert \"error\" not in internal.headers.get(\"Content-Type\", \"\")\nprint(\"DRF_UNEXPECTED_500_OK no internal string in response\")", output: "DRF_HANDLED_ERRORS_OK 200 400 404 405 406 415 no writes\nDRF_UNEXPECTED_500_OK no internal string in response" } },
    { heading: "What can go wrong?", body: "If all responses still use DRF's default detail shape, check REST_FRAMEWORK.EXCEPTION_HANDLER, restart the shell and verify the import path. If the 415 is not raised, check that the request really sends text/plain to a view that accesses request.data. If 404 is HTML rather than JSON, check whether the missing route itself was outside DRF; the demo looks up a missing Book INSIDE APIView deliberately. Never use a broad except Exception: return Response(...,status=400) in production, since it mislabels program defects." },
  ], ["Create the four files and settings/route fragments, run python manage.py check, then execute the exact test script.","Explain for every status whether parsing, serializer validation, view lookup or HTTP dispatch rejected the request.","Change the handler to return None for a validation exception in a disposable copy; predict what happens and restore the correct handler.","Demonstrate the difference between a view that raises a ValidationError and one that directly returns Response(status=400).","Record why the 500 test URL is isolated and why the response may be HTML rather than a standardized JSON envelope."], ["Why does calling exception_handler first preserve important HTTP semantics?","Why doesn't a custom DRF handler automatically change every directly returned Response?","Why must an unexpected RuntimeError not be turned into a client-side 400?","What proves a 400 request did not mutate a database row?"], [{"title":"DRF — Exceptions and custom handlers","url":"https://www.django-rest-framework.org/api-guide/exceptions/","kind":"documentation","purpose":"Framework handling, exception_handler returning None, custom APIException and response headers."},{"title":"DRF — APIView exception handling","url":"https://www.django-rest-framework.org/api-guide/views/","kind":"reference","purpose":"What APIView catches and how it dispatches unexpected errors."},{"title":"Django 5.2 — Test client","url":"https://docs.djangoproject.com/en/5.2/topics/testing/tools/","kind":"reference","purpose":"Real test HTTP requests and raise_request_exception=False for deliberate 500."}]),

  richLesson("API Error Handling", "The prior lesson showed the real Django/DRF exception pipeline with the Book catalogue. Now connect the existing Steward readiness command to HTTP without moving its business rule into a serializer or pretending that a working route is already authorized for deployment.", ["Translate a real ReadinessConflict into 409 without exposing internal exceptions.","Keep unexpected errors distinct from deliberate domain rejection.","Test rejected and accepted operations against PostgreSQL, including unchanged state after 409.","Recognize that authenticating and authorizing a caller is a separate prerequisite owned by the following module."], [
    { heading: "The business command owns the rule; HTTP only translates", body: "You already wrote registry/services.py with promote_to_production() and remove_environment() under transaction.atomic(). A request to promote a UAT Service without a production Environment must not change its lifecycle. That is a domain conflict, not a malformed JSON payload, database connection failure or permission check. The API adapter chooses HTTP 409 and a stable public code while the reusable service command still owns the rule." },
    { heading: "Define a small, explicit exception boundary", body: "Save registry/api_errors.py. A known ReadinessConflict becomes an APIException with HTTP 409 and a safe, non-secret message. The handler delegates to DRF for status and headers, formats the public error envelope, and returns None for unknown exceptions. It never builds its response from raw database error text. Unlike a standalone dict mapping, this code can be called by the real DRF exception mechanism.", code: { language: "python", caption: "registry/api_errors.py — real ReadinessConflict to HTTP 409", value: "from rest_framework.exceptions import APIException\nfrom rest_framework.views import exception_handler\nfrom .services import ReadinessConflict\n\nclass ReadinessHTTPConflict(APIException):\n    status_code = 409\n    default_detail = \"The Service cannot make this transition yet.\"\n    default_code = \"readiness_conflict\"\n\ndef registry_exception_handler(exc, context):\n    # Translate only this known domain exception into a public API error.\n    if isinstance(exc, ReadinessConflict):\n        exc = ReadinessHTTPConflict()\n\n    response = exception_handler(exc, context)\n    if response is None:\n        return None  # A programming bug must remain a server failure.\n\n    if response.status_code == 409:\n        code = \"readiness_conflict\"\n    elif response.status_code == 404:\n        code = \"not_found\"\n    elif response.status_code == 405:\n        code = \"method_not_allowed\"\n    else:\n        code = \"invalid_input\" if response.status_code == 400 else \"request_failed\"\n\n    response.data = {\n        \"error\": {\"code\": code, \"details\": response.data}\n    }\n    return response" } },
    { heading: "Call the existing transaction command from a thin view", body: "Save registry/readiness_api.py. POST calls the existing promotion command. The view catches only Service.DoesNotExist to produce 404; it deliberately does not catch ReadinessConflict because the registered handler translates that centrally. A success returns the saved Service ID and lifecycle. It does not do authorization—this is a local teaching view that must not be published as a production route.", code: { language: "python", caption: "registry/readiness_api.py — call the domain command", value: "from rest_framework.exceptions import NotFound\nfrom rest_framework.response import Response\nfrom rest_framework.views import APIView\nfrom .models import Service\nfrom .services import promote_to_production\n\nclass TrainingPromotionView(APIView):\n    def post(self, request, service_id):\n        try:\n            service = promote_to_production(service_id)\n        except Service.DoesNotExist:\n            raise NotFound(\"Service does not exist.\")\n        # ReadinessConflict is NOT handled here. The central exception\n        # adapter maps it to a consistent HTTP 409.\n        return Response({\"id\": service.pk, \"lifecycle\": service.lifecycle})" } },
    { heading: "Keep the demonstration endpoint out of the deployed URL tree", body: "Save registry/training_urls.py. The test switches to this URLConf only inside override_settings. Do not add it to config/urls.py, expose it over the network, or infer that the route is secure. The next Identity/Authentication/Authorization module teaches trusting Team membership and enforcing object-level authority; those prerequisites cannot be bypassed just to make a training POST work.", code: { language: "python", caption: "registry/training_urls.py — isolated training route", value: "# Save as registry/training_urls.py; test-only, not public config/urls.py.\nfrom django.urls import path\nfrom .readiness_api import TrainingPromotionView\nurlpatterns = [\n    path(\"training/promote/<int:service_id>/\",\n         TrainingPromotionView.as_view(), name=\"training-promote\"),\n]" } },
    { heading: "Run the actual negative then successful transition", body: "Save registry/error_contract_lab.py inside the isolated tsa_steward_django_lab, after earlier migrations and readiness commands. The script creates a fresh UAT training Service, then sends real Client HTTP requests to the temporary route. It asserts a 409 with no lifecycle or Environment change, adds one production Environment, retries successfully with 200 and verifies saved state, then observes 404 and 405. Only synthetic workshop records are created; never point the script at a live system.", code: { language: "python", caption: "registry/error_contract_lab.py — real HTTP 409 and unchanged state", value: "# Save as registry/error_contract_lab.py in tsa_steward_django_lab.\nfrom uuid import uuid4\nfrom django.test import Client, override_settings\nfrom registry.models import Team, Service, Environment\n\nteam, _ = Team.objects.get_or_create(name=\"Error Contract Workshop\")\nservice = Service.objects.create(\n    name=\"Practice \" + uuid4().hex,\n    owning_team=team,\n    endpoint=\"https://example.invalid/api\",\n    lifecycle=Service.Lifecycle.UAT,\n)\nurl = f\"/training/promote/{service.pk}/\"\nbefore_environments = Environment.objects.filter(service=service).count()\n\n# This URLConf exists ONLY inside this local test. Authentication, Team\n# membership, and permissions belong to the later Identity module.\nwith override_settings(\n    ROOT_URLCONF=\"registry.training_urls\",\n    REST_FRAMEWORK={\n        \"EXCEPTION_HANDLER\": \"registry.api_errors.registry_exception_handler\"\n    },\n):\n    client = Client()\n    rejected = client.post(url, data=\"{}\", content_type=\"application/json\")\n    assert rejected.status_code == 409\n    assert rejected.json()[\"error\"][\"code\"] == \"readiness_conflict\"\n    service.refresh_from_db()\n    assert service.lifecycle == Service.Lifecycle.UAT\n    assert Environment.objects.filter(service=service).count() == before_environments\n    print(\"READINESS_409_NO_MUTATION\")\n\n    Environment.objects.create(\n        service=service, name=\"Production\",\n        kind=Environment.Kind.PRODUCTION,\n    )\n    accepted = client.post(url, data=\"{}\", content_type=\"application/json\")\n    assert accepted.status_code == 200\n    service.refresh_from_db()\n    assert service.lifecycle == Service.Lifecycle.PRODUCTION\n    print(\"READINESS_PROMOTION_200\")\n\n    missing = client.post(\n        \"/training/promote/999999999/\", data=\"{}\",\n        content_type=\"application/json\",\n    )\n    assert missing.status_code == 404\n    assert missing.json()[\"error\"][\"code\"] == \"not_found\"\n    assert client.get(url).status_code == 405\n    print(\"READINESS_404_405\")\n\nprint(\"TRAINING_ONLY_NOT_AUTHORIZED_FOR_PUBLIC_DEPLOYMENT\")", output: "READINESS_409_NO_MUTATION\nREADINESS_PROMOTION_200\nREADINESS_404_405\nTRAINING_ONLY_NOT_AUTHORIZED_FOR_PUBLIC_DEPLOYMENT" } },
    { heading: "Do not misrepresent security or failure coverage", body: "An HTTP 409 is not a substitute for an authorization denial: a caller without Team permission should be denied before the command runs. The local test-only view has no membership enforcement and must never become public as-is. A fake positive/negative mapper would also not prove transactional rollback. Our test verifies actual saved rows after the rejected and accepted requests; multi-session concurrency and indirect database write bypasses remain separate engineering risks." },
    { heading: "Choose status intentionally and investigate failures", body: "400 is rejected request data, 401/403 are authentication/permission outcomes (their precise behavior depends on the configured authentication classes), 404 addresses missing or hidden resources, 409 represents a recoverable domain state conflict, and 500 signals unexpected application failure. A stack trace belongs in controlled operator diagnostics, not a client message. If a domain exception returns 500 instead of 409, verify that registry_exception_handler is installed for the test and that the exception class is the same one imported by registry/services.py. If a rejected request still changes lifecycle, the defect is in the transaction/command, not the error envelope." },
  ], ["Create the three registry files and run the exact local test through the migrated Steward Django shell.","Capture the Service lifecycle and Environment count before and after the failed POST and verify both are unchanged.","Explain why the custom handler must preserve 404/405 while mapping only ReadinessConflict to 409.","Demonstrate that the training route is not registered in the project's normal URLConf.","Before proposing this for deployment, write the required authentication and Team membership authorization test cases without pretending to have implemented them."], ["Why is a production-readiness failure a conflict rather than invalid JSON?","Where does the database mutation happen, and why must the handler not attempt it?","What remains unproven about concurrent writers and cross-Team permissions?","Why must the test-only URLConf not be copied into a public service?"], [{"title":"DRF — Exceptions and custom handlers","url":"https://www.django-rest-framework.org/api-guide/exceptions/","kind":"documentation","purpose":"Framework handling, exception_handler returning None, custom APIException and response headers."},{"title":"DRF — APIView exception handling","url":"https://www.django-rest-framework.org/api-guide/views/","kind":"reference","purpose":"What APIView catches and how it dispatches unexpected errors."},{"title":"Django 5.2 — Test client","url":"https://docs.djangoproject.com/en/5.2/topics/testing/tools/","kind":"reference","purpose":"Real test HTTP requests and raise_request_exception=False for deliberate 500."}]),
  richLesson("Filter, Search and Order a Real Book API", "The prior Book API already saves, reads and validates real database rows. Add a carefully bounded GET query contract now: one exact year filter, one case-insensitive title search, and four explicitly permitted ordering choices. Learn what the database actually does and why these features do not confer permission to read a row.", ["Separate an exact database filter, a case-insensitive substring search, and an ordering decision.","Build and test actual GET query parameters using DRF's query_params and real Book rows.","Reject unsupported field paths, invalid values and repeated parameters with HTTP 400.","Verify generated SQL performs filtering and sorting, and identify the later authorization boundary."], [
    { heading: "Three operations with different meanings", body: "Filtering asks whether one row satisfies a precise condition, e.g. published_year=2023. Search asks for text matches such as title__icontains='atlas' (case-insensitive substring, not the same as full-text word search). Ordering changes which matching row appears first, not which rows exist. Each returns a QuerySet, and you already measured QuerySet evaluation. Query parameters are untrusted request strings; never pass an arbitrary field name directly into filter(**params) or order_by(params['ordering'])." },
    { heading: "Decide which client questions you support", body: "In this independent Book API, allow only year, search and ordering. The supported sort values are title, -title, year and -year. The server always adds unique primary key pk as tie-breaker, so two books published in the same year have a deterministic order within that response. A year must be four ASCII digits in the stated range; an empty search is rejected and a 41-character substring is out of scope. Reject unknown parameters rather than silently implying you support them. This is a deliberately strict example contract, not Django's automatic default behavior." },
    { heading: "Write the actual QuerySet and DRF endpoint", body: "Save catalogue/query_books.py exactly as shown, in the same tsa-django-intro project with stored_serializers.py. QueryDict.getlist() checks repeated parameters rather than silently accepting one of them. Every invalid request raises DRF ValidationError, so the exception handler from the previous lesson returns an HTTP 400 with a stable invalid_input code. valid requests evaluate the QuerySet in StoredBookSerializer(rows, many=True). A list endpoint like this is unbounded for teaching clarity; add pagination before exposing substantial datasets.", code: { language: "python", caption: "catalogue/query_books.py — validate and execute real Book queries", value: "from rest_framework.exceptions import ValidationError\nfrom rest_framework.response import Response\nfrom rest_framework.views import APIView\nfrom .models import Book\nfrom .stored_serializers import StoredBookSerializer\n\nORDERINGS = {\n    \"title\": (\"title\", \"pk\"),\n    \"-title\": (\"-title\", \"pk\"),\n    \"year\": (\"published_year\", \"pk\"),\n    \"-year\": (\"-published_year\", \"pk\"),\n}\n\ndef filtered_book_queryset(params, ignored=()):\n    allowed = {\"year\", \"search\", \"ordering\"} | set(ignored)\n    unknown = set(params.keys()) - allowed\n    if unknown:\n        raise ValidationError({\"query\": \"Unsupported parameters: \" +\n                               \", \".join(sorted(unknown))})\n    for key in params.keys():\n        if len(params.getlist(key)) != 1:\n            raise ValidationError({key: \"Provide this parameter once.\"})\n\n    rows = Book.objects.all()\n    year = params.get(\"year\")\n    if year is not None:\n        if (not year.isascii() or not year.isdecimal()\n                or len(year) != 4 or not 1450 <= int(year) <= 2100):\n            raise ValidationError({\"year\": \"Use a four-digit year (1450–2100).\"})\n        rows = rows.filter(published_year=int(year))\n\n    search = params.get(\"search\")\n    if search is not None:\n        search = search.strip()\n        if not 1 <= len(search) <= 40:\n            raise ValidationError({\"search\": \"Use 1–40 non-space characters.\"})\n        rows = rows.filter(title__icontains=search)\n\n    ordering = params.get(\"ordering\", \"title\")\n    if ordering not in ORDERINGS:\n        raise ValidationError({\"ordering\": \"Use title, -title, year or -year.\"})\n    return rows.order_by(*ORDERINGS[ordering])\n\nclass QueryBooks(APIView):\n    def get(self, request):\n        rows = filtered_book_queryset(request.query_params)\n        return Response(StoredBookSerializer(rows, many=True).data)" } },
    { heading: "Append the URL without overwriting older routes", body: "Add this fragment after the existing urlpatterns in catalogue/urls.py. Your config/urls.py already includes the catalogue prefix. Ensure the handler receives a DRF Request, whose request.query_params is a QueryDict. Do not create a new Django project or install django-filter just for these three explicitly written lookups.", code: { language: "python", caption: "catalogue/urls.py — append the query-books endpoint", value: "# Append to catalogue/urls.py; keep existing URL patterns.\nfrom .query_books import QueryBooks\nurlpatterns += [\n    path(\"query-books/\", QueryBooks.as_view(), name=\"query-books\"),\n]" } },
    { heading: "Run actual HTTP queries and inspect the SQL", body: "Save the full source as catalogue/query_request_lab.py. Its idempotent fixture provides six Books with a predictable shared prefix, years and unique shelf codes. Real Client GETs prove sorted search results, a year/search intersection, a descending year sort with ID tie-break, five invalid parameter types plus duplicate year, and that none of these reads mutated the database. CaptureQueriesContext inspects the SELECT actually executed by the endpoint and checks WHERE plus ORDER BY, rather than making up a SQL query string.", code: { language: "python", caption: "catalogue/query_request_lab.py — search, sort, invalid requests and real SQL", value: "# Save as catalogue/query_request_lab.py.\nfrom django.db import connection\nfrom django.test import Client\nfrom django.test.utils import CaptureQueriesContext\nfrom catalogue.models import Book\n\nfixture = [\n    (\"Query Lab Atlas\", 2023, \"query-lab-atlas\"),\n    (\"Query Lab Alpine\", 2023, \"query-lab-alpine\"),\n    (\"Query Lab Birch\", 2023, \"query-lab-birch\"),\n    (\"Query Lab Cypress\", 2021, \"query-lab-cypress\"),\n    (\"Query Lab Delta\", 2021, \"query-lab-delta\"),\n    (\"Query Lab Echo\", 2020, \"query-lab-echo\"),\n]\nfor title, year, code in fixture:\n    Book.objects.get_or_create(\n        shelf_code=code,\n        defaults={\"title\": title, \"published_year\": year},\n    )\n\nclient = Client()\nbefore = Book.objects.count()\nbase = \"/catalogue/query-books/\"\n\nall_books = client.get(base, {\"search\": \"query lab\"})\nassert all_books.status_code == 200\nassert [b[\"title\"] for b in all_books.json()] == sorted(\n    title for title, _, _ in fixture\n)\nprint(\"QUERY_SEARCH_SIX_ORDERED\")\n\ncombined = client.get(base, {\"year\": \"2023\", \"search\": \"Query Lab\"})\nassert combined.status_code == 200\nassert len(combined.json()) == 3\nassert all(b[\"published_year\"] == 2023 for b in combined.json())\nprint(\"QUERY_FILTER_THREE\")\n\nreversed_year = client.get(\n    base, {\"search\": \"query lab\", \"ordering\": \"-year\"},\n)\nassert reversed_year.status_code == 200\nranked = [(b[\"published_year\"], b[\"id\"]) for b in reversed_year.json()]\nassert ranked == sorted(ranked, key=lambda row: (-row[0], row[1]))\nprint(\"QUERY_TIE_BREAK_ORDERED\")\n\ninvalid_cases = [\n    {\"ordering\": \"owning_team__name\"},\n    {\"year\": \"not-a-year\"},\n    {\"search\": \" \"},\n    {\"search\": \"x\" * 41},\n    {\"unknown\": \"1\"},\n]\nfor params in invalid_cases:\n    refused = client.get(base, params)\n    assert refused.status_code == 400, refused.content\n    assert refused.json()[\"error\"][\"code\"] == \"invalid_input\"\nduplicate = client.get(base + \"?year=2023&year=2020\")\nassert duplicate.status_code == 400\nassert Book.objects.count() == before\nprint(\"QUERY_SIX_BAD_PARAMS_400_NO_WRITES\")\n\nwith CaptureQueriesContext(connection) as measured:\n    executed = client.get(\n        base, {\"search\": \"Query Lab\", \"year\": \"2023\",\n               \"ordering\": \"-year\"},\n    )\nassert executed.status_code == 200\nbook_sql = [\n    q[\"sql\"] for q in measured\n    if \"catalogue_book\" in q[\"sql\"].lower()\n]\nassert any(\"WHERE\" in sql.upper() and \"ORDER BY\" in sql.upper()\n           for sql in book_sql), book_sql\nprint(\"QUERY_ACTUAL_SQL_WHERE_ORDER_BY\")\nprint(\"BOOK_QUERY_API_OK\")", output: "QUERY_SEARCH_SIX_ORDERED\nQUERY_FILTER_THREE\nQUERY_TIE_BREAK_ORDERED\nQUERY_SIX_BAD_PARAMS_400_NO_WRITES\nQUERY_ACTUAL_SQL_WHERE_ORDER_BY\nBOOK_QUERY_API_OK" } },
    { heading: "Use the existing Django shell to execute the script", body: "Run the commands from the directory containing manage.py. Python manage.py check finds bad imports and URL registration; it does not prove query semantics. Then run the source code against migrated Book rows. The script is safe to rerun as its own six fixture rows use get_or_create, but it does not delete or reset unrelated learner data.", code: { language: "bash", caption: "Terminal — run the real Book query contract", value: "python manage.py check\npython manage.py shell -c \"exec(open('catalogue/query_request_lab.py').read())\"" } },
    { heading: "Understand what remains unproven", body: "No authenticated Team scope exists in this beginner catalogue: this is not a secure multi-tenant endpoint. The later Identity module establishes trusted memberships and authorized base querysets; only then should extra filters/search/order be applied. The test ensures no additional Book writes, but it cannot certify cross-Team privacy or response latency on millions of rows. Case-insensitive leading-wildcard searches can require different indexing approaches after measuring a real production workload." },
  ], ["Create both files and append the published route, then reproduce each positive and negative response.","Add a seventh Book with the teaching prefix and year 2023; predict how the result sets and count change before executing.","Replace the year equality with a new allowed minimum-year parameter in a disposable copy, define its validation and run two negative requests.","Show the SQL that your GET endpoint actually executed and explain WHERE versus ORDER BY.","Explain why this query builder cannot replace an authorized base queryset in Steward."], ["Why does query_params.getlist() matter when a user repeats ?year?","Why is title__icontains not the same as published_year equality or full-text search?","What proves an unapproved owning_team__name sort value cannot be passed into the ORM?","Why does appending pk make tied publication years deterministic?","Why does an allowed query parameter not establish permission to view the resulting rows?"], [{"title":"DRF — Filtering","url":"https://www.django-rest-framework.org/api-guide/filtering/","kind":"documentation","purpose":"Explicit queryset filtering, search semantics, and allowlisting sort fields."},{"title":"Django — QuerySet API","url":"https://docs.djangoproject.com/en/5.2/ref/models/querysets/","kind":"reference","purpose":"Exact equality and icontains lookups, ordering and deterministic unique tie-breakers."}]),

  richLesson("Filtering, Searching and Ordering", "After the real Book query lab, apply the same mechanism to Service records—but do not pretend we have taught authentication or Team membership. This isolated Steward exercise uses a Team ID chosen by the SERVER's test configuration, never the URL, to demonstrate that filtering is allowed to narrow an established scope but never widen it. It is not a secure endpoint to deploy.", ["Distinguish server-selected visibility scope from client-supplied query options.","Implement explicit lifecycle, criticality, Team, search and ordering filters on real PostgreSQL Service rows.","Prove HTTP responses and SQL exclude the other Team, even when that Team's ID appears in the query.","Treat missing trusted scope and unsupported/repeated input as errors without leaking or altering rows."], [{"heading":"What the earlier Book API could not prove","body":"Books have no Team owner. The Book lesson correctly taught query syntax but could not demonstrate a multitenant boundary. A typical Service API begins with an authenticated principal, finds memberships, authorizes actions and *then* filters Service rows. Membership and authentication are not yet taught: do not manufacture users or silently trust an HTTP header. Here a server-selected, test-only Team ID stands in for the *result* of that later authorization step, not the security mechanism itself."},{"heading":"Build a server-owned base QuerySet FIRST","body":"Create registry/training_scope.py. The trusted_training_team() function reads a positive integer from Django settings supplied through override_settings in a local test. No request header, body or query string chooses it. Missing scope returns DRF PermissionDenied (403). Only after Service.objects.filter(owning_team_id=team_id) does the code apply untrusted filters. An owning_team query value intersects that base query; a different Team ID returns zero rows rather than selecting that Team. The route is test-only and must not be published.","code":{"language":"python","caption":"registry/training_scope.py — server-selected Team scope and allowlisted Service lookups","value":"from django.conf import settings\nfrom rest_framework.exceptions import PermissionDenied, ValidationError\nfrom .models import Service\n\nORDERS = {\n    \"name\": (\"name\", \"pk\"),\n    \"-name\": (\"-name\", \"pk\"),\n    \"criticality\": (\"criticality\", \"pk\"),\n    \"-criticality\": (\"-criticality\", \"pk\"),\n}\n\ndef trusted_training_team():\n    # A server-owned setting selected ONLY by a disposable lab. It is NOT\n    # authentication or membership verification. Replace in Identity school.\n    team_id = getattr(settings, \"TSA_TRAINING_TEAM_ID\", None)\n    if type(team_id) is not int or team_id <= 0:\n        raise PermissionDenied(\"The training Team scope is not configured.\")\n    return team_id\n\ndef scoped_services(params, ignored=()):\n    team_id = trusted_training_team()\n    allowed = {\"lifecycle\", \"criticality\", \"owning_team\", \"search\",\n               \"ordering\"} | set(ignored)\n    extra = set(params.keys()) - allowed\n    if extra:\n        raise ValidationError({\"query\": \"Unsupported: \" +\n                               \", \".join(sorted(extra))})\n    for key in params.keys():\n        if len(params.getlist(key)) != 1:\n            raise ValidationError({key: \"Supply this parameter once.\"})\n\n    # A client may narrow this queryset, NEVER replace its server-owned scope.\n    rows = Service.objects.filter(owning_team_id=team_id)\n    lifecycle = params.get(\"lifecycle\")\n    if lifecycle is not None:\n        if lifecycle not in Service.Lifecycle.values:\n            raise ValidationError({\"lifecycle\": \"Unsupported lifecycle.\"})\n        rows = rows.filter(lifecycle=lifecycle)\n\n    criticality = params.get(\"criticality\")\n    if criticality is not None:\n        if criticality not in {\"low\", \"medium\", \"high\", \"critical\"}:\n            raise ValidationError({\"criticality\": \"Unsupported criticality.\"})\n        rows = rows.filter(criticality=criticality)\n\n    requested_team = params.get(\"owning_team\")\n    if requested_team is not None:\n        if (not requested_team.isascii() or\n                not requested_team.isdecimal() or int(requested_team) < 1):\n            raise ValidationError({\"owning_team\": \"Use a positive Team ID.\"})\n        rows = rows.filter(owning_team_id=int(requested_team))\n\n    search = params.get(\"search\")\n    if search is not None:\n        search = search.strip()\n        if not 1 <= len(search) <= 40:\n            raise ValidationError({\"search\": \"Use 1–40 characters.\"})\n        rows = rows.filter(name__icontains=search)\n\n    ordering = params.get(\"ordering\", \"name\")\n    if ordering not in ORDERS:\n        raise ValidationError({\"ordering\": \"Unsupported sort.\"})\n    return rows.order_by(*ORDERS[ordering])"}},{"heading":"Keep a GET view thin and paginate separately","body":"Create registry/training_query_views.py. TrainingServiceList returns both an actual SQL-backed count and stored Service fields. The same class file introduces a small page-number endpoint for the next lesson, but do not use it until that lesson. No login has been implemented, so this view may only be routed from a temporary test URLConf; the next module teaches real authentication and object-level authorization. Rows are ordered by an explicit allowed field and a unique pk tie-breaker.","code":{"language":"python","caption":"registry/training_query_views.py — real Service list and bounded page view","value":"from rest_framework.exceptions import ValidationError\nfrom rest_framework.pagination import PageNumberPagination\nfrom rest_framework.response import Response\nfrom rest_framework.views import APIView\nfrom .training_scope import scoped_services\n\nFIELDS = (\"id\", \"name\", \"owning_team_id\", \"lifecycle\", \"criticality\")\n\nclass TrainingServiceList(APIView):\n    def get(self, request):\n        rows = scoped_services(request.query_params)\n        return Response({\n            \"count\": rows.count(),\n            \"results\": list(rows.values(*FIELDS)),\n        })\n\nclass TrainingPageNumbers(PageNumberPagination):\n    page_size = 2\n    page_size_query_param = \"page_size\"\n    max_page_size = 3\n\nclass TrainingServicePages(APIView):\n    def get(self, request):\n        # Reject malformed page input rather than silently treating it\n        # as a normal page size; reject duplicates in scoped_services.\n        for name in (\"page\", \"page_size\"):\n            value = request.query_params.get(name)\n            if value is not None and (\n                not value.isascii() or not value.isdecimal()\n                or int(value) < 1\n            ):\n                raise ValidationError({name: \"Use a positive integer.\"})\n        rows = scoped_services(\n            request.query_params, ignored=(\"page\", \"page_size\")\n        )\n        pager = TrainingPageNumbers()\n        page = pager.paginate_queryset(rows, request, view=self)\n        return pager.get_paginated_response([\n            {field: getattr(service, field) for field in FIELDS}\n            for service in page\n        ])"}},{"heading":"Use a separate, test-only URL configuration","body":"Save registry/training_scoped_urls.py. The test calls override_settings(ROOT_URLCONF='registry.training_scoped_urls'); it never adds these paths to config/urls.py or makes them available to real clients. Using ordinary project URLs here would create a severe security defect: the trusted Team ID fixture is not tied to a requesting person.","code":{"language":"python","caption":"registry/training_scoped_urls.py — unpublished teaching endpoints","value":"# Save as registry/training_scoped_urls.py. This URLConf is TEST ONLY.\n# Do not include it from the project's ordinary config/urls.py.\nfrom django.urls import path\nfrom .training_query_views import TrainingServiceList, TrainingServicePages\n\nurlpatterns = [\n    path(\"training/services/\", TrainingServiceList.as_view()),\n    path(\"training/service-pages/\", TrainingServicePages.as_view()),\n]"}},{"heading":"Seed two Teams without creating invalid production Services","body":"Save registry/seed_scoped_services.py and run it in the isolated Django-managed Steward project AFTER the model migration lab. The source creates five UAT Services for Team A and three for Team B. Every row has a real owning_team FK and a valid lifecycle. The seed uses get_or_create to avoid duplicate training records. Do not seed a production lifecycle without a production Environment.","code":{"language":"python","caption":"registry/seed_scoped_services.py — eight fictional UAT Services","value":"# Save as registry/seed_scoped_services.py.\nfrom registry.models import Service, Team\n\na, _ = Team.objects.get_or_create(name=\"Scoped Query Team A\")\nb, _ = Team.objects.get_or_create(name=\"Scoped Query Team B\")\nfor title, team, criticality in [\n    (\"Scope Lab Birch\", a, \"high\"),\n    (\"Scope Lab Cedar\", a, \"high\"),\n    (\"Scope Lab Delta\", a, \"medium\"),\n    (\"Scope Lab Elm\", a, \"medium\"),\n    (\"Scope Lab Fir\", a, \"low\"),\n    (\"Scope Lab Hidden Gold\", b, \"high\"),\n    (\"Scope Lab Hidden Silver\", b, \"medium\"),\n    (\"Scope Lab Hidden Bronze\", b, \"low\"),\n]:\n    Service.objects.get_or_create(\n        name=title,\n        defaults={\n            \"owning_team\": team,\n            \"endpoint\": \"https://workshop.example.invalid/service\",\n            \"lifecycle\": Service.Lifecycle.UAT,\n            \"criticality\": criticality,\n        },\n    )\nassert Service.objects.filter(owning_team=a, name__startswith=\"Scope Lab\").count() == 5\nassert Service.objects.filter(owning_team=b, name__startswith=\"Scope Lab\").count() == 3\nprint(\"SCOPED_FIXTURE_FIVE_AND_THREE\")","output":"SCOPED_FIXTURE_FIVE_AND_THREE"}},{"heading":"Prove visibility, filter intersection, SQL and refused requests","body":"Run registry/scoped_filter_lab.py after the seed. The local test selects Team A through SERVER configuration and makes genuine Django Client GET requests. The first response returns only five Team A Services; captured SQL must contain owning_team_id and ORDER BY. Lifecycle=uat and criticality=high narrows to two. Supplying Team B's real PK through ?owning_team returns zero, never Team B's rows. Six invalid parameter shapes plus repeated search return 400 with the previous error handler; no Services are written. Without any server-selected Team, the same route returns 403.","code":{"language":"python","caption":"registry/scoped_filter_lab.py — real SQL-backed boundary and negative queries","value":"# Save as registry/scoped_filter_lab.py.\nfrom django.db import connection\nfrom django.test import Client, override_settings\nfrom django.test.utils import CaptureQueriesContext\nfrom registry.models import Service, Team\n\na = Team.objects.get(name=\"Scoped Query Team A\")\nb = Team.objects.get(name=\"Scoped Query Team B\")\nbefore = Service.objects.count()\nwith override_settings(\n    ROOT_URLCONF=\"registry.training_scoped_urls\",\n    TSA_TRAINING_TEAM_ID=a.pk,\n    REST_FRAMEWORK={\n        \"EXCEPTION_HANDLER\": \"registry.api_errors.registry_exception_handler\"\n    },\n):\n    client = Client()\n    base = \"/training/services/\"\n    with CaptureQueriesContext(connection) as observed:\n        response = client.get(base, {\"search\": \"Scope Lab\"})\n    assert response.status_code == 200, response.content\n    data = response.json()\n    assert data[\"count\"] == 5\n    assert len(data[\"results\"]) == 5\n    assert all(row[\"owning_team_id\"] == a.pk for row in data[\"results\"])\n    assert [row[\"name\"] for row in data[\"results\"]] == sorted(\n        row[\"name\"] for row in data[\"results\"]\n    )\n    sql = [q[\"sql\"] for q in observed if \"service\" in q[\"sql\"].lower()]\n    assert any(\"owning_team_id\" in statement\n               and \"ORDER BY\" in statement.upper() for statement in sql), sql\n    print(\"SCOPE_FIVE_NO_OTHER_TEAM_SQL_CONFIRMED\")\n\n    filtered = client.get(base, {\n        \"search\": \"Scope Lab\", \"lifecycle\": \"uat\", \"criticality\": \"high\",\n    })\n    assert filtered.status_code == 200\n    assert [row[\"name\"] for row in filtered.json()[\"results\"]] == [\n        \"Scope Lab Birch\", \"Scope Lab Cedar\"\n    ]\n    print(\"SCOPE_CRITICALITY_LIFECYCLE_INTERSECTION_TWO\")\n\n    untrusted_owner = client.get(base, {\n        \"search\": \"Scope Lab\", \"owning_team\": str(b.pk),\n    })\n    assert untrusted_owner.status_code == 200\n    assert untrusted_owner.json() == {\"count\": 0, \"results\": []}\n    print(\"SCOPE_OTHER_TEAM_REQUEST_RETURNS_ZERO\")\n\n    for params in [\n        {\"ordering\": \"owning_team__name\"}, {\"lifecycle\": \"active\"},\n        {\"criticality\": \"urgent\"}, {\"search\": \" \"},\n        {\"owning_team\": \"invalid\"}, {\"team_id\": str(b.pk)},\n    ]:\n        refused = client.get(base, params)\n        assert refused.status_code == 400, refused.content\n        assert refused.json()[\"error\"][\"code\"] == \"invalid_input\"\n    repeated = client.get(base + \"?search=one&search=two\")\n    assert repeated.status_code == 400\n    assert Service.objects.count() == before\n    print(\"SCOPE_SEVEN_BAD_QUERIES_400_NO_WRITES\")\n\nwith override_settings(\n    ROOT_URLCONF=\"registry.training_scoped_urls\",\n    TSA_TRAINING_TEAM_ID=None,\n):\n    denied = Client().get(\"/training/services/\")\n    assert denied.status_code == 403\nprint(\"SCOPE_NOT_CONFIGURED_403\")\nprint(\"SCOPED_STEWARD_QUERY_OK\")","output":"SCOPE_FIVE_NO_OTHER_TEAM_SQL_CONFIRMED\nSCOPE_CRITICALITY_LIFECYCLE_INTERSECTION_TWO\nSCOPE_OTHER_TEAM_REQUEST_RETURNS_ZERO\nSCOPE_SEVEN_BAD_QUERIES_400_NO_WRITES\nSCOPE_NOT_CONFIGURED_403\nSCOPED_STEWARD_QUERY_OK"}},{"heading":"Execute with the correct migrated Django project","body":"From the isolated tsa_steward_django_lab project containing manage.py, retain the existing registry/models.py and registry/api_errors.py. Save these four files and run python manage.py check. Run the fixture first and the filter script second; they use the same Postgres database and are not standalone python3 filename.py scripts. These are local training commands, not an invitation to run against a bank database.","code":{"language":"python","caption":"Terminal — run the applied Service filtering evidence","value":"python manage.py check\npython manage.py shell -c \"exec(open('registry/seed_scoped_services.py').read())\"\npython manage.py shell -c \"exec(open('registry/scoped_filter_lab.py').read())\""}},{"heading":"A precise security claim—and an equally precise limitation","body":"The local test establishes: *given a trustworthy server-selected Team ID*, query parameters cannot widen the resulting list or its count. It does NOT establish that an HTTP client belongs to that Team, that direct detail endpoints enforce owner checks, or that Team membership updates revoke access correctly. The later Identity module must derive scope from verified credentials and authorized Membership rows. No test-only URL is deployable as written."}], ["Create each complete file, run the seed and capture all six printed evidence lines.","Predict the response to a forged ?owning_team=<Team B ID> before executing it, then explain why a client-visible 200 with an empty list is different from granting Team B access.","Add a permitted criticality level to the training fixture and show the filter/query change without altering the trusted scope.","Replace the Team A override with Team B inside the test, and record that a server-controlled change alters the visible data while a client-supplied filter never does.","Write the missing Identity-layer checks: authentication, membership lookup, per-Service object authority and membership-revocation behavior; do not claim they have been implemented."], ["Which line prevents query parameters from broadening the row set?","Why is TSA_TRAINING_TEAM_ID a test fixture rather than authentication?","What differs between an invalid owning_team string and a valid Team B ID under Team A scope?","What can a SQL trace demonstrate about scoping that a pure parser cannot?"], [{"title":"DRF filtering and queryset scoping","url":"https://www.django-rest-framework.org/api-guide/filtering/","kind":"documentation","purpose":"Filter an authoritative queryset before user-chosen filters."},{"title":"Django queryset API","url":"https://docs.djangoproject.com/en/5.2/ref/models/querysets/","kind":"reference","purpose":"SQL ordering, lookups and unique tie-breakers."}]),

  richLesson("Paginate Real Book Records Across Requests", "A working filtered GET still sends every matching row. Learn two real pagination mechanisms using the same Book API: numbered pages with a bounded size, and an opaque cursor over a unique stable shelf code. Then insert one new record between requests and observe the difference rather than trusting a diagram.", ["Return actual DRF page-number responses with count/next/previous/results and a maximum page size.","Show how deterministic ordering differs from a stable snapshot across two requests.","Reproduce a duplicate on offset-style pages after a new earlier record appears.","Use CursorPagination with a stable unique key and identify what it does and does not guarantee."], [
    { heading: "A page needs both a query and an ordering rule", body: "You already returned a sorted QuerySet in query_books.py. A page-number request gives the database a slice of that ordered result. DRF PageNumberPagination returns count, next, previous and results. Without a stable ordering, the same page number may return different rows even on unchanged data. Here the authorized base-query issue is deferred to the Identity module: this catalogue contains only tutorial Books and is not a production permission design." },
    { heading: "Keep response size bounded and reuse the validated query", body: "Save catalogue/page_books.py. The PageBooks view strips page/page_size only from the reusable query validation stage, validates those two parameters explicitly (rather than silently accepting invalid numbers), and then calls DRF's paginator on the still-unevaluated QuerySet. A default of two and a maximum of three are intentionally tiny for experiments, not recommended production values. The cursor endpoint uses a unique shelf_code whose values remain unchanged in this lab. Its filter limits the example to fictional page-lab rows; actual per-user permission scoping would be required before any real deployment.", code: { language: "python", caption: "catalogue/page_books.py — bounded page numbers and stable-key cursors", value: "from rest_framework.exceptions import ValidationError\nfrom rest_framework.pagination import PageNumberPagination, CursorPagination\nfrom rest_framework.views import APIView\nfrom .models import Book\nfrom .query_books import filtered_book_queryset\nfrom .stored_serializers import StoredBookSerializer\n\nclass BookPages(PageNumberPagination):\n    page_size = 2\n    page_size_query_param = \"page_size\"\n    max_page_size = 3\n\nclass PageBooks(APIView):\n    def get(self, request):\n        for name in (\"page\", \"page_size\"):\n            if name in request.query_params:\n                value = request.query_params.get(name)\n                if not value.isascii() or not value.isdecimal() or int(value) < 1:\n                    raise ValidationError({name: \"Use a positive integer.\"})\n        rows = filtered_book_queryset(\n            request.query_params, ignored=(\"page\", \"page_size\")\n        )\n        pager = BookPages()\n        chunk = pager.paginate_queryset(rows, request, view=self)\n        return pager.get_paginated_response(\n            StoredBookSerializer(chunk, many=True).data\n        )\n\nclass BookCursor(CursorPagination):\n    page_size = 2\n    ordering = \"shelf_code\"  # Unique and unchanged after creation in this lab.\n\nclass CursorBooks(APIView):\n    def get(self, request):\n        unknown = set(request.query_params.keys()) - {\"cursor\"}\n        if unknown or len(request.query_params.getlist(\"cursor\")) > 1:\n            raise ValidationError({\"cursor\": \"Only one cursor is supported.\"})\n        rows = Book.objects.filter(\n            shelf_code__startswith=\"page-lab-\"\n        ).order_by(\"shelf_code\")\n        pager = BookCursor()\n        chunk = pager.paginate_queryset(rows, request, view=self)\n        return pager.get_paginated_response(\n            StoredBookSerializer(chunk, many=True).data\n        )" } },
    { heading: "Append the two pagination endpoints", body: "Add these routes to catalogue/urls.py after query-books/. Keep the earlier serializers and saved-book endpoints intact. The request goes through the existing DRF error handler so unsupported query parameters return the same public 400 envelope as the previous lesson.", code: { language: "python", caption: "catalogue/urls.py — append page and cursor endpoints", value: "# Append to catalogue/urls.py, retaining query-books/ and earlier paths.\nfrom .page_books import PageBooks, CursorBooks\nurlpatterns += [\n    path(\"page-books/\", PageBooks.as_view(), name=\"page-books\"),\n    path(\"cursor-books/\", CursorBooks.as_view(), name=\"cursor-books\"),\n]" } },
    { heading: "Watch two requests disagree after one insertion", body: "Save catalogue/pagination_request_lab.py. It creates five known Books, requests page one (Birch,Cedar), then captures a cursor page with the same rows. Between requests it inserts Aardvark, which sorts earlier. The next numbered page now repeats Cedar and its reported count changes from five to six: deterministic sort did not freeze the database. Continuing from the saved cursor instead returns Delta,Elm, with no duplicate under this particular unique, immutable-key insertion scenario. Neither approach guarantees a snapshot across all future requests.", code: { language: "python", caption: "catalogue/pagination_request_lab.py — real offset duplicate and cursor continuation", value: "# Save as catalogue/pagination_request_lab.py.\nfrom urllib.parse import urlparse\nfrom django.test import Client\nfrom catalogue.models import Book\n\nfixture = [\n    (\"Page Lab Birch\", \"page-lab-birch\"),\n    (\"Page Lab Cedar\", \"page-lab-cedar\"),\n    (\"Page Lab Delta\", \"page-lab-delta\"),\n    (\"Page Lab Elm\", \"page-lab-elm\"),\n    (\"Page Lab Fir\", \"page-lab-fir\"),\n]\nfor title, code in fixture:\n    Book.objects.get_or_create(\n        shelf_code=code,\n        defaults={\"title\": title, \"published_year\": 2022},\n    )\nclient = Client()\nbase = \"/catalogue/page-books/\"\nfiltering = {\"search\": \"Page Lab\", \"page_size\": \"2\"}\n\nfirst = client.get(base, {**filtering, \"page\": \"1\"})\nassert first.status_code == 200\nassert first.json()[\"count\"] == 5\nseen_first = [row[\"title\"] for row in first.json()[\"results\"]]\nassert seen_first == [\"Page Lab Birch\", \"Page Lab Cedar\"]\nassert first.json()[\"next\"] is not None\nprint(\"PAGE_ONE_TWO_OF_FIVE\")\n\n# This cursor uses a unique stable shelf_code, not the mutable title.\ncursor_first = client.get(\"/catalogue/cursor-books/\")\nassert cursor_first.status_code == 200\ncursor_one_names = [row[\"title\"] for row in cursor_first.json()[\"results\"]]\nassert cursor_one_names == seen_first\ncursor_next = cursor_first.json()[\"next\"]\nassert cursor_next is not None\n\n# Separate HTTP requests can observe changed database content.\nnew_book, created = Book.objects.get_or_create(\n    shelf_code=\"page-lab-aardvark\",\n    defaults={\"title\": \"Page Lab Aardvark\", \"published_year\": 2022},\n)\nassert created\nsecond = Client().get(base, {**filtering, \"page\": \"2\"})\nassert second.status_code == 200 and second.json()[\"count\"] == 6\noffset_names = [row[\"title\"] for row in second.json()[\"results\"]]\nassert offset_names == [\"Page Lab Cedar\", \"Page Lab Delta\"]\nassert \"Page Lab Cedar\" in seen_first and \"Page Lab Cedar\" in offset_names\nprint(\"OFFSET_DUPLICATE_AFTER_INSERT\")\n\ncursor_path = urlparse(cursor_next)\ncursor_second = Client().get(cursor_path.path + \"?\" + cursor_path.query)\nassert cursor_second.status_code == 200\ncursor_two_names = [row[\"title\"] for row in cursor_second.json()[\"results\"]]\nassert cursor_two_names == [\"Page Lab Delta\", \"Page Lab Elm\"]\nassert not set(cursor_one_names) & set(cursor_two_names)\nassert \"count\" not in cursor_second.json()\nprint(\"CURSOR_CONTINUES_NO_DUPLICATE\")\n\ncapped = Client().get(base, {\"search\": \"Page Lab\", \"page_size\": \"100\"})\nassert capped.status_code == 200\nassert len(capped.json()[\"results\"]) == 3\nprint(\"PAGE_SIZE_CAPPED_THREE\")\n\nfor params in [\n    {\"page\": \"0\"}, {\"page_size\": \"oops\"},\n    {\"search\": \"Page Lab\", \"ordering\": \"owning_team__name\"},\n]:\n    rejected = client.get(base, params)\n    assert rejected.status_code == 400, rejected.content\n    assert rejected.json()[\"error\"][\"code\"] == \"invalid_input\"\nassert client.get(base + \"?page=1&page=2\").status_code == 400\nassert client.get(base, {\"page\": \"999\"}).status_code == 404\nassert Book.objects.filter(shelf_code__startswith=\"page-lab-\").count() == 6\nprint(\"PAGE_BAD_PARAMS_400_MISSING_PAGE_404\")\nprint(\"PAGINATION_REAL_API_OK\")", output: "PAGE_ONE_TWO_OF_FIVE\nOFFSET_DUPLICATE_AFTER_INSERT\nCURSOR_CONTINUES_NO_DUPLICATE\nPAGE_SIZE_CAPPED_THREE\nPAGE_BAD_PARAMS_400_MISSING_PAGE_404\nPAGINATION_REAL_API_OK" } },
    { heading: "Run the same lab with the same Django setup", body: "Run python manage.py check, then execute the script through the initialized Django shell. It is a one-time insert experiment: the Aardvark row intentionally changes the dataset. If you rerun it, the assertion that the insert is new will fail; do not conceal that by deleting unrelated rows. Reset only that known fictional Aardvark record in your disposable training database or rerun the experiment in a clean scratch database.", code: { language: "bash", caption: "Terminal — reproduce changing-page behavior", value: "python manage.py check\npython manage.py shell -c \"exec(open('catalogue/pagination_request_lab.py').read())\"" } },
    { heading: "Why not solve everything with cursors?", body: "DRF CursorPagination returns next/previous links and results, but not a stable total count. Its ordering should be unique or nearly unique and stable; a client should treat cursor tokens as opaque. Changes to a record's ordering key, deletions and altered permission scope can still affect which rows the client sees. Offset pages are useful for numbered navigation, while stable-key cursors can be better for forward traversal of changing feeds. Neither method can promise a frozen multi-request snapshot without a separate consistency design." },
    { heading: "Failure diagnosis and security boundary", body: "An out-of-range numbered page is 404 in this teaching contract; malformed page parameters are explicit 400. page_size=100 is capped to three, not allowed to return a hundred rows. If a cursor fails after an insertion, inspect whether its ordering key was modified or the endpoint's initial queryset changed. Do not slice rows in Python before calling the paginator and do not allow a client to construct arbitrary ordering field paths. In a multi-tenant system, apply Team visibility to the database QuerySet before filtering, counting and paginating." },
  ], ["Create the two endpoints, then run the exact source-derived HTTP experiment on the existing Book catalogue.","Explain why Cedar repeats on the second numbered page even though both requests are sorted.","Repeat the thought experiment for a deletion before page two: predict whether an unseen record can be skipped.","Inspect page_size=100 and show the bounded three-result response; test duplicate, invalid and missing page parameters.","Explain why the saved cursor continues after Cedar, why its response has no total count and why it is not a global snapshot."], ["Why does ORDER BY make each page deterministic without fixing changes between requests?","Which pagination response includes count, and why can that count change?","Why is a stable unique shelf_code useful for a cursor?","Can a cursor ensure repeatable-read semantics across unrelated HTTP requests?","Why must permission filtering precede pagination and total-count calculation?"], [{"title":"DRF — Pagination","url":"https://www.django-rest-framework.org/api-guide/pagination/","kind":"documentation","purpose":"PageNumberPagination, bounded page_size_query_param/max_page_size and CursorPagination stable ordering."},{"title":"Django — QuerySet ordering","url":"https://docs.djangoproject.com/en/5.2/ref/models/querysets/","kind":"reference","purpose":"Deterministic ordering, limiting and changing row sets."}]),

  richLesson("Pagination", "The earlier Book paginator demonstrated how separate requests can see a moving table. Now apply it to the correctly server-scoped Steward Service QuerySet. Pagination must operate AFTER trusted scoping and explicit sorting: a page can leak another Team's identifiers or counts even if a UI hides the corresponding rows.", ["Paginate a trusted server-scoped QuerySet with deterministic order and a bounded response size.","Measure that counts and pages exclude another Team's Services, not just omit those rows from the view.","Reproduce an offset duplicate after a real row insertion between separate HTTP requests.","Distinguish a test-selected Team scope from unimplemented identity authorization and document the cursor trade-off already demonstrated."], [{"heading":"The rule is about database operations, not hiding fields","body":"When a Team A client requests Services, a correct implementation must derive the trusted Team scope *before* building the queryset, issuing COUNT(*), applying ORDER BY and selecting a page. Filtering a completed results list afterward is too late: next/previous/count can reveal records from another Team. The prior filtering lesson's scoped_services() returns a narrowed, ordered QuerySet, so the paginator can operate on it without changing the security boundary."},{"heading":"Reuse the same source instead of building a new app","body":"The previous registry/training_query_views.py already defines TrainingServicePages and TrainingPageNumbers. Save that exact code from the filtering lesson if it is not yet in your project. Its GET passes the scoped QuerySet into DRF PageNumberPagination with page_size=2 and max_page_size=3; it explicitly rejects invalid page strings. It still uses the local server-owned Team scope. The Book primer already demonstrated real CursorPagination; this applied exercise concentrates on scope and counts rather than repeating cursor setup."},{"heading":"What does COUNT reveal?","body":"With five Team A and three Team B Services, a list under Team A should report count=5 when searching the fixture prefix, NOT 8. After a new earlier-sorting Team A record is inserted, the same query reports 6. Both results are correct at their individual request times. SQL executes a scoped count and a scoped ordered LIMIT/OFFSET; merely asserting the result rows' owners is insufficient. A filtered query parameter for Team B must never turn count into 3 from Team A's context."},{"heading":"Observe the same offset failure against real scoped Services","body":"Save registry/scoped_page_lab.py and run it once after the scoped filtering lab. First page: Birch/Cedar, count 5. Query page 2 before mutation: Delta/Elm. Insert an earlier-sorting Aardvark Service owned by Team A, then query page 2 again: Cedar/Delta, count 6. Cedar repeats even though each response is deterministically ordered. Captured SQL must include owning_team_id, ORDER BY and OFFSET. The script then requests an excessive page size to prove the cap and checks invalid and missing pages.","code":{"language":"python","caption":"registry/scoped_page_lab.py — scoped HTTP page shift, cap and non-leak","value":"# Save as registry/scoped_page_lab.py (one-time insertion experiment).\nfrom django.db import connection\nfrom django.test import Client, override_settings\nfrom django.test.utils import CaptureQueriesContext\nfrom registry.models import Service, Team\n\na = Team.objects.get(name=\"Scoped Query Team A\")\nb = Team.objects.get(name=\"Scoped Query Team B\")\nbase = \"/training/service-pages/\"\nwith override_settings(\n    ROOT_URLCONF=\"registry.training_scoped_urls\",\n    TSA_TRAINING_TEAM_ID=a.pk,\n    REST_FRAMEWORK={\n        \"EXCEPTION_HANDLER\": \"registry.api_errors.registry_exception_handler\"\n    },\n):\n    client = Client()\n    params = {\"search\": \"Scope Lab\", \"page\": \"1\"}\n    first = client.get(base, params)\n    assert first.status_code == 200, first.content\n    assert first.json()[\"count\"] == 5\n    first_names = [row[\"name\"] for row in first.json()[\"results\"]]\n    assert first_names == [\"Scope Lab Birch\", \"Scope Lab Cedar\"]\n    assert first.json()[\"next\"] is not None\n    print(\"SCOPED_FIRST_PAGE_FIVE\")\n\n    with CaptureQueriesContext(connection) as captured:\n        second_unchanged = Client().get(base, {\n            \"search\": \"Scope Lab\", \"page\": \"2\"\n        })\n    assert [row[\"name\"] for row in second_unchanged.json()[\"results\"]] == [\n        \"Scope Lab Delta\", \"Scope Lab Elm\"\n    ]\n    sql = [q[\"sql\"] for q in captured if \"service\" in q[\"sql\"].lower()]\n    assert any(\"owning_team_id\" in q and \"ORDER BY\" in q.upper()\n               and \"OFFSET\" in q.upper() for q in sql), sql\n\n    name = \"Scope Lab Aardvark\"\n    added, fresh = Service.objects.get_or_create(\n        name=name,\n        defaults={\n            \"owning_team\": a,\n            \"endpoint\": \"https://workshop.example.invalid/new\",\n            \"lifecycle\": Service.Lifecycle.UAT,\n        },\n    )\n    assert fresh, \"Run once on a clean fixture; Aardvark already exists.\"\n    shifted = Client().get(base, {\"search\": \"Scope Lab\", \"page\": \"2\"})\n    assert shifted.status_code == 200\n    assert shifted.json()[\"count\"] == 6\n    shifted_names = [row[\"name\"] for row in shifted.json()[\"results\"]]\n    assert shifted_names == [\"Scope Lab Cedar\", \"Scope Lab Delta\"]\n    assert \"Scope Lab Cedar\" in first_names and \"Scope Lab Cedar\" in shifted_names\n    assert all(row[\"owning_team_id\"] == a.pk for row in shifted.json()[\"results\"])\n    print(\"SCOPED_OFFSET_DUPLICATE_AFTER_INSERT\")\n\n    capped = Client().get(base, {\"search\": \"Scope Lab\", \"page_size\": \"100\"})\n    assert capped.status_code == 200 and len(capped.json()[\"results\"]) == 3\n    assert capped.json()[\"count\"] == 6\n    print(\"SCOPED_PAGE_SIZE_CAPPED_THREE\")\n\n    for bad in [{\"page\": \"0\"}, {\"page_size\": \"0\"},\n                {\"ordering\": \"owning_team__name\"}, {\"owning_team\": \"invalid\"}]:\n        refused = client.get(base, bad)\n        assert refused.status_code == 400, refused.content\n    assert client.get(base + \"?page=1&page=2\").status_code == 400\n    assert client.get(base, {\"page\": \"999\"}).status_code == 404\n    assert Service.objects.filter(name__startswith=\"Scope Lab\").count() == 9\n    print(\"SCOPED_BAD_PAGES_400_OUT_OF_RANGE_404\")\n\nwith override_settings(\n    ROOT_URLCONF=\"registry.training_scoped_urls\",\n    TSA_TRAINING_TEAM_ID=b.pk,\n):\n    b_page = Client().get(base, {\"search\": \"Scope Lab\"})\n    assert b_page.status_code == 200 and b_page.json()[\"count\"] == 3\n    assert all(row[\"owning_team_id\"] == b.pk for row in b_page.json()[\"results\"])\nprint(\"TRUSTED_SCOPE_CHANGES_WITH_SERVER_CONFIG_NOT_QUERY\")\nprint(\"SCOPED_STEWARD_PAGINATION_OK\")","output":"SCOPED_FIRST_PAGE_FIVE\nSCOPED_OFFSET_DUPLICATE_AFTER_INSERT\nSCOPED_PAGE_SIZE_CAPPED_THREE\nSCOPED_BAD_PAGES_400_OUT_OF_RANGE_404\nTRUSTED_SCOPE_CHANGES_WITH_SERVER_CONFIG_NOT_QUERY\nSCOPED_STEWARD_PAGINATION_OK"}},{"heading":"Run the migration-safe local experiment once","body":"Use the existing isolated registry and training_scoped_urls.py. First run python manage.py check; then execute the script using manage.py shell, not an imported uninitialized module. Its insertion is deliberately one-time: if Aardvark already exists, the test fails rather than silently concealing a changed baseline. Reset only these fictional fixture rows in a disposable lab if you need to repeat the complete timeline.","code":{"language":"python","caption":"Terminal — reproduce scoped numbered-page behavior","value":"python manage.py check\npython manage.py shell -c \"exec(open('registry/scoped_page_lab.py').read())\""}},{"heading":"When a cursor helps, and when it cannot","body":"The earlier Book exercise used real CursorPagination on a unique, stable shelf_code and observed no repeat for one earlier insertion. A Service name or lifecycle can change, and permission membership can be revoked; such keys or scopes are not immutable stream positions. Page-number navigation has a count and numbered jumps but can shift under insertions. Cursor traversal can avoid some offset shifts but neither offers a cross-request snapshot, nor can either substitute for the missing Identity authorization step."},{"heading":"Diagnose a surprising page count","body":"If count shows eight instead of five, inspect the SQL query used for COUNT before blaming the serializer. If an invalid page is accepted, verify the view rejects negative/blank/multiple page parameters and that the configured exception handler formats the 400. If a Team B filter shows three Services in Team A's test, something broadened the base queryset. Stop and fix the scope boundary; hiding the rows in serialization would be insufficient."}], ["Run the complete scoped pagination experiment, including the HTTP 400/404 failure cases.","Explain each observed count 5 → 6 and why Cedar repeats, identifying the actual inserted row.","Choose Team B in the server test settings and prove its three rows/count are visible while Team A's six are not.","Demonstrate a forged owner filter or arbitrary sort does not bypass server-selected scope.","Describe how Identity/Authorization must replace the server fixture and why cursor/offset responses have different consistency limits."], ["Why must scope precede COUNT and LIMIT/OFFSET?","What evidence shows Team B does not affect Team A's count?","Why is a deterministic ORDER BY insufficient to promise identical pages across changing HTTP requests?","Which part of this training route must change before it can accept real external requests?"], [{"title":"DRF pagination","url":"https://www.django-rest-framework.org/api-guide/pagination/","kind":"documentation","purpose":"PageNumberPagination, max_page_size, count and missing-page behavior."},{"title":"Django test client","url":"https://docs.djangoproject.com/en/5.2/topics/testing/tools/","kind":"reference","purpose":"Real in-process request testing and override_settings for isolated test configuration."}]),

  richLesson("Serve Two Versions of a Real Book API", "A deployed API is a promise to existing clients, not just a URL. Before discussing Steward compatibility policy, implement real /v1/ and /v2/ Book routes over the same persisted Django model. Keep v1 working, introduce one deliberately breaking response change only in v2, and make a synthetic regression of v1 fail a consumer check.", ["Explain when DRF populates request.version and why a URL prefix does not transform data automatically.","Implement complete per-view URLPathVersioning with explicit allowed versions and real HTTP GET responses.","Prove v1 clients still work after v2 is introduced, while the v2 representation would break an unmodified v1 client.","Reject v3, missing books and unsupported methods, and detect a deliberate v1 contract regression."], [{"heading":"A version labels a specific observed behavior","body":"A consumer may depend on JSON field names and meanings, HTTP statuses, ordering and errors. The current Book API returns fields such as published_year. Suppose a new client wants publication: {year: ...} instead. Replacing the top-level year in-place would break an older client even though the response remains valid JSON. Here we keep the v1 response unchanged and make v2 intentionally different. This is a teaching reason to explore versioning; most compatible additive changes do not need a new version."},{"heading":"Version negotiation is a DRF mechanism, not a path decoration","body":"By default, DRF request.version is None. URLPathVersioning reads a named version captured by the URL pattern, checks its allowed versions and makes the result available in the request during view execution. A per-view versioning_class suffices here, so you do not have to rewrite REST_FRAMEWORK settings for the whole project. Returning a different representation is still YOUR view's responsibility—DRF does not migrate a field automatically."},{"heading":"Implement the two real versions on the same Book row","body":"Save catalogue/versioned_book_api.py exactly as written. SupportedBookVersions accepts only v1 and v2, and the view uses request.version to choose between a stable v1 shape (published_year) and a breaking v2 shape (publication.year). The same Book primary key, title and shelf code are returned in both; the database is not copied or migrated. This is deliberate representation versioning, not two data stores.","code":{"language":"python","caption":"catalogue/versioned_book_api.py — complete version-aware DRF view","value":"from django.shortcuts import get_object_or_404\nfrom rest_framework.response import Response\nfrom rest_framework.versioning import URLPathVersioning\nfrom rest_framework.views import APIView\nfrom .models import Book\n\nclass SupportedBookVersions(URLPathVersioning):\n    allowed_versions = (\"v1\", \"v2\")\n    default_version = None\n\nclass VersionedBookDetail(APIView):\n    versioning_class = SupportedBookVersions\n\n    def get(self, request, version, book_id):\n        book = get_object_or_404(Book, pk=book_id)\n        common = {\n            \"id\": book.pk,\n            \"title\": book.title,\n            \"shelf_code\": book.shelf_code,\n            \"api_version\": request.version,\n        }\n        if request.version == \"v1\":\n            # The original consumer expects published_year at top level.\n            return Response({**common, \"published_year\": book.published_year})\n        # v2 deliberately changes the representation. Both read the same row.\n        return Response({\n            **common, \"publication\": {\"year\": book.published_year}\n        })"}},{"heading":"Capture the actual version in the URL pattern","body":"Append this URL fragment to catalogue/urls.py, retaining the earlier stored-book, query, page and cursor endpoints. The named group (?P<version>...) is what URLPathVersioning reads. The regular expression also matches v3 so DRF's allowed_versions rejection, rather than an unrelated missing route, can be observed as HTTP 404. The project already adds the /catalogue/ prefix.","code":{"language":"python","caption":"catalogue/urls.py — add v1/v2 Book routes without replacing old endpoints","value":"# Append to catalogue/urls.py, preserving ALL earlier urlpatterns.\nfrom django.urls import re_path\nfrom .versioned_book_api import VersionedBookDetail\n\nurlpatterns += [\n    re_path(\n        r\"^(?P<version>v[0-9]+)/books/(?P<book_id>[0-9]+)/$\",\n        VersionedBookDetail.as_view(),\n        name=\"versioned-book-detail\",\n    ),\n]"}},{"heading":"Create a deliberately broken v1, but keep it out of normal routes","body":"Save catalogue/version_bug_urls.py. It subclasses the versioned view but deletes the legacy published_year field only for v1. This is an intentional defect used in the last test; it must never be included from the main config/urls.py. The test temporarily selects it through override_settings, then restores the project's normal routes. This isolates a meaningful regression rather than weakening the working v1 contract.","code":{"language":"python","caption":"catalogue/version_bug_urls.py — isolated broken v1 for regression detection","value":"# Save as catalogue/version_bug_urls.py — ONLY for an isolated test.\n# Do NOT include this URLConf from config/urls.py.\nfrom django.urls import re_path\nfrom .versioned_book_api import VersionedBookDetail\n\nclass BrokenOldVersion(VersionedBookDetail):\n    def get(self, request, version, book_id):\n        response = super().get(request, version, book_id)\n        if request.version == \"v1\" and response.status_code == 200:\n            response.data.pop(\"published_year\", None)\n        return response\n\nurlpatterns = [\n    re_path(\n        r\"^catalogue/(?P<version>v[0-9]+)/books/(?P<book_id>[0-9]+)/$\",\n        BrokenOldVersion.as_view(),\n    ),\n]"}},{"heading":"Test real requests, not a hand-written dictionary","body":"Save catalogue/version_request_lab.py in tsa-django-intro. It uses an existing or newly inserted fictional Book, sends two fresh Django Client GET requests, proves the old client contract accepts v1 and rejects the v2 shape, and re-fetches v1 to verify it was not silently changed. It requests v3 and a missing book (404) and uses the wrong method (405). Finally it deliberately selects the broken test URLConf and proves the same v1 consumer check rejects it, without altering Book rows.","code":{"language":"python","caption":"catalogue/version_request_lab.py — real v1/v2 HTTP compatibility and mutant","value":"# Save as catalogue/version_request_lab.py.\nfrom django.test import Client, override_settings\nfrom catalogue.models import Book\n\nbook, _ = Book.objects.get_or_create(\n    shelf_code=\"versioned-book-example\",\n    defaults={\"title\": \"Versioned Book Story\", \"published_year\": 2003},\n)\nbefore = Book.objects.count()\nbase = f\"/catalogue/v1/books/{book.pk}/\"\nnew_route = f\"/catalogue/v2/books/{book.pk}/\"\n\ndef old_client_accepts(data):\n    return (\n        set(data) == {\"id\", \"title\", \"published_year\",\n                      \"shelf_code\", \"api_version\"}\n        and isinstance(data[\"published_year\"], int)\n        and data[\"api_version\"] == \"v1\"\n    )\n\nlegacy = Client().get(base)\nassert legacy.status_code == 200, legacy.content\nassert old_client_accepts(legacy.json())\nassert legacy.json()[\"published_year\"] == 2003\nprint(\"VERSIONED_V1_OLD_CLIENT_OK\")\n\nupdated = Client().get(new_route)\nassert updated.status_code == 200, updated.content\nassert updated.json()[\"api_version\"] == \"v2\"\nassert updated.json()[\"publication\"] == {\"year\": 2003}\nassert \"published_year\" not in updated.json()\nassert updated.json()[\"id\"] == legacy.json()[\"id\"]\nassert not old_client_accepts(updated.json())\nprint(\"VERSIONED_V2_BREAKING_SHAPE_IDENTIFIED\")\n\n# v2 does not delete or silently change the deployed v1 contract.\nagain = Client().get(base)\nassert again.status_code == 200 and old_client_accepts(again.json())\nassert again.json() == legacy.json()\nassert Book.objects.count() == before\nprint(\"VERSIONED_V1_STILL_COMPATIBLE_AFTER_V2\")\n\ninvalid_version = Client().get(f\"/catalogue/v3/books/{book.pk}/\")\nassert invalid_version.status_code == 404\nassert invalid_version.json()[\"error\"][\"code\"] == \"not_found\"\nassert Client().get(\"/catalogue/v1/books/99999999/\").status_code == 404\nmethod = Client().post(base, data=\"{}\", content_type=\"application/json\")\nassert method.status_code == 405 and \"Allow\" in method.headers\nprint(\"VERSIONED_BAD_VERSION_404_MISSING_404_METHOD_405\")\n\n# Deliberate route mutation: an accidental v1 field removal must cause\n# a consumer contract failure, not be accepted as a harmless refactor.\nwith override_settings(ROOT_URLCONF=\"catalogue.version_bug_urls\"):\n    broken = Client().get(base)\nassert broken.status_code == 200\nassert not old_client_accepts(broken.json())\nassert \"published_year\" not in broken.json()\nprint(\"VERSIONED_BROKEN_V1_CONTRACT_DETECTED\")\nassert Book.objects.count() == before\nprint(\"VERSIONED_HTTP_CONTRACT_OK\")","output":"VERSIONED_V1_OLD_CLIENT_OK\nVERSIONED_V2_BREAKING_SHAPE_IDENTIFIED\nVERSIONED_V1_STILL_COMPATIBLE_AFTER_V2\nVERSIONED_BAD_VERSION_404_MISSING_404_METHOD_405\nVERSIONED_BROKEN_V1_CONTRACT_DETECTED\nVERSIONED_HTTP_CONTRACT_OK"}},{"heading":"Run in the same migrated catalogue","body":"From the existing tsa-django-intro directory containing manage.py, save the four files and append the route. Run python manage.py check to catch Python/URL wiring errors. Then execute the source-published lab from manage.py shell. The fixture uses get_or_create, so repeating the test does not create a duplicate record. The exact v1 client fields are fixed in this lab so unannounced additions are also detected; real API consumers may be more permissive.","code":{"language":"python","caption":"Terminal — test a real versioned HTTP contract","value":"python manage.py check\npython manage.py shell -c \"exec(open('catalogue/version_request_lab.py').read())\""}},{"heading":"Why not introduce v2 for every release?","body":"A compatible additive response field often needs no new version if old clients ignore unknown keys; changing an existing field's meaning, removing a required field or tightening input requirements may be breaking. Consider a compatibility path before cloning routes. URI path versions are visible and easy to inspect; Accept-header/media-type versions keep a URL stable but add negotiation complexity. Versioning also creates maintenance, security patching, migration and sunset obligations. This lesson implements URI path versioning so those mechanics are observable—not because it is universally superior."},{"heading":"What the HTTP experiment does not establish","body":"These are open tutorial Book GET endpoints in a disposable database; they do not authorize clients or protect multiple Teams. A real public API needs authentication, object-level permissions, reliable client contract coverage and a published deprecation window. The test demonstrates only this v1/v2 contract and deliberately narrow failure cases. It cannot prove every old consumer in the wild is compatible."}], ["Create the complete source, URL and test-only mutant URLConf, then run the real Client-based test.","Change the hypothetical v2 response to include a compatible optional field instead of replacing published_year. Explain whether a new version would still be necessary.","Make one disposable v1 change that renames shelf_code, predict which old-client assertion fails and restore the original.","Explain why v3 is rejected by allowed_versions and why the deliberately broken v1 uses override_settings rather than public routing.","Describe a consumer-supported migration and deprecation strategy with measurable retirement criteria."], ["Without a versioning_class, what does DRF normally put in request.version?","Why does creating a /v2/ path not automatically produce different JSON?","Which exact change makes v2 incompatible with the old Book consumer?","Why must the old v1 route be retested after v2 exists?","Why is a unit test over a hand-written dictionary weaker than the real HTTP contract test?"], [{"title":"DRF — Versioning","url":"https://www.django-rest-framework.org/api-guide/versioning/","kind":"documentation","purpose":"URLPathVersioning, request.version, allowed_versions and per-view schemes."},{"title":"DRF — APIView","url":"https://www.django-rest-framework.org/api-guide/views/","kind":"reference","purpose":"Versioned method dispatch and errors."},{"title":"Django — Test Client","url":"https://docs.djangoproject.com/en/5.2/topics/testing/tools/","kind":"reference","purpose":"Real HTTP contract verification, isolation through override_settings and status checks."}]),
  richLesson("API Versioning", "You have now served two real Book API versions and observed old-client compatibility over HTTP. Apply that experience to Steward's public contract: identify which changes actually require concurrent versions, which can be staged compatibly, and how to maintain a reliable sunset policy. This is a design exercise, not a prerequisite to implementing the later Identity module.", ["Classify API changes by actual effects on existing clients, not by whether the code deployed.","Identify compatibility risks involving field shape, lifecycle meaning, errors, ordering and authorization.","Choose deliberately between compatible evolution, temporary dual support and an explicit new version.","Specify evidence needed for deprecation, migration and retirement."], [{"heading":"Start with what a deployed consumer has actually observed","body":"A Steward client may parse id, name, lifecycle='production'; filter by lifecycle=production; expect HTTP 409 when a production transition lacks a deployment; and rely on stable ordering and a documented error code. Replacing lifecycle='production' with 'active' would break its enum contract: 'active' is not even one of Steward's lifecycle values. The previous Book v1 test demonstrated the same kind of break with a field rename, over real HTTP. Do not call every SQL or software release an API version."},{"heading":"Separate safe additions from incompatible replacement","body":"Consider four changes. Adding a new optional response property may work for tolerant clients; removing or renaming a property breaks strict consumers. Adding an optional request parameter with an unchanged default may be compatible, but making a previously optional parameter required is not. Changing 404 to 403 may have security motivations yet break client behavior; deciding that needs an explicit security and consumer assessment. An index or internal query optimization with identical externally observable behavior is not a version change."},{"heading":"Versioned URLs do not inherit authority","body":"Versioning is not authentication or authorization. Both v1 and v2 must enforce the same applicable access-control rules, rate limits, logging and data protection. A cloned v1 view does not become secure merely because v2 added permissions. The current Steward query labs used a server-selected fixture only; the subsequent Identity module will teach real memberships and object-level rules. Until then, do not publish either training route or treat its Team setting as a security token."},{"heading":"Choose a path deliberately","body":"For a small example, URLPathVersioning makes /v1/ and /v2/ easy to debug, route and test. NamespaceVersioning can organize larger URL trees; Accept-header and media-type negotiation keep the URL stable at the cost of more complex discovery, client configuration and caches. Pick the least disruptive scheme for clients you already have. Using an API gateway or OpenAPI document does not remove the need for compatibility tests across actual requests."},{"heading":"Write a real decision record for a breaking Steward change","body":"Use this rubric for ten changes: document old request and response with sample data; state new observable behavior; identify which old clients break and how you would know; see if a compatibility shim or deprecation warning can keep them working; decide whether a new version is necessary; specify a parallel-test period, usage telemetry, change notice, migration guide, sunset approval and eventual removal test. A complete plan is not an ungrounded promise to support both forever."},{"heading":"Prove the old contract before disabling it","body":"The Book exercise asserted v1 still works after v2 appeared. For Steward, write equivalent request tests for success and failures (including 400/403/404/409) and for filter/page semantics. A valid OpenAPI file and a passing deploy pipeline do not prove old-client behavior. If no old clients are known, discover consumers before declaring a removal safe. Keep old APIs patched while they remain exposed."}], ["Take ten potential Steward changes (e.g. lifecycle name, owner mutability, filter default, 409 code, sort order, pagination size, new optional field, new required field, route path, internal index) and classify each by real client impact.","For three breaking candidates, design one compatible or staged alternative and specify what the old client would observe.","Choose between URI and header/media-type versioning for an actual client constraint, and document your reason.","Write a deprecation and retirement plan for one unavoidable breaking change, including consumer tests and usage telemetry.","Explain which real HTTP regression the Book versioning lab caught and how you would transfer that assertion to a Steward contract after Identity is taught."], ["Can an optional response field break a strict client? Which assumption matters?","Why does changing a status code count as a compatibility decision?","What does a new API version fail to solve about security permissions?","What evidence would justify turning off a still-exposed v1 route?"], [{"title":"DRF — Versioning","url":"https://www.django-rest-framework.org/api-guide/versioning/","kind":"documentation","purpose":"URLPathVersioning, request.version, allowed_versions and per-view schemes."},{"title":"DRF — APIView","url":"https://www.django-rest-framework.org/api-guide/views/","kind":"reference","purpose":"Versioned method dispatch and errors."},{"title":"Django — Test Client","url":"https://docs.djangoproject.com/en/5.2/topics/testing/tools/","kind":"reference","purpose":"Real HTTP contract verification, isolation through override_settings and status checks."}]),
  richLesson("Generate and Verify OpenAPI from a Real Book API", "The previous Book endpoints already parse, validate and persist HTTP requests. Now make their contract machine-readable, viewable in a local Swagger UI, and testable against the actual running code. The source of truth cannot be a sample JSON dictionary that says something without consulting Django.", ["Explain OpenAPI versus Swagger UI and why neither proves runtime behavior alone.","Install a documented OpenAPI generator and annotate real APIView method operations rather than inventing a schema file.","Export and validate an OpenAPI 3 schema with GET, POST, 200/201/400/404, requestBody and serializer fields.","Use actual Django HTTP requests to detect both incorrect documented routes and mismatched response fields."], [{"heading":"A schema describes an API; it does not execute the API","body":"OpenAPI contains paths, operations, parameters, request bodies, responses and component schemas. Swagger UI is a browser renderer for the document, not a different API standard. A schema can be valid yet claim a nonexistent route or field; the consumer still fails. We will test the exported document and real Django response together. A test that only calls json.loads is insufficient."},{"heading":"Choose a maintained generator and understand its extra dependency","body":"The built-in DRF OpenAPI generator is deprecated; DRF recommends drf-spectacular. Install it into the SAME Python environment as Django using python -m pip (not an unrelated global interpreter). Add drf_spectacular to INSTALLED_APPS and set DEFAULT_SCHEMA_CLASS, retaining the earlier EXCEPTION_HANDLER. The next code example is an append-only settings fragment. Schema generation happens locally and requires no Docker. Unlike Swagger UI, the JSON document can be validated and version-controlled independently.","code":{"caption":"config/settings.py — enable drf-spectacular without erasing the error handler","value":"# Append to config/settings.py; preserve the earlier settings.\nINSTALLED_APPS += [\"drf_spectacular\"]\nREST_FRAMEWORK = {\n    **globals().get(\"REST_FRAMEWORK\", {}),\n    \"DEFAULT_SCHEMA_CLASS\": \"drf_spectacular.openapi.AutoSchema\",\n}\nSPECTACULAR_SETTINGS = {\n    \"TITLE\": \"Book Contract Workshop\",\n    \"DESCRIPTION\": \"Local, unauthenticated training Book API; not Steward.\",\n    \"VERSION\": \"1.0.0\",\n}","language":"python"}},{"heading":"Describe request, successful output and meaningful errors","body":"Save catalogue/contract_api.py. These are two small database-backed APIViews that reuse your existing StoredBookSerializer rather than redefining Book fields. The POST actually validates and saves a Book; GET returns stored rows. The @extend_schema decorator is attached to each actual APIView method, not blindly to a class. An ErrorEnvelopeSerializer describes the same error/code/details shape used by the installed handler. We annotate 201/400 and 200/404 explicitly. A 405 from POST on the detail route is a method routing failure; we must not fabricate a POST operation in OpenAPI. Authentication is explicitly disabled for this disposable teaching view—never publish it as multi-tenant Steward.","code":{"caption":"catalogue/contract_api.py — annotated real DRF GET and POST","value":"from django.shortcuts import get_object_or_404\nfrom drf_spectacular.utils import extend_schema\nfrom rest_framework import serializers, status\nfrom rest_framework.permissions import AllowAny\nfrom rest_framework.response import Response\nfrom rest_framework.views import APIView\n\nfrom .models import Book\nfrom .stored_serializers import StoredBookSerializer\n\nclass ErrorDetailSerializer(serializers.Serializer):\n    code = serializers.CharField()\n    details = serializers.JSONField()\n\nclass ErrorEnvelopeSerializer(serializers.Serializer):\n    error = ErrorDetailSerializer()\n\nclass ContractBookCollection(APIView):\n    # A LOCAL training endpoint, not an authorized multi-tenant service.\n    authentication_classes = []\n    permission_classes = [AllowAny]\n\n    @extend_schema(\n        request=None,\n        responses={200: StoredBookSerializer(many=True)},\n        description=\"List stored Books. The local tutorial has no user scoping.\",\n    )\n    def get(self, request):\n        books = Book.objects.order_by(\"pk\")\n        return Response(StoredBookSerializer(books, many=True).data)\n\n    @extend_schema(\n        request=StoredBookSerializer,\n        responses={201: StoredBookSerializer, 400: ErrorEnvelopeSerializer},\n        description=\"Validate and persist a Book; errors use the catalogue envelope.\",\n    )\n    def post(self, request):\n        serializer = StoredBookSerializer(data=request.data)\n        serializer.is_valid(raise_exception=True)\n        created = serializer.save()\n        return Response(\n            StoredBookSerializer(created).data,\n            status=status.HTTP_201_CREATED,\n        )\n\nclass ContractBookDetail(APIView):\n    authentication_classes = []\n    permission_classes = [AllowAny]\n\n    @extend_schema(\n        request=None,\n        responses={200: StoredBookSerializer, 404: ErrorEnvelopeSerializer},\n        description=\"Return a stored Book by its integer primary key.\",\n    )\n    def get(self, request, book_id):\n        book = get_object_or_404(Book, pk=book_id)\n        return Response(StoredBookSerializer(book).data)","language":"python"}},{"heading":"Define the paths only once for runtime and schema generation","body":"Save catalogue/contract_urls.py with both operations, and catalogue/openapi_urls.py as a limited schema-export entrypoint. The normal app and the generator both INCLUDE the same contract_urls module, so they cannot drift by independently retyping a path. The extra URLConf restricts this first schema exercise to two completed, annotated routes; attempting to document every earlier tutorial endpoint would require unrelated schema annotations and create noise. Both operations still use the project-level /catalogue/ prefix.","code":{"caption":"catalogue/contract_urls.py — one shared routing source","value":"# Save as catalogue/contract_urls.py.\n# These exact URL patterns are reused by the normal app and schema export.\nfrom django.urls import path\nfrom .contract_api import ContractBookCollection, ContractBookDetail\n\nurlpatterns = [\n    path(\"\", ContractBookCollection.as_view(), name=\"contract-book-list\"),\n    path(\"<int:book_id>/\", ContractBookDetail.as_view(), name=\"contract-book-detail\"),\n]","language":"python"}},{"heading":"Create the narrow schema-export URLConf","body":"This file does not replace your working config/urls.py. It merely selects the already-defined training operations for a focused generated schema. Your actual project will still have all the prior API endpoints. When a full application is documented later, the generator should cover its whole public URLConf and CI should reject incomplete or undocumented endpoints.","code":{"caption":"catalogue/openapi_urls.py — generate the two declared training endpoints","value":"# Save as catalogue/openapi_urls.py.\n# Narrow schema export to just the two teaching operations.\n# This includes the SAME contract_urls module as the real application.\nfrom django.urls import include, path\n\nurlpatterns = [\n    path(\"catalogue/contract-books/\", include(\"catalogue.contract_urls\")),\n]","language":"python"}},{"heading":"Expose JSON schema and Swagger UI alongside the working API","body":"Append these routes to catalogue/urls.py. SpectacularAPIView serves the same narrow schema over HTTP; SpectacularSwaggerView renders it for interactive inspection. The route names are important: the Swagger view resolves training-openapi-schema to find its document. The lesson only tests the server-rendered HTML response; Swagger's external browser assets may require network access unless configured for offline hosting.","code":{"caption":"catalogue/urls.py — append live contract, schema and Swagger UI","value":"# Append to catalogue/urls.py; keep all previous routes.\nfrom django.urls import include\nfrom drf_spectacular.views import SpectacularAPIView, SpectacularSwaggerView\n\nurlpatterns += [\n    path(\"contract-books/\", include(\"catalogue.contract_urls\")),\n    path(\n        \"training-schema/\",\n        SpectacularAPIView.as_view(urlconf=\"catalogue.openapi_urls\"),\n        name=\"training-openapi-schema\",\n    ),\n    path(\n        \"training-docs/\",\n        SpectacularSwaggerView.as_view(url_name=\"training-openapi-schema\"),\n        name=\"training-swagger-ui\",\n    ),\n]","language":"python"}},{"heading":"Run explicit setup, schema validation and a live contract test","body":"Save catalogue/openapi_contract_lab.py exactly as shown and run the terminal sequence. The management command exports JSON using drf-spectacular and fails on generation warnings or invalid OpenAPI structure. The HTTP script then verifies its paths and operations, 201/400/404 statuses, serializer field definitions, and actual saved Book state across requests. It also asks the local schema and Swagger UI routes for 200. A separate test cannot assume a syntax check proves the response matches the declared serializer.","code":{"caption":"Terminal — install, export, validate, test and open schema UI","value":"# From tsa-django-intro, with the previous Book migrations applied:\npython -m pip install 'drf-spectacular>=0.28,<1'\n# Append config/settings.py and catalogue/urls.py fragments shown above.\npython manage.py check\npython manage.py spectacular --urlconf catalogue.openapi_urls --format openapi-json --file catalogue/openapi.json --validate --fail-on-warn\npython manage.py shell -c \"exec(open('catalogue/openapi_contract_lab.py').read())\"\n# Optional: python manage.py runserver\n# Visit /catalogue/training-schema/ and /catalogue/training-docs/ locally.","language":"bash"}},{"heading":"Inspect the actual exported document and runtime response together","body":"This lab asserts that a POST really creates one Book and that a GET retrieves the same row; invalid or duplicate input returns the existing 400 error envelope, a missing Book returns 404, and a disallowed detail POST returns 405. The test inspects schema components for id, title, published_year, edition_note, shelf_code and matches them to returned keys. Finally it creates TWO valid-looking but false schema copies: one silently drops published_year, the other documents a nonexistent path. Both fail contract checks. This is a stronger lesson than hand-writing a schema and calling json.loads.","code":{"caption":"catalogue/openapi_contract_lab.py — validated schema plus real HTTP conformance","value":"# Save as catalogue/openapi_contract_lab.py.\n# Run AFTER generating catalogue/openapi.json with manage.py spectacular.\nimport json\nfrom copy import deepcopy\nfrom pathlib import Path\n\nfrom django.test import Client\nfrom catalogue.models import Book\n\ndocument = json.loads(Path(\"catalogue/openapi.json\").read_text())\nassert document[\"openapi\"].startswith(\"3.0.\")\ncollection = \"/catalogue/contract-books/\"\ndetail = \"/catalogue/contract-books/{book_id}/\"\nassert set(document[\"paths\"]) == {collection, detail}\nassert {\"get\", \"post\"} <= set(document[\"paths\"][collection])\nassert set(document[\"paths\"][detail]) == {\"get\"}\nassert {\"201\", \"400\"} <= set(document[\"paths\"][collection][\"post\"][\"responses\"])\nassert {\"200\", \"404\"} <= set(document[\"paths\"][detail][\"get\"][\"responses\"])\nassert \"requestBody\" in document[\"paths\"][collection][\"post\"]\n\n# The generated serializer component must describe the actual Book payload.\ncomponents = document[\"components\"][\"schemas\"]\nassert \"StoredBook\" in components, components.keys()\nproperties = components[\"StoredBook\"][\"properties\"]\nexpected = {\"id\", \"title\", \"published_year\", \"edition_note\", \"shelf_code\"}\nassert set(properties) == expected, properties\nassert properties[\"id\"].get(\"readOnly\") is True\nprint(\"OPENAPI_GENERATED_PATHS_METHODS_AND_FIELDS_OK\")\n\nclient = Client()\nschema_http = client.get(\"/catalogue/training-schema/\")\nassert schema_http.status_code == 200\nassert schema_http.data[\"paths\"] == document[\"paths\"]\ndocs_http = client.get(\"/catalogue/training-docs/\")\nassert docs_http.status_code == 200\nprint(\"OPENAPI_SCHEMA_AND_SWAGGER_UI_HTTP_200\")\n\nbefore = Book.objects.count()\npayload = {\n    \"title\": \"Contract Workshop Story\",\n    \"published_year\": 2019,\n    \"shelf_code\": \"contract-workshop-story\",\n}\ncreated = client.post(\n    collection, data=json.dumps(payload), content_type=\"application/json\",\n)\nassert created.status_code == 201, created.content\ncreated_data = created.json()\nassert set(created_data) == set(properties)\nassert created_data[\"id\"] == Book.objects.get(\n    shelf_code=\"contract-workshop-story\"\n).pk\nassert Book.objects.count() == before + 1\nread_back = Client().get(\n    f\"/catalogue/contract-books/{created_data['id']}/\"\n)\nassert read_back.status_code == 200\nassert read_back.json() == created_data\nlisted = client.get(collection)\nassert listed.status_code == 200\nassert created_data in listed.json()\nprint(\"OPENAPI_REAL_POST_201_GET_200_AND_PERSISTENCE\")\n\ninvalid = client.post(\n    collection,\n    data=json.dumps({\"published_year\": 2020, \"shelf_code\": \"missing-title\"}),\n    content_type=\"application/json\",\n)\nassert invalid.status_code == 400\nassert invalid.json()[\"error\"][\"code\"] == \"invalid_input\"\nduplicate = client.post(\n    collection, data=json.dumps(payload), content_type=\"application/json\",\n)\nassert duplicate.status_code == 400\nassert \"shelf_code\" in duplicate.json()[\"error\"][\"details\"]\nmissing = client.get(\"/catalogue/contract-books/999999999/\")\nassert missing.status_code == 404\nassert missing.json()[\"error\"][\"code\"] == \"not_found\"\nunsupported = client.post(\n    f\"/catalogue/contract-books/{created_data['id']}/\",\n    data=\"{}\", content_type=\"application/json\",\n)\nassert unsupported.status_code == 405\nassert \"Allow\" in unsupported.headers\nassert Book.objects.count() == before + 1\nprint(\"OPENAPI_REAL_400_404_405_NO_EXTRA_WRITES\")\n\n# A syntactically valid schema can still lie. Two independent mutations:\n# (1) remove a response field; (2) document a nonexistent URL.\ndef declared_fields_match(spec, actual):\n    return set(actual) == set(\n        spec[\"components\"][\"schemas\"][\"StoredBook\"][\"properties\"]\n    )\n\nassert declared_fields_match(document, created_data)\nwrong_fields = deepcopy(document)\ndel wrong_fields[\"components\"][\"schemas\"][\"StoredBook\"][\"properties\"][\"published_year\"]\nassert not declared_fields_match(wrong_fields, created_data)\nwrong_route = deepcopy(document)\nwrong_route[\"paths\"][\"/catalogue/not-our-books/\"] = (\n    wrong_route[\"paths\"].pop(collection)\n)\nassert collection not in wrong_route[\"paths\"]\nassert client.get(\"/catalogue/not-our-books/\").status_code == 404\nprint(\"OPENAPI_TWO_VALID_LOOKING_DRIFTS_DETECTED\")\nprint(\"OPENAPI_REAL_CONTRACT_OK\")","language":"python","output":"OPENAPI_GENERATED_PATHS_METHODS_AND_FIELDS_OK\nOPENAPI_SCHEMA_AND_SWAGGER_UI_HTTP_200\nOPENAPI_REAL_POST_201_GET_200_AND_PERSISTENCE\nOPENAPI_REAL_400_404_405_NO_EXTRA_WRITES\nOPENAPI_TWO_VALID_LOOKING_DRIFTS_DETECTED\nOPENAPI_REAL_CONTRACT_OK"}},{"heading":"Understand the limitations before applying this to Steward","body":"A generated schema describes declared field shapes and status possibilities but does not discover all state-dependent rules: your Steward readiness conflict (409) requires explicit application annotation and an HTTP test. Security schemes in OpenAPI describe token transport, not the current user's permission to access a Team. These Book endpoints deliberately have no authentication and must remain local; the Identity module teaches real credentials and membership checks. A local Swagger UI appearing in the browser proves neither authentication nor data access control."}], ["Install drf-spectacular in the existing Django environment, create the complete files and append only the specified settings/routes; run python manage.py check.","Generate catalogue/openapi.json with --validate --fail-on-warn and identify paths, GET/POST operations, requestBody, 201/400/404 outcomes and StoredBook component properties.","Run the exact HTTP contract script and verify both false schema mutations fail their respective checks while the real schema passes.","Change the documented POST response to omit a required field without changing the code; predict and observe which contract test fails, then restore the annotation.","Explain why the schema/Swagger HTML are public-interface descriptions but do not establish Steward Team membership or authorization."], ["Why is Swagger UI not an alternative to OpenAPI?","What does @extend_schema add to an otherwise minimally introspectable APIView?","Why does a valid exported schema not establish that GET or POST actually works?","What is the difference between a missing documented route and an undocumented business conflict?","Why must authorization and its failure status be tested independently of schema generation?"], [{"title":"drf-spectacular — Schema Generation and Annotation","url":"https://drf-spectacular.readthedocs.io/en/latest/customization.html","kind":"documentation","purpose":"ModelSerializer extraction, annotations on APIView method and CLI schema validation."},{"title":"DRF — Schemas (deprecation)","url":"https://www.django-rest-framework.org/api-guide/schemas/","kind":"documentation","purpose":"Built-in generator deprecation and recommendation for drf-spectacular."},{"title":"OpenAPI 3.0.3 specification","url":"https://spec.openapis.org/oas/v3.0.3.html","kind":"reference","purpose":"Path and operation objects, requestBody, responses, components and security."}]),
  richLesson("OpenAPI and Swagger Documentation", "You have now generated, validated and tested an actual Book API schema and rendered Swagger UI from an unchanged Django project. Transfer that mechanism into Steward's documented Service contract, explicitly identifying business errors and security assumptions that cannot be inferred from a serializer alone.", ["Explain OpenAPI schema-generation and runtime conformance separately.","Document Steward's 409 readiness conflict and its stable public error envelope.","Distinguish bearer-token security scheme documentation from implemented Team-level authorization.","Define CI checks for schema completeness, compatibility and real HTTP behavior."], [{"heading":"Generator output is an informed starting point, not a contract guarantee","body":"The previous Book lesson proved that an annotated APIView can generate a valid OpenAPI file while a false path or field is still detectable only by runtime comparison. Steward's canonical lifecycle values are development/uat/production/retired and Service has an owning_team FK. A generated ModelSerializer may describe types but cannot infer every production-readiness transition rule. Review each externally visible operation and its failure cases, not just successful serializer shapes."},{"heading":"Document known domain conflict deliberately","body":"The actual registry/services.py command rejects a UAT→production promotion without a production Environment by raising ReadinessConflict. registry/api_errors.py translates that into HTTP 409 with an error.code of readiness_conflict. An OpenAPI response definition should document that 409 with the same envelope and a safe description. The source-derived HTTP test from the earlier lesson already proves stored state remains unchanged. Do not describe the conflict as a validation 400 or promise successful deployment from a serializer alone."},{"heading":"Do not promise an authentication system that is not implemented","body":"A future bearer security scheme will tell a consumer how to send a credential, but the currently demonstrated Steward training endpoints use an isolated server-selected Team fixture. They are NOT deployable and do not validate identity. A public Steward schema must include actual authentication/authorization rules only when the subsequent Identity module has implemented and tested them. Document pending requirements as explicitly not implemented rather than generating a fictional 401/403 guarantee."},{"heading":"What a schema validator actually proves","body":"The drf-spectacular CLI --validate checks OpenAPI document structure and --fail-on-warn catches generator introspection warnings. It cannot verify that a real response matches the declared field list or that API endpoints authorize the right caller. Combine generation with live request tests, negative inputs and state assertions. Keep an exported schema artifact and compare intentional changes through review; a new endpoint with no schema entry is a public contract defect."},{"heading":"Build a focused contract-review matrix","body":"For each Steward operation, record method/path, actual request fields, 2xx response, relevant 4xx/5xx outcomes, security assumption, corresponding runtime test, and whether the schema is generated, annotated or not yet implemented. Review /services/ list/create/detail, production transition 409, filtering/page params and per-Team visibility. If an operation lacks code or test evidence, mark it pending instead of inventing green acceptance."}], ["Use the generated Book OpenAPI file as a worked example and identify where its schema and runtime are cross-checked.","Prepare an explicit Steward contract matrix for list/create, detail, production transition and query/page endpoints; mark the training-only APIs as not public.","Write a schema annotation for the real readiness 409 shape, then compare it with the previously observed HTTP response.","Document exactly which bearer scheme and Team object permission checks must be deferred to the Identity module.","Propose a CI gate that validates the full public schema, performs representative live requests and fails on deliberately introduced schema drift."], ["What is the role of an operation-specific 409 response in a Service schema?","Which business rule cannot be inferred by ModelSerializer introspection?","Why would a valid generated bearer security scheme not prove Team authorization?","Why must both OpenAPI structural validation and real HTTP conformance exist?"], [{"title":"drf-spectacular — Schema Generation and Annotation","url":"https://drf-spectacular.readthedocs.io/en/latest/customization.html","kind":"documentation","purpose":"ModelSerializer extraction, annotations on APIView method and CLI schema validation."},{"title":"DRF — Schemas (deprecation)","url":"https://www.django-rest-framework.org/api-guide/schemas/","kind":"documentation","purpose":"Built-in generator deprecation and recommendation for drf-spectacular."},{"title":"OpenAPI 3.0.3 specification","url":"https://spec.openapis.org/oas/v3.0.3.html","kind":"reference","purpose":"Path and operation objects, requestBody, responses, components and security."}]),
  richLesson("Make Django Refuse Unsafe Training Configuration", "A Python function that parses configuration is not enough: Django must refuse unsafe settings before it can execute a query. Starting from the existing tsa-django-intro catalogue, connect environment input to the actual settings module, then prove five unsafe scenarios terminate before application code runs. This is deliberately a lab-only guard, not an invented production configuration system.", ["Explain why Django reads a settings module before managing models or handling requests.","Read environment values as strings, reject false-like boolean traps, limit database targets and protect a key from diagnostics.","Test effective DATABASES, DEBUG and ALLOWED_HOSTS through a genuinely new Django process.","Prove wrong-target, invalid flag, wildcard host, nonlocal mode and missing secret fail before an application command executes."], [{"heading":"What configuration actually changes","body":"Django imports config/settings.py during manage.py check, shell, migrate, and HTTP startup. DATABASES controls the connection used by ORM operations; DEBUG controls debugging behavior; ALLOWED_HOSTS checks Host headers; SECRET_KEY supports cryptographic signing. These settings are independent and none proves authentication or production readiness. If we merely validate an invented dictionary without connecting it to Django, the deployed process may still use unsafe values."},{"heading":"Build a strict, disposable lab policy","body":"Create config/lab_guard.py. It is a small readable function which accepts an explicit environment and the project BASE_DIR. Only the existing db.sqlite3 filename is accepted; the function constructs and resolves the database path inside this project. It accepts exact lowercase true/false instead of bool('false'), and only the three local Host values. It requires a sufficiently long secret from the environment without printing or returning it in exception messages. This guard intentionally refuses real remote databases and should never be mistaken for a complete deployment policy.","code":{"language":"python","caption":"config/lab_guard.py — check the effective training database target","value":"from pathlib import Path\n\ndef validated_lab_configuration(env, base_dir):\n    # This contract is ONLY for the disposable Django catalogue.\n    # It never authorizes a database other than db.sqlite3 in this project.\n    if env.get(\"TSA_TRAINING_MODE\") != \"local\":\n        raise ValueError(\"training mode must be local\")\n\n    db_name = env.get(\"TSA_TRAINING_DB\")\n    if db_name != \"db.sqlite3\":\n        raise ValueError(\"training database target rejected\")\n    database_path = (Path(base_dir) / db_name).resolve()\n    if database_path.parent != Path(base_dir).resolve():\n        raise ValueError(\"training database outside project\")\n\n    flag = env.get(\"TSA_TRAINING_DEBUG\")\n    if flag not in {\"true\", \"false\"}:\n        raise ValueError(\"training DEBUG must be true or false\")\n\n    hosts = env.get(\"TSA_TRAINING_HOSTS\", \"\").split(\",\")\n    if (not hosts or any(\n        host not in {\"testserver\", \"localhost\", \"127.0.0.1\"}\n        for host in hosts\n    )):\n        raise ValueError(\"training hosts not allowlisted\")\n\n    secret = env.get(\"TSA_TRAINING_SECRET_KEY\")\n    if not secret or len(secret) < 32:\n        raise ValueError(\"training secret key missing or too short\")\n    return {\n        \"DATABASES\": {\"default\": {\n            \"ENGINE\": \"django.db.backends.sqlite3\",\n            \"NAME\": str(database_path),\n        }},\n        \"DEBUG\": flag == \"true\",\n        \"ALLOWED_HOSTS\": hosts,\n        \"SECRET_KEY\": secret,\n    }"}},{"heading":"Wire the guard to Django's real settings","body":"Append the shown block at the end of config/settings.py without discarding earlier REST_FRAMEWORK or logging settings. The gate only activates with TSA_VALIDATE_TRAINING_SETTINGS=1, preserving prior beginner lessons' behavior. When active, it replaces the effective DATABASES, DEBUG, ALLOWED_HOSTS and SECRET_KEY from validated input. Any invalid value raises ValueError before Django can execute the requested shell command. This is a teaching opt-in, not a production fail-safe; a real deployment must enforce its own unconditional startup policy.","code":{"language":"python","caption":"config/settings.py — append guarded environment configuration","value":"# Append to config/settings.py, not to registry or any deployed service.\n# Prior Django lessons work unchanged when this explicit lab gate is disabled.\nimport os\nif os.environ.get(\"TSA_VALIDATE_TRAINING_SETTINGS\") == \"1\":\n    from config.lab_guard import validated_lab_configuration\n    safe = validated_lab_configuration(os.environ, BASE_DIR)\n    DATABASES = safe[\"DATABASES\"]\n    DEBUG = safe[\"DEBUG\"]\n    ALLOWED_HOSTS = safe[\"ALLOWED_HOSTS\"]\n    SECRET_KEY = safe[\"SECRET_KEY\"]"}},{"heading":"Verify startup using real new Python interpreters","body":"Save catalogue/settings_startup_lab.py and run it with manage.py shell after normal Book migrations. It launches new Django subprocesses with independent environment maps. The valid case checks the effective settings and reads a real Book row count from the already-migrated SQLite file. The five bad cases deliberately request that Django write an UNSAFE_DJANGO_QUERY_EXECUTED sentinel, but each must terminate at settings import before executing the body. The script checks exit codes, expected diagnostics, secret redaction, no unsafe database file and unchanged Book count.","code":{"language":"python","caption":"catalogue/settings_startup_lab.py — prove actual startup denial before a query","value":"# Save as catalogue/settings_startup_lab.py.\n# Run from manage.py: python manage.py shell -c\n# \"exec(open('catalogue/settings_startup_lab.py').read())\"\nimport os\nimport secrets\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nfrom django.conf import settings\nfrom catalogue.models import Book\n\nbase = Path.cwd()\nassert (base / \"manage.py\").is_file()\nassert settings.DATABASES[\"default\"][\"ENGINE\"] == \"django.db.backends.sqlite3\"\noriginal_count = Book.objects.count()\nrandom_training_secret = secrets.token_urlsafe(40)\nvalid_env = {\n    **os.environ,\n    \"TSA_VALIDATE_TRAINING_SETTINGS\": \"1\",\n    \"TSA_TRAINING_MODE\": \"local\",\n    \"TSA_TRAINING_DB\": \"db.sqlite3\",\n    \"TSA_TRAINING_DEBUG\": \"false\",\n    \"TSA_TRAINING_HOSTS\": \"testserver,localhost\",\n    \"TSA_TRAINING_SECRET_KEY\": random_training_secret,\n}\n\ndef check_with(env, python_command=None):\n    cmd = [sys.executable, \"manage.py\"]\n    if python_command is None:\n        cmd += [\"check\"]\n    else:\n        cmd += [\"shell\", \"-c\", python_command]\n    return subprocess.run(\n        cmd, cwd=base, env=env,\n        text=True, capture_output=True, timeout=30,\n    )\n\ncorrect = check_with(valid_env, (\n    \"from django.conf import settings; \"\n    \"from django.db import connection; \"\n    \"from catalogue.models import Book; \"\n    \"assert settings.DEBUG is False; \"\n    \"assert settings.ALLOWED_HOSTS == ['testserver','localhost']; \"\n    \"assert connection.settings_dict['NAME'].endswith('/db.sqlite3'); \"\n    \"assert Book.objects.count() >= 1; \"\n    \"print('EFFECTIVE_DJANGO_SETTINGS_AND_DB_OK')\"\n))\nassert correct.returncode == 0, correct.stderr\nassert \"EFFECTIVE_DJANGO_SETTINGS_AND_DB_OK\" in correct.stdout\nprint(\"STARTUP_VALID_CONFIG_REAL_DATABASE_OK\")\n\nbad_cases = [\n    (\"WRONG_DB\", {\"TSA_TRAINING_DB\": \"bank_production\"},\n     \"training database target rejected\"),\n    (\"INVALID_BOOLEAN\", {\"TSA_TRAINING_DEBUG\": \"False\"},\n     \"training DEBUG must be true or false\"),\n    (\"WILDCARD_HOST\", {\"TSA_TRAINING_HOSTS\": \"*\"},\n     \"training hosts not allowlisted\"),\n    (\"NOT_LOCAL\", {\"TSA_TRAINING_MODE\": \"production\"},\n     \"training mode must be local\"),\n    (\"MISSING_SECRET\", {\"TSA_TRAINING_SECRET_KEY\": \"\"},\n     \"training secret key missing or too short\"),\n]\nfor label, override, expected in bad_cases:\n    invalid = check_with({**valid_env, **override}, (\n        \"from pathlib import Path; \"\n        \"Path('UNSAFE_DJANGO_QUERY_EXECUTED').write_text('bad')\"\n    ))\n    assert invalid.returncode != 0, (label, invalid.stdout)\n    assert expected in invalid.stderr, (label, invalid.stderr)\n    assert random_training_secret not in invalid.stderr\n    assert not (base / \"UNSAFE_DJANGO_QUERY_EXECUTED\").exists()\n    print(\"STARTUP_REJECTED_\" + label)\n\nassert not (base / \"bank_production\").exists()\nassert Book.objects.count() == original_count\nprint(\"STARTUP_NO_WRONG_DATABASE_NO_WRITES\")\nprint(\"DJANGO_LAB_CONFIGURATION_OK\")","output":"STARTUP_VALID_CONFIG_REAL_DATABASE_OK\nSTARTUP_REJECTED_WRONG_DB\nSTARTUP_REJECTED_INVALID_BOOLEAN\nSTARTUP_REJECTED_WILDCARD_HOST\nSTARTUP_REJECTED_NOT_LOCAL\nSTARTUP_REJECTED_MISSING_SECRET\nSTARTUP_NO_WRONG_DATABASE_NO_WRITES\nDJANGO_LAB_CONFIGURATION_OK"}},{"heading":"Run it in the existing catalogue","body":"Use the same working directory that contains manage.py, and keep your initial migrations applied. First run python manage.py check without the opt-in; then the complete test script. No server, Docker or production credential is required. The training secret is randomly generated in memory by secrets.token_urlsafe and never printed.","code":{"language":"bash","caption":"Terminal — execute Django startup configuration tests","value":"python manage.py check\npython manage.py shell -c \"exec(open('catalogue/settings_startup_lab.py').read())\""}},{"heading":"Trace a wrong-target failure","body":"The bad target bank_production is never used as DATABASES['default']['NAME']; it is rejected before Django opens a connection. The test also proves no file named bank_production is created. A case with an unexpected `TSA_TRAINING_DEBUG=False` (capital F) fails deliberately: this local contract requires lowercase exact spelling. In a real configuration system, documenting accepted values prevents silent misunderstandings."},{"heading":"Configuration safety is bigger than these five values","body":"A real production Django deployment also needs CSRF trusted origins and cookies, HTTPS forwarding settings, security headers, logging, static file handling, a secure secret manager, database network controls, certificate validation and startup checks. ALLOWED_HOSTS is not authorization; DEBUG=False does not make a deployment safe. This intentionally minimal lab demonstrates the mechanism only. Production environment design follows later Delivery, Security and Identity training."},{"heading":"Prove understanding without copying","body":"Create an extra invalid-host case using example.com, predict the failure message and prove no sentinel file appears. Then add an explicitly allowed local hostname to the guard and test the effect on a real Host request in a disposable branch. Explain why a config file checked into Git with an actual bank password would invalidate the entire approach."}], ["Save the two complete Python files and append the settings snippet to the existing project.","Run the exact new-process startup lab; report effective DB target and five separate failures without printing the generated key.","Add one new rejected database name and predict the outcome before running it.","Explain why rejecting a wrong target before importing models is stronger than catching a database exception after a query.","Identify at least four production security settings not established by this lab."], ["What actually imports settings.py during manage.py check?","Why is bool('false') unsafe for environment booleans?","Which assertions prove the bad configuration never executed application code?","Why does an opt-in lab guard not constitute an enforceable production safety control?"], [{"title":"Django — Settings","url":"https://docs.djangoproject.com/en/5.2/topics/settings/","kind":"reference","purpose":"Settings modules, environment values, effective DATABASES/DEBUG/ALLOWED_HOSTS and SECRET_KEY."},{"title":"Django — Deployment checklist","url":"https://docs.djangoproject.com/en/5.2/howto/deployment/checklist/","kind":"documentation","purpose":"Production security settings require more than safe local defaults."},{"title":"Python — subprocess","url":"https://docs.python.org/3/library/subprocess.html","kind":"reference","purpose":"Check real child-process exit codes and capture diagnostics without exposing credentials."}]),
  richLesson("Configuration and Environments", "Configuration decides which database, domains and security controls a running application actually uses. A single codebase can run safely in a disposable lab and dangerously in production if a connection string or DEBUG flag is wrong. Learn to validate typed settings before launching, separate code from secrets, and test failure-to-start rather than expecting a password in a checked-in file.", ["Distinguish settings/code, nonsecret environment configuration and secret credentials.","Parse booleans safely and fail closed on missing required settings.","Explain why DEBUG, hosts, CSRF/trusted origins and database targets are independent controls.","Prove a production target cannot be accidentally accepted by a local destructive teaching script."], [{"heading":"A deployment is a code version plus a configuration set","body":"Django's DATABASES chooses a server and database; ALLOWED_HOSTS controls accepted HTTP Host headers; CSRF_TRUSTED_ORIGINS concerns browser cross-origin unsafe requests; DEBUG affects error handling and information disclosure. None substitutes for the others. The local PostgreSQL/Django labs must use distinct nonproduction database names and user permissions. A correct query on the wrong database can still corrupt valuable data."},{"heading":"Validate startup configuration with an executable parser","body":"Treat environment variables as untrusted text supplied by the deployment system: bool('false') is True in Python. Reject unexpected boolean strings and forbid a development script from running against a production database name. The example uses a supplied dictionary to avoid reading/printing secrets. The database password is intentionally represented only by existence, not its value.","code":{"language":"python","caption":"Django configuration — executable environment contract","value":"def configuration(env):\n    db = env.get(\"PGDATABASE\")\n    if not db:\n        raise ValueError(\"PGDATABASE missing\")\n    if db not in (\"tsa_steward_lab\",\"tsa_steward_django_lab\"):\n        raise ValueError(\"unsafe database target\")\n    debug = env.get(\"DJANGO_DEBUG\",\"false\").lower()\n    if debug not in (\"true\",\"false\"):\n        raise ValueError(\"invalid DEBUG\")\n    return {\"db\":db, \"debug\":debug==\"true\"}\n\nassert configuration({\"PGDATABASE\":\"tsa_steward_django_lab\",\"DJANGO_DEBUG\":\"false\"})[\"debug\"] is False\nfor bad in [{\"PGDATABASE\":\"bank_production\"},{\"PGDATABASE\":\"tsa_steward_lab\",\"DJANGO_DEBUG\":\"not-sure\"},{}]:\n    try:\n        configuration(bad)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError(\"unsafe configuration accepted\")\nprint(\"configuration: valid local and 3 rejected setups\")"}},{"heading":"Make secret handling a required boundary","body":"Never commit database passwords, Django SECRET_KEY or bearer tokens in source files or sample screenshots. In CI use short-lived, isolated environment-specific credentials; a dedicated database user should not have permission to alter other databases. A .env file may help local learning but must be excluded from version control and guarded from accidental upload; an environment variable alone does not magically prevent secret exposure. Avoid echoing connection URLs that contain passwords into logs."},{"heading":"Environments need configuration parity and intentional differences","body":"Development may permit DEBUG for local inspection but production must disable it. Security response headers, authentication requirements and authorization rules should remain representative across QA and production unless an explicit test requires otherwise. Use different DB names and credentials, not weaker permission checks. Document which test data and deployment values are synthetic and which checks are disabled, otherwise a QA pass can be misleading."},{"heading":"Test the wrong-target failure, not only the happy path","body":"Before running any migration or seed script, display/verify the selected database identity without exposing credentials. The live PostgreSQL test runner asserts PGDATABASE=tsa_steward_lab and the Django runner switches specifically to tsa_steward_django_lab. Extend this to your personal exercise: simulate bank_production and prove the process aborts before executing SQL. Also test missing variable and invalid DEBUG. A configuration schema with no negative tests is incomplete."}], ["Run the pure configuration example and prove 3 rejected setups.","Document the variables required for the Django-managed lab and PostgreSQL SQL fixture, marking secret/nonsecret and safe targets.","Implement a startup check that refuses dangerous database names before running a migration or seed.","Compare QA and production configuration with a focus on security-policy parity and deliberately different secrets."], ["Why does bool('false') evaluate True?","Why does DEBUG=false not establish that a server is safe?","Why can correct SQL still be dangerous with a wrong target database?"], [{"title":"Django — Settings","url":"https://docs.djangoproject.com/en/5.2/ref/settings/","kind":"documentation","purpose":"Official DEBUG, ALLOWED_HOSTS, security and database configuration."},{"title":"Django — Deployment checklist","url":"https://docs.djangoproject.com/en/5.2/howto/deployment/checklist/","kind":"documentation","purpose":"Production security and startup checks."}]),
  richLesson("Python Logging: Follow a Message to Its Destination", "Before configuring Django, see what Python logging actually does. We begin with a standalone Python program and one observable record, not an external monitoring stack.", ["Explain how a record reaches a handler.","Predict logger and handler threshold behavior.","Diagnose duplicate output from propagation.","Choose levels and context without leaking secrets."], [
    { heading: "Why use logging instead of print?", body: "A print statement writes text directly to a stream. A logging call creates a record with a severity, a logger name, a message and optional exception details. The logging system decides whether a record should be handled and where it goes. This lets an application keep DEBUG details out of production output while retaining warnings. Logging is not a database: a console handler does not automatically store records after the process exits." },
    { heading: "The five pieces of a log message", body: "A logger is a named entry point, such as catalogue.api. A record is one emitted event. A handler delivers accepted records to a destination such as a stream or file. A formatter determines the visible representation. A filter can further accept or reject records. Logger and handler severity thresholds both matter; a DEBUG logger paired with a WARNING handler will not show INFO messages. Python's standard levels increase as DEBUG, INFO, WARNING, ERROR, CRITICAL." },
    { heading: "Run a complete Python example", body: "Save this as logging_first_steps.py and run python3 logging_first_steps.py. It does not require Django, a server, a database or Docker. The buffer makes the actual emitted result visible and testable. The INFO event passes the logger but is rejected by the WARNING handler; the WARNING event appears. The %s placeholder is interpolated by logging when handled.", code: {"language":"python","caption":"logging_first_steps.py — real logger and handler levels","value":"import io\nimport logging\n\ncaptured = io.StringIO()\nhandler = logging.StreamHandler(captured)\nhandler.setLevel(logging.WARNING)\nhandler.setFormatter(logging.Formatter(\"%(levelname)s %(name)s %(message)s\"))\n\nlogger = logging.getLogger(\"catalogue.example\")\nlogger.handlers.clear()  # Isolate this exercise from other handlers.\nlogger.setLevel(logging.DEBUG)\nlogger.addHandler(handler)\nlogger.propagate = False\n\nlogger.info(\"book_created book_id=%s\", 7)\nlogger.warning(\"book_rejected reason=%s\", \"missing_title\")\nprint(captured.getvalue().strip())","output":"WARNING catalogue.example book_rejected reason=missing_title"} },
    { heading: "Why the same event sometimes appears twice", body: "Logger names form a hierarchy: catalogue.api has parent catalogue. By default, a child's accepted record propagates to parent handlers. Adding handlers at both levels can duplicate one event. Run this independent example; the record is emitted twice, then once after propagation is disabled at the child. Do not blindly disable propagation everywhere: first understand where the application's handlers live.", code: {"language":"python","caption":"logging_propagation.py — reproduce and fix duplicate messages","value":"import io\nimport logging\n\noutput = io.StringIO()\nparent = logging.getLogger(\"catalogue\")\nchild = logging.getLogger(\"catalogue.api\")\nfor current in (parent, child):\n    current.handlers.clear()\n    current.setLevel(logging.DEBUG)\n    handler = logging.StreamHandler(output)\n    handler.setFormatter(logging.Formatter(\"%(message)s\"))\n    current.addHandler(handler)\n\nchild.propagate = True\nchild.warning(\"duplicate_event\")\nprint(\"before:\", output.getvalue().count(\"duplicate_event\"))\n\noutput.seek(0)\noutput.truncate(0)\nchild.propagate = False\nchild.warning(\"single_event\")\nprint(\"after:\", output.getvalue().count(\"single_event\"))","output":"before: 2\nafter: 1"} },
    { heading: "How to choose a level", body: "DEBUG is for detailed development diagnostics; INFO for routine events whose occurrence matters; WARNING for an unusual but handled condition; ERROR for a failed operation; CRITICAL for a severe system failure. Do not turn every user validation mistake into ERROR. Log exceptions with traceback where unexpected faults are caught, not as routine noise. A log event should answer a diagnostic question; naming matters more than decorating it with extra words." },
    { heading: "What should never appear in logs", body: "Passwords, session tokens, authorization headers, secret keys and unnecessary personal data must not be passed into formatting arguments or extra fields. Avoid printing whole request bodies. Use stable non-secret identifiers and a supplied request/correlation ID if one is available. An example that avoids logging a demo token is a teaching boundary, not proof an entire application is secure." },
  ], ["Create logging_first_steps.py from the example and run it; show exactly one WARNING line.","Change the handler to INFO; predict and verify the extra line, then restore it.","Run logging_propagation.py; explain why before=2 and after=1.","Invent one safe event for an ordinary library checkout rejection and explain which fields must be excluded."], ["Why does logger.setLevel(DEBUG) not guarantee an INFO record will appear?","Why does one logging call produce two lines when the child and parent have handlers?","Where does a console log go after its process exits?"], [{"title":"Python Logging HOWTO","url":"https://docs.python.org/3/howto/logging.html","kind":"documentation","purpose":"Official logger/handler/formatter mechanics and configuration examples."}]),

  richLesson("Application Logging", "Use Python logging in the Django scratch project you already built. This lesson establishes a working event path from a named application module through Django settings to console output, then makes missing and duplicate logs diagnosable.", ["Configure a named application logger in Django.","Run two reproducible events and inspect their output.","Distinguish level filtering from propagation.","Treat event context, exceptions and secrets deliberately."], [
    { heading: "What Django adds to Python logging", body: "Django uses Python's logging library. It configures loggers during django.setup() and normally extends its defaults through the LOGGING setting. Do not log during settings.py import and do not assume DEBUG=True makes your own logger verbose. The earlier Python lesson already showed logger, handler, formatter, level and propagation; Django mainly gives you a project-wide place to configure them." },
    { heading: "Configure the existing catalogue project", body: "Reuse the tsa-django-intro scratch project from the earlier Django lessons. Add this LOGGING dictionary to config/settings.py; do not replace the file. The named catalogue logger receives records from catalogue.logging_demo. The logger and handler both accept INFO and above, the formatter exposes severity/logger/event, and propagate=False at catalogue avoids duplicate records through the root logger. Keep disable_existing_loggers=False so Django's preconfigured loggers are not silently disabled.", code: {"language":"python","caption":"config/settings.py — configure a dedicated catalogue logger","value":"# Add this dictionary near the end of config/settings.py.\n# Keep your existing INSTALLED_APPS, DATABASES, and other settings.\nLOGGING = {\n    \"version\": 1,\n    \"disable_existing_loggers\": False,\n    \"formatters\": {\n        \"brief\": {\"format\": \"%(levelname)s %(name)s %(message)s\"},\n    },\n    \"handlers\": {\n        \"catalogue_console\": {\n            \"class\": \"logging.StreamHandler\",\n            \"formatter\": \"brief\",\n            \"level\": \"INFO\",\n        },\n    },\n    \"loggers\": {\n        \"catalogue\": {\n            \"handlers\": [\"catalogue_console\"],\n            \"level\": \"INFO\",\n            \"propagate\": False,\n        },\n    },\n}"} },
    { heading: "Log an event from an ordinary Python module", body: "Create catalogue/logging_demo.py. __name__ becomes catalogue.logging_demo when Django imports this module. The function has a normal return value independent of logging: a positive id returns a book dictionary; an invalid id returns None and emits a warning. A log is diagnostic evidence, not an API response and not a database write.", code: {"language":"python","caption":"catalogue/logging_demo.py — two observable application events","value":"# Save as catalogue/logging_demo.py in the existing Django scratch project.\nimport logging\n\nlogger = logging.getLogger(__name__)\n\ndef find_book(book_id: int):\n    if book_id <= 0:\n        logger.warning(\"book_lookup_rejected reason=invalid_id\")\n        return None\n    logger.info(\"book_lookup_requested book_id=%s\", book_id)\n    return {\"id\": book_id}"} },
    { heading: "Run it and inspect the result", body: "Run the command from the directory containing manage.py. Expect one INFO line containing book_lookup_requested book_id=5, one WARNING line containing book_lookup_rejected reason=invalid_id, and printed Python results {'id': 5} and None. Log lines normally go to stderr while print goes to stdout, so their interleaving may vary. If no log appears, inspect the logger name, effective level, handler level and propagation before editing the function.", code: {"language":"bash","caption":"Terminal — execute the Django logging example","value":"# From the directory containing manage.py:\npython manage.py shell -c \"from catalogue.logging_demo import find_book; print(find_book(5)); print(find_book(-1))\"","output":"INFO catalogue.logging_demo book_lookup_requested book_id=5\nWARNING catalogue.logging_demo book_lookup_rejected reason=invalid_id\n{'id': 5}\nNone  # Stream order may differ"} },
    { heading: "Experiment with filtering and duplicates", body: "Change the catalogue_console handler level from INFO to WARNING, restart the shell command and predict the result before running it: the successful INFO event disappears but the rejection WARNING remains, while both function return values are unchanged. Restore INFO afterwards. If an event appears twice, check whether a handler is also attached to an ancestor; if none appears, check both levels and disabled loggers. Do not solve logging defects by printing sensitive request objects." },
    { heading: "Exceptions, security and production boundaries", body: "For an unexpected error caught at a boundary, logger.exception('catalogue_lookup_failed') inside an except block includes traceback data. Do not use logger.exception for an ordinary invalid book id. Never log access tokens, passwords or complete request payloads; use narrow IDs and error categories. Console delivery is enough for this local lesson. Rotation, collection, aggregation and alerting are introduced in later operations/reliability material, not assumed here." },
  ], ["Apply the sample LOGGING dictionary to the existing Django scratch project; run python manage.py check.","Create catalogue/logging_demo.py, run the shell command, capture stderr and stdout and explain both output streams.","Change the handler level to WARNING, predict exactly which message disappears, then restore INFO.","In a second experiment, attach an extra handler to an ancestor with propagation enabled; observe a duplicate and fix the configuration.","Only after the independent example works, add one safe INFO event and one ordinary rejected-operation WARNING event to the Steward practical. Document the diagnostic question answered by each and verify that secrets are absent."], ["Why does a logger named catalogue.logging_demo inherit a mapping configured for catalogue?","What is the difference between an INFO event being filtered out and a failed Python function call?","When is logger.exception appropriate, and why should it not be used for routine validation?","Where would you investigate a missing log: Python function, Django settings, handler, or propagation? Justify the order."]),

  richLesson("Map a Directed Service Dependency into Django", "The PostgreSQL Steward schema already contains a directed ServiceDependency table with two foreign keys, a unique ordered pair and a prohibition on self-dependency. Your Django registry currently has Team, Service, and Environment only. Before building dependency APIs, you must make the existing SQL contract real in Django and test its database constraints, not just draw a graph.", ["Map a directed source/target edge into two ForeignKeys with different reverse names.","Generate and inspect a fifth migration without disturbing the already-migrated Service rows.","Prove the database rejects self-edges, duplicate directed edges and missing foreign-key targets.","Show why reversed edges remain distinct and why PROTECT does not implement a cycle-detection policy."], [{"heading":"Read the locked PostgreSQL model first","body":"The existing disposable SQL schema defines service_dependency(id, source_service_id, target_service_id). UNIQUE(source_service_id,target_service_id) distinguishes a directed edge. CHECK(source_service_id <> target_service_id) forbids only self-dependency. A→B and B→A are different valid rows; the schema does NOT guarantee that longer cycles are impossible. Each endpoint is a stored Service primary key and each delete must respect referential integrity."},{"heading":"Reuse the actual migrated registry","body":"Continue the separate PostgreSQL-backed Django Steward project you built for schema evolution, not the Book catalogue and not the unrelated pure SQL shell. Its registry 0001–0004 migrations have been applied and Service.slug is now required and unique. Confirm with python manage.py showmigrations registry and python manage.py check. Append one new model BELOW existing Team, Service and Environment; do not overwrite earlier definitions or generate a new project."},{"heading":"Describe the edge as two separate relationships","body":"Append the complete class. source_service and target_service point to Service but have different related_name values to disambiguate reverse navigation. PROTECT prevents deleting either endpoint while edges reference it. UniqueConstraint and CheckConstraint are enforced by PostgreSQL even if someone bypasses model.full_clean. The Q expression compares the two stored FK IDs on the same row; a self edge is not allowed.","code":{"language":"python","caption":"registry/models.py — append ServiceDependency with database constraints","value":"# Append this class below Team, Service and Environment in registry/models.py.\n# The existing file already imports models from django.db.\nclass ServiceDependency(models.Model):\n    source_service = models.ForeignKey(\n        Service, on_delete=models.PROTECT,\n        related_name=\"outgoing_dependencies\",\n    )\n    target_service = models.ForeignKey(\n        Service, on_delete=models.PROTECT,\n        related_name=\"incoming_dependencies\",\n    )\n\n    class Meta:\n        db_table = \"service_dependency\"\n        constraints = [\n            models.UniqueConstraint(\n                fields=[\"source_service\", \"target_service\"],\n                name=\"uq_service_dependency_direction\",\n            ),\n            models.CheckConstraint(\n                condition=~models.Q(\n                    source_service_id=models.F(\"target_service_id\")\n                ),\n                name=\"ck_service_dependency_not_self\",\n            ),\n        ]"}},{"heading":"Generate the numbered migration, then read its SQL","body":"After saving the model, run makemigrations registry --name service_dependency: the next filename should be 0005_service_dependency.py. Use sqlmigrate registry 0005 to inspect the actual CREATE TABLE, FK, unique and CHECK operations before applying migrate registry 0005. The source is a complete class but the migration is generated by Django from the project state: it is not an unspecified file the lesson pretends already exists.","code":{"language":"bash","caption":"Terminal — add and inspect the directed dependency migration","value":"# Use ONLY the already-migrated Django Steward scratch project.\n# Before editing: python manage.py showmigrations registry must show 0004 applied.\n# Append ServiceDependency to the existing registry/models.py; do not replace it.\npython manage.py check\npython manage.py makemigrations registry --name service_dependency\npython manage.py sqlmigrate registry 0005\npython manage.py migrate registry 0005\npython manage.py makemigrations registry --check --dry-run\npython manage.py shell -c \"exec(open('registry/dependency_integrity_lab.py').read())\"\n# Restart the Python process and confirm both directional edges persist:\npython manage.py shell -c \"from registry.models import ServiceDependency; assert ServiceDependency.objects.filter(source_service__name='Dependency Workshop API', target_service__name='Dependency Workshop Identity').exists(); print('DEPENDENCY_REOPENED_OK')\""}},{"heading":"Test both positive directions and three genuine rejects","body":"Save the full script below as registry/dependency_integrity_lab.py and run it via manage.py shell in the migrated scratch project. It creates two fictional UAT Services with required slugs and valid owning Team, then creates A→B and B→A. It wraps three attempted broken writes in transaction.atomic because PostgreSQL may enforce a foreign key at transaction end; catches actual IntegrityError and proves row count is unchanged. The test also exercises ProtectedError when deleting a referenced Service.","code":{"language":"python","caption":"registry/dependency_integrity_lab.py — two directions and PostgreSQL rejections","value":"# Save as registry/dependency_integrity_lab.py in the migrated Steward app.\nfrom django.db import IntegrityError, transaction\nfrom django.db.models.deletion import ProtectedError\nfrom registry.models import Team, Service, ServiceDependency\n\nteam, _ = Team.objects.get_or_create(name=\"Dependency Workshop\")\ndef make_service(name, code):\n    service, _ = Service.objects.get_or_create(\n        name=name,\n        defaults={\n            \"slug\": code,\n            \"owning_team\": team,\n            \"endpoint\": \"https://workshop.example.invalid/\" + code,\n            \"lifecycle\": Service.Lifecycle.UAT,\n        },\n    )\n    return service\n\napi = make_service(\"Dependency Workshop API\", \"dependency-workshop-api\")\nidentity = make_service(\"Dependency Workshop Identity\", \"dependency-workshop-identity\")\nassert api.pk != identity.pk\n\nfirst, created = ServiceDependency.objects.get_or_create(\n    source_service=api, target_service=identity,\n)\nassert created\nreverse, reverse_created = ServiceDependency.objects.get_or_create(\n    source_service=identity, target_service=api,\n)\nassert reverse_created and first.pk != reverse.pk\nassert (first.source_service_id, first.target_service_id) == (\n    reverse.target_service_id, reverse.source_service_id\n)\nprint(\"DIRECTED_DEPENDENCIES_BOTH_DIRECTIONS\")\n\ndef database_rejects(label, **fields):\n    before = ServiceDependency.objects.count()\n    try:\n        with transaction.atomic():\n            ServiceDependency.objects.create(**fields)\n    except IntegrityError:\n        assert ServiceDependency.objects.count() == before\n        print(label)\n    else:\n        raise AssertionError(label + \" was accepted\")\n\ndatabase_rejects(\n    \"SELF_DEPENDENCY_DB_REJECTED\",\n    source_service=api, target_service=api,\n)\ndatabase_rejects(\n    \"DUPLICATE_DEPENDENCY_DB_REJECTED\",\n    source_service=api, target_service=identity,\n)\ndatabase_rejects(\n    \"UNKNOWN_DEPENDENCY_FK_DB_REJECTED\",\n    source_service_id=987654321, target_service=identity,\n)\ntry:\n    identity.delete()\nexcept ProtectedError:\n    assert Service.objects.filter(pk=identity.pk).exists()\n    print(\"DEPENDENCY_TARGET_DELETE_PROTECTED\")\nelse:\n    raise AssertionError(\"Referenced Service deletion succeeded\")\n\nassert ServiceDependency.objects.filter(\n    source_service=api, target_service=identity\n).count() == 1\nassert ServiceDependency.objects.filter(\n    source_service=identity, target_service=api\n).count() == 1\nprint(\"DEPENDENCY_DATABASE_LAB_OK\")","output":"DIRECTED_DEPENDENCIES_BOTH_DIRECTIONS\nSELF_DEPENDENCY_DB_REJECTED\nDUPLICATE_DEPENDENCY_DB_REJECTED\nUNKNOWN_DEPENDENCY_FK_DB_REJECTED\nDEPENDENCY_TARGET_DELETE_PROTECTED\nDEPENDENCY_DATABASE_LAB_OK"}},{"heading":"Verify durability and state consistency","body":"The last command in the terminal block opens a genuinely new Django shell and re-reads the A→B edge. The exercise also asserts makemigrations --check --dry-run reports no differences between Python models and migration state. If it reports a pending change, stop and correct your model or migration rather than inventing success. After this lesson you have a real DB relationship, not a protected HTTP endpoint or authorization policy."},{"heading":"What this model does not settle","body":"Acyclic graph enforcement, dependency deletion rights, cross-Team visibility, service version compatibility, transaction-level graph changes and dependency-impact analysis are not provided here. Adding a self-edge check does not stop A→B→C→A. The later integrated API and Identity modules will establish which users may create or remove edges and which validation belongs in a transaction-backed command."}], ["Append the class after the existing Service model and generate/apply migration 0005 in the already-owned disposable PostgreSQL Django project.","Run the published exact script and verify each named database rejection, not just model-level Python validation.","Explain why both A→B and B→A can exist while A→A is rejected.","Reopen the edge from a fresh manage.py shell and inspect sqlmigrate output for actual database constraints.","Describe a three-Service cycle and explain why the existing CHECK does not forbid it."], ["What does UNIQUE(source_service_id,target_service_id) enforce and what does it leave possible?","Why must the two ForeignKeys have different reverse relationship names?","What does transaction.atomic achieve for the foreign-key failure test?","How would the database behave if a referenced Service were deleted?","Does this constraint enforce an acyclic graph?"], [{"title":"Django 5.2 — Constraints","url":"https://docs.djangoproject.com/en/5.2/ref/models/constraints/","kind":"documentation","purpose":"Database CheckConstraint and UniqueConstraint semantics."},{"title":"Django 5.2 — ForeignKey","url":"https://docs.djangoproject.com/en/5.2/ref/models/fields/","kind":"documentation","purpose":"Relationship descriptors and protective deletes."},{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"Schema history and reviewable generated migrations."}]),

  richLesson("Persist a Steward Service Review History", "A Service can receive more than one review, and later reviews must not erase earlier conclusions. Your earlier PostgreSQL exercise used a session-limited service_review sketch; now build the durable Django version in the same migrated Steward registry. Treat reviewer labels as synthetic text until Identity teaches verified users.", ["Represent an independent historical review event with a real service foreign key and UTC timestamp.","Generate migration 0006 after the dependency migration, inspect SQL and preserve previously stored rows.","Store multiple reviews for one Service, including two with the same timestamp, with deterministic ID tie-break ordering.","Prove database rejection of invalid verdicts and unknown Services, and distinguish stored history from immutable audit enforcement."], [{"heading":"Current status and history are different kinds of data","body":"A single Service.current_verdict field would lose the previous state when overwritten. Instead a review is a separate record with a unique ID, service reference, reviewer label, verdict and timestamp. Repeating service_id is allowed: one Service may have multiple reviews. The earlier SQL sketch specified verdict pass/followup and reviewed_at timestamptz; the Django DateTimeField with USE_TZ=True represents that instant."},{"heading":"Be precise about what reviewer means","body":"This is a synthetic teaching label like synthetic-a, not an authenticated person or authorization claim. The later Identity school will replace or associate this representation with verified principal data, define role checks and retention rules. Hard-coded learner names and request-supplied 'reviewer' values must never become an authoritative audit actor in production."},{"heading":"Append a durable model with the right constraints","body":"Append ServiceReview to the SAME registry/models.py after ServiceDependency. It uses ForeignKey with PROTECT so an established review cannot be orphaned by deleting its Service; multiple review rows per Service are permitted. CheckConstraint enforces pass/followup in PostgreSQL even for direct ORM writes that do not call full_clean. Meta.ordering uses reviewed_at then PK so reviews with equal timestamps have an unambiguous order.","code":{"language":"python","caption":"registry/models.py — append historical ServiceReview with verdict CHECK","value":"# Append this class below ServiceDependency in registry/models.py.\n# This representation follows the earlier disposable PostgreSQL review sketch.\nclass ServiceReview(models.Model):\n    class Verdict(models.TextChoices):\n        PASS = \"pass\", \"Pass\"\n        FOLLOWUP = \"followup\", \"Follow-up\"\n\n    service = models.ForeignKey(\n        Service, on_delete=models.PROTECT, related_name=\"reviews\",\n    )\n    reviewer = models.TextField()  # Fictional label, NOT a verified identity.\n    verdict = models.CharField(max_length=8, choices=Verdict.choices)\n    reviewed_at = models.DateTimeField()\n\n    class Meta:\n        db_table = \"service_review\"\n        ordering = [\"reviewed_at\", \"pk\"]\n        constraints = [\n            models.CheckConstraint(\n                condition=models.Q(verdict__in=[\"pass\", \"followup\"]),\n                name=\"ck_service_review_verdict\",\n            ),\n        ]"}},{"heading":"Generate migration 0006 after the earlier 0005","body":"Run the commands from the project with manage.py. Ensure the dependency migration 0005 already exists and is applied. django makemigrations then generates 0006_service_review.py. Inspect sqlmigrate for a new service_review table, FK, CHECK and time-zone-aware field. Apply it and check that no model-state differences remain.","code":{"language":"bash","caption":"Terminal — migrate review events without altering existing Services","value":"# Same disposable Steward Django project; dependency migration 0005 applied.\n# Append ServiceReview to the existing registry/models.py; do not replace it.\npython manage.py check\npython manage.py makemigrations registry --name service_review\npython manage.py sqlmigrate registry 0006\npython manage.py migrate registry 0006\npython manage.py makemigrations registry --check --dry-run\npython manage.py shell -c \"exec(open('registry/review_history_lab.py').read())\"\n# Fresh process: all three persisted history rows remain.\npython manage.py shell -c \"from registry.models import ServiceReview; assert ServiceReview.objects.filter(service__name='Review Workshop API').count() == 3; print('REVIEW_HISTORY_REOPENED_OK')\""}},{"heading":"Prove historic rows and database constraints on real PostgreSQL","body":"Save registry/review_history_lab.py. It creates a new fictional UAT Service with required slug and three separate review events. The second and third share a timestamp yet have different IDs; both must survive. Invalid verdict and nonexistent Service ID writes throw real database IntegrityError with unchanged event count. Deleting the reviewed Service raises ProtectedError. This is a one-time lab: a second full run deliberately fails rather than silently manufacturing duplicate review facts.","code":{"language":"python","caption":"registry/review_history_lab.py — three events and real negative writes","value":"# Save as registry/review_history_lab.py. Run once after migration 0006.\nfrom datetime import datetime, timezone\nfrom django.db import IntegrityError, transaction\nfrom django.db.models.deletion import ProtectedError\nfrom registry.models import Team, Service, ServiceReview\n\nteam, _ = Team.objects.get_or_create(name=\"Review Workshop\")\nservice, fresh = Service.objects.get_or_create(\n    name=\"Review Workshop API\",\n    defaults={\n        \"slug\": \"review-workshop-api\",\n        \"owning_team\": team,\n        \"endpoint\": \"https://workshop.example.invalid/reviews\",\n        \"lifecycle\": Service.Lifecycle.UAT,\n    },\n)\nassert fresh, \"Run this one-time history experiment in a clean training DB.\"\n\njan = datetime(2026, 1, 10, 10, tzinfo=timezone.utc)\nfeb = datetime(2026, 2, 10, 10, tzinfo=timezone.utc)\nfirst = ServiceReview.objects.create(\n    service=service, reviewer=\"synthetic-a\",\n    verdict=ServiceReview.Verdict.FOLLOWUP, reviewed_at=jan,\n)\nsecond = ServiceReview.objects.create(\n    service=service, reviewer=\"synthetic-b\",\n    verdict=ServiceReview.Verdict.PASS, reviewed_at=feb,\n)\nthird = ServiceReview.objects.create(\n    service=service, reviewer=\"synthetic-c\",\n    verdict=ServiceReview.Verdict.FOLLOWUP, reviewed_at=feb,\n)\nhistory = list(service.reviews.values_list(\"pk\", \"verdict\"))\nassert history == [\n    (first.pk, \"followup\"), (second.pk, \"pass\"), (third.pk, \"followup\")\n]\nassert ServiceReview.objects.filter(service=service).count() == 3\nassert ServiceReview.objects.filter(service=service, reviewed_at=feb).count() == 2\nprint(\"THREE_HISTORICAL_REVIEWS_SAME_SERVICE_AND_TIMESTAMP_TIE\")\n\ndef review_database_rejects(label, **fields):\n    before = ServiceReview.objects.count()\n    try:\n        with transaction.atomic():\n            ServiceReview.objects.create(**fields)\n    except IntegrityError:\n        assert ServiceReview.objects.count() == before\n        print(label)\n    else:\n        raise AssertionError(label + \" was accepted\")\n\nreview_database_rejects(\n    \"INVALID_REVIEW_VERDICT_DB_REJECTED\",\n    service=service, reviewer=\"synthetic-invalid\",\n    verdict=\"unknown\", reviewed_at=feb,\n)\nreview_database_rejects(\n    \"UNKNOWN_REVIEW_SERVICE_FK_DB_REJECTED\",\n    service_id=987654321, reviewer=\"synthetic-invalid\",\n    verdict=\"pass\", reviewed_at=feb,\n)\ntry:\n    service.delete()\nexcept ProtectedError:\n    assert Service.objects.filter(pk=service.pk).exists()\n    print(\"REVIEWED_SERVICE_DELETE_PROTECTED\")\nelse:\n    raise AssertionError(\"Reviewed Service deletion succeeded\")\n\nassert ServiceReview.objects.get(pk=first.pk).verdict == \"followup\"\nassert ServiceReview.objects.get(pk=second.pk).verdict == \"pass\"\nprint(\"SERVICE_REVIEW_DATABASE_LAB_OK\")","output":"THREE_HISTORICAL_REVIEWS_SAME_SERVICE_AND_TIMESTAMP_TIE\nINVALID_REVIEW_VERDICT_DB_REJECTED\nUNKNOWN_REVIEW_SERVICE_FK_DB_REJECTED\nREVIEWED_SERVICE_DELETE_PROTECTED\nSERVICE_REVIEW_DATABASE_LAB_OK"}},{"heading":"Reopen the timeline in a new process","body":"The final command closes the first Python process and confirms all three events persist. Note that django model default ordering is helpful for presentation but an API should still declare its own explicit ordering and pagination contract. Avoid implying that a 200 response or serializer alone establishes historical integrity."},{"heading":"Do not misuse the phrase append-only","body":"This schema stores separate historical facts but does NOT prevent database UPDATE or DELETE by a sufficiently privileged process. Real append-only/audit guarantees need an explicit mutation policy and database permissions, possibly triggers/event ingestion or separate audit records. We will implement only create/list API operations as a later checkpoint, with real Identity/permissions to follow."}], ["Append the Review model without replacing existing service or dependency definitions; generate/review/apply migration 0006.","Execute the exact three-event source in the isolated PostgreSQL Django registry and capture all four positive/negative checks.","Restart Django shell and prove the historical event count, ordering and original Service identity are unchanged.","Explain why UNIQUE(service_id) would violate the domain's history requirement.","Describe which guarantees are still missing if a system administrator updates one recorded verdict."], ["Why is one review row per Service insufficient for a review history?","Why is an explicit PK tie-breaker required for simultaneous events?","Why does choices=... alone not establish a database CHECK?","Does this model prevent arbitrary SQL DELETE of a review?","What must change before reviewer can identify an actual authenticated person?"], [{"title":"Django 5.2 — Constraints","url":"https://docs.djangoproject.com/en/5.2/ref/models/constraints/","kind":"documentation","purpose":"Database CheckConstraint and UniqueConstraint semantics."},{"title":"Django 5.2 — ForeignKey","url":"https://docs.djangoproject.com/en/5.2/ref/models/fields/","kind":"documentation","purpose":"Relationship descriptors and protective deletes."},{"title":"Django 5.2 — Migrations","url":"https://docs.djangoproject.com/en/5.2/topics/migrations/","kind":"documentation","purpose":"Schema history and reviewable generated migrations."}]),

  {
    "id": "django-and-api-engineering-lab-steward-api-skeleton",
    "title": "Lab: Steward API Skeleton",
    "activities": [
      {
        "id": "django-and-api-engineering-lab-steward-api-skeleton-brief",
        "title": "Steward API Skeleton Brief",
        "estimatedMinutes": 20,
        "content": {
          "type": "reading",
          "body": "Build one consistent Steward Django registry incrementally. Before adding an HTTP endpoint, verify that the existing Team, Service, Environment, directed ServiceDependency and historical ServiceReview models all have executable database evidence. Reuse the separated PostgreSQL-backed Django schema project. Do not treat the unauthenticated training URLs from earlier lessons as public APIs; verified principal and membership authorization are taught next.",
          "blocks": [
            {
              "type": "heading",
              "id": "objective",
              "text": "One domain, several independently verifiable checkpoints"
            },
            {
              "type": "paragraph",
              "text": "The canonical data design came from PostgreSQL. Django must represent it without changing its identities, relationships or constraints. The two immediately preceding lessons provide complete migrations and real negative tests for dependency edges and review history. Complete the data checkpoints below before attempting HTTP integration."
            },
            {
              "type": "heading",
              "id": "boundaries",
              "text": "What already exists and what remains"
            },
            {
              "type": "list",
              "items": [
                "Implemented and independently tested: Team/Service/Environment, staged Service.slug migrations, readiness commands, limited training queries, real generated OpenAPI in the separate Book catalogue, and Django settings/logging examples.",
                "Newly taught in complete source: ServiceDependency directional constraints and ServiceReview historical rows, each with real PostgreSQL schema and negative tests.",
                "Still to integrate: full Service list/create/detail and review create/list HTTP endpoints backed by these exact rows; schema/runtime evidence and operational behavior as one project.",
                "Not yet implemented: authenticated user, Team Membership-derived authorization, secure public registration, and immutable audit guarantees."
              ]
            },
            {
              "type": "heading",
              "id": "learning-order",
              "text": "Do not skip the transition"
            },
            {
              "type": "paragraph",
              "text": "Use the existing PostgreSQL Django schema lab as the source of truth. The prior Django examples included an independent Book tutorial and multiple separate test-only Steward projects; their file paths are examples to transfer deliberately, not proof they were already assembled in the same application. The final assembly must be verified against one coherent project before calling this module complete."
            }
          ]
        }
      },
      {
        "id": "django-and-api-engineering-lab-steward-api-skeleton-dependency-checkpoint",
        "title": "Checkpoint 1: Verify directed dependencies",
        "estimatedMinutes": 55,
        "content": {
          "type": "practical",
          "objective": "Prove the actual Steward Django registry can store directed Service dependency edges while the database rejects self-links, duplicate edges and missing targets.",
          "scenario": "The PostgreSQL-backed Steward schema project has applied registry migrations 0001–0004. The earlier dependency lesson adds 0005 and publishes all source.",
          "instructions": [
            "Confirm that registry 0004 was applied and that original Service IDs/slugs are intact; do not reconstruct the database.",
            "Execute the prior lesson's complete ServiceDependency model append, reviewed generated 0005 migration and dependency_integrity_lab.py.",
            "Record actual sqlmigrate output with source_service_id, target_service_id, foreign keys, ordered-pair uniqueness and a self-edge check.",
            "Capture both positive directions, the self/duplicate/unknown-target database rejection and PROTECT deletion outcome.",
            "Run a new Django shell and confirm the stored A→B relation exists. Explain why a three-Service cycle is still possible."
          ],
          "deliverables": [
            "Generated and applied 0005 migration",
            "Original row/owner preservation evidence",
            "Five real dependency outcomes",
            "Fresh-shell edge verification",
            "Unimplemented cycle/identity notes"
          ],
          "completionCriteria": [
            "Directed relationships and constraints are executable against real PostgreSQL.",
            "Invalid writes leave stored relations unchanged.",
            "Migration state and Python models agree.",
            "The result is not misrepresented as a secure Service dependency API."
          ]
        }
      },
      {
        "id": "django-and-api-engineering-lab-steward-api-skeleton-review-history-checkpoint",
        "title": "Checkpoint 2: Preserve multiple review events",
        "estimatedMinutes": 55,
        "content": {
          "type": "practical",
          "objective": "Record and independently verify more than one historical review for one Service, including equal-timestamp events and negative database writes.",
          "scenario": "Continue the same schema project after 0005. Reviewer values are synthetic labels, not authenticated users.",
          "instructions": [
            "Append the published ServiceReview model and generate/review/apply registry 0006; use python manage.py sqlmigrate registry 0006 to identify FK and CHECK constraints.",
            "Run the prior lesson's complete review_history_lab.py exactly once in the disposable training database.",
            "Verify that three event IDs remain for the same Service, including two events with the same reviewed_at, ordered by timestamp then ID.",
            "Record the database's rejection of invalid verdict and unknown Service, plus PROTECT deletion of a reviewed Service.",
            "Close the Python process, re-open a Django shell and verify the same three rows exist. Explain why this schema is not an immutable audit trail."
          ],
          "deliverables": [
            "Applied and reviewed 0006 migration",
            "Three-event historical record with stable identity",
            "CHECK/FK/PROTECT failure evidence",
            "Fresh-shell durable history",
            "Identity/immutability gap"
          ],
          "completionCriteria": [
            "Multiple reviews for one Service survive across processes.",
            "Actual database constraints reject invalid facts.",
            "Original Service/Dependency data remain intact.",
            "No unverifiable reviewer identity or append-only enforcement is claimed."
          ]
        }
      },
      {
        "id": "django-and-api-engineering-lab-steward-api-skeleton-build",
        "title": "Build Steward API Skeleton",
        "estimatedMinutes": 150,
        "content": {
          "type": "practical",
          "objective": "Integrate the proven Steward models into real DRF endpoints, then demonstrate contract and operational behavior in one coherent test-only application.",
          "scenario": "Start only after the two schema checkpoints are green. Work in the same already migrated Steward Django project rather than silently combining unrelated scratch installations. The remaining endpoint assembly is not independently learner-validated yet; use the named earlier source examples as reference and record any missing support before claiming completion.",
          "instructions": [
            "Inventory the actual existing registry files and migrations 0001–0006. Explain where the previously taught service serializer, command, exception handler, query scope, OpenAPI generator, settings and logging lessons can be reused, and which files must be added deliberately.",
            "Build a narrowly testable Service collection/detail API, including explicitly selected writable and read-only fields. Test one persisted creation, a second independent read, a missing record and a rejected invalid field without data changes.",
            "Add ServiceReview create/list through the actual historical model, and demonstrate that an unauthorized cross-Team write cannot be claimed blocked until Identity-backed authorization exists. Keep all interim routes isolated from public config/urls.py.",
            "Apply lifecycle and criticality filters plus deterministic pagination on a *server-selected teaching Team*, never a client-selected Team authority. Inspect executed PostgreSQL SQL and N+1 behavior rather than hand-writing a pretend query.",
            "Reuse the real readiness command for an HTTP 409 conflict and demonstrate unchanged stored Service lifecycle after rejection. Do not treat serializer validation as a replacement for domain rules.",
            "Generate the API's actual OpenAPI document and compare paths, parameters, response fields and success/failure statuses against real HTTP exchanges. Verify application logging is useful and excludes secrets.",
            "Prepare a concrete missing-prerequisite list for the next Identity module: verified principals, Team membership, object-level authorization, cross-Team visibility/revocation, and reviewer attribution."
          ],
          "deliverables": [
            "One migrated Steward Django project",
            "Actual Service and ServiceReview HTTP request/state evidence",
            "SQL count/relationship loading notes",
            "Readiness and invalid input negatives",
            "Actual schema/runtime comparison",
            "Logs without credentials",
            "Security work explicitly deferred to Identity"
          ],
          "completionCriteria": [
            "The demonstrated HTTP operations use real stored rows and match their documented response contracts.",
            "Domain constraint failures do not produce hidden writes.",
            "All test-only routes remain unpublished until Identity/permissions are implemented.",
            "Cross-project sample code is not presented as if it had already been assembled.",
            "A novice can reproduce every step; until full source and uncoached verification exist, this checkpoint must remain unvalidated."
          ]
        }
      },
      {
        "id": "django-and-api-engineering-lab-steward-api-skeleton-review",
        "title": "Django/API Module Review",
        "estimatedMinutes": 25,
        "content": {
          "type": "reflection",
          "prompt": "Trace one Service dependency request and one ServiceReview request from URL → DRF view → serializer/command → ORM → database constraint → HTTP response. Which source files and command outputs actually prove every transition? What happens for a malformed request and a correct-looking but forbidden cross-Team request? Which guarantee is implemented now and which awaits the Identity module? Identify at least one missing executable prerequisite before declaring this integration ready."
        }
      }
    ]
  },
];
